import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Product {
  id: string;
  code: string;
  name: string;
  grams: string;
  flavor: string;
  costPrice: number;
  salePrice: number;
  stock: number;
  category: string;
  totalInvested: number;
  totalEarned: number;
}

export interface InputTransaction {
  id: string;
  productId: string;
  productName: string;
  quantity: number;
  unitCost: number;
  totalCost: number;
  date: string;
  provider: string;
  invoiceId: string;
  status: 'Paid' | 'Pending';
}

export interface OutputTransaction {
  id: string;
  productId: string;
  productName: string;
  quantity: number;
  salePrice: number;
  totalSale: number;
  date: string;
  shift: string;
}

export interface DailyClosing {
  id: string;
  date: string;
  totalSold: number;
  netProfit: number;
  cogs: number; // Cost of Goods Sold
}

export interface OCRResult {
  code?: string;
  name: string;
  grams?: string;
  flavor?: string;
  costPrice: number;
  salePrice?: number;
  quantity: number;
}

import { GoogleGenAI, Type } from "@google/genai";
import { OCRResult } from "../types";

export const processTicketWithGemini = async (base64Image: string): Promise<OCRResult[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

  const prompt = `Analyze this purchase ticket/invoice image. Extract the following information for each item as a JSON array.
  Look for: Code/SKU, Name/Description, Grams (if applicable), Flavor (if applicable), Cost Price per unit, Suggested Sale Price, and Quantity purchased.
  Ensure numerical values are numbers, not strings. Use 0 if data is not found.`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: {
        parts: [
          { inlineData: { data: base64Image.split(',')[1] || base64Image, mimeType: "image/jpeg" } },
          { text: prompt }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              code: { type: Type.STRING },
              name: { type: Type.STRING },
              grams: { type: Type.STRING },
              flavor: { type: Type.STRING },
              costPrice: { type: Type.NUMBER },
              salePrice: { type: Type.NUMBER },
              quantity: { type: Type.NUMBER },
            },
            required: ["name", "costPrice", "quantity"]
          }
        }
      }
    });

    return JSON.parse(response.text || "[]");
  } catch (error) {
    console.error("Gemini OCR error:", error);
    throw new Error("Failed to process ticket image. Please check your API key and connection.");
  }
};

import { Product, InputTransaction, OutputTransaction, DailyClosing } from "../types";

// Note: In a real production scenario, this service would make fetch calls to 
// the Google Apps Script Web App URL.
// We are using localStorage to ensure "real-time" sync simulation within the browser session.

const STORAGE_KEYS = {
  PRODUCTS: 'zenith_products',
  INPUTS: 'zenith_inputs',
  OUTPUTS: 'zenith_outputs',
  CLOSINGS: 'zenith_closings'
};

const getFromStorage = <T,>(key: string, defaultValue: T): T => {
  const data = localStorage.getItem(key);
  return data ? JSON.parse(data) : defaultValue;
};

const saveToStorage = (key: string, data: any) => {
  localStorage.setItem(key, JSON.stringify(data));
};

export const dataService = {
  getProducts: (): Product[] => getFromStorage(STORAGE_KEYS.PRODUCTS, []),

  saveProduct: (product: Product) => {
    const products = dataService.getProducts();
    const index = products.findIndex(p => p.id === product.id);
    if (index >= 0) {
      products[index] = product;
    } else {
      products.push(product);
    }
    saveToStorage(STORAGE_KEYS.PRODUCTS, products);
  },

  getInputs: (): InputTransaction[] => getFromStorage(STORAGE_KEYS.INPUTS, []),

  saveInput: (transaction: InputTransaction) => {
    const inputs = dataService.getInputs();
    inputs.push(transaction);
    saveToStorage(STORAGE_KEYS.INPUTS, inputs);

    // Update product stock and investment
    const products = dataService.getProducts();
    const product = products.find(p => p.id === transaction.productId);
    if (product) {
      product.stock += transaction.quantity;
      product.totalInvested += transaction.totalCost;
      product.costPrice = transaction.unitCost; // Update current cost price
      dataService.saveProduct(product);
    }
  },

  getOutputs: (): OutputTransaction[] => getFromStorage(STORAGE_KEYS.OUTPUTS, []),

  saveOutput: (transaction: OutputTransaction) => {
    const outputs = dataService.getOutputs();
    outputs.push(transaction);
    saveToStorage(STORAGE_KEYS.OUTPUTS, outputs);

    // Update product stock and earnings
    const products = dataService.getProducts();
    const product = products.find(p => p.id === transaction.productId);
    if (product) {
      product.stock -= transaction.quantity;
      product.totalEarned += transaction.totalSale;
      dataService.saveProduct(product);
    }
  },

  getClosings: (): DailyClosing[] => getFromStorage(STORAGE_KEYS.CLOSINGS, []),

  saveClosing: (closing: DailyClosing) => {
    const closings = dataService.getClosings();
    closings.push(closing);
    saveToStorage(STORAGE_KEYS.CLOSINGS, closings);
  },

  sync: async () => {
    // Simulated sync delay
    await new Promise(r => setTimeout(r, 800));
    return { success: true, timestamp: new Date().toISOString() };
  }
};

import React, { useState, useEffect } from 'react';
import { HashRouter, Routes, Route, Link, useLocation } from 'react-router-dom';
import { 
  LayoutDashboard, 
  Package, 
  PlusCircle, 
  MinusCircle, 
  History, 
  RefreshCcw,
  Settings,
  TrendingUp,
  AlertCircle
} from 'lucide-react';
import Dashboard from './components/Dashboard';
import Inventory from './components/Inventory';
import ProductRegistration from './components/ProductRegistration';
import Restock from './components/Restock';
import DailyClosingView from './components/DailyClosingView';
import HistoryView from './components/HistoryView';

const NavItem: React.FC<{ to: string, icon: React.ReactNode, label: string }> = ({ to, icon, label }) => {
  const location = useLocation();
  const isActive = location.pathname === to;

  return (
    <Link 
      to={to} 
      className={`flex items-center space-x-3 px-4 py-3 rounded-lg transition-all ${
        isActive 
          ? 'bg-blue-600 text-white shadow-md' 
          : 'text-slate-500 hover:bg-blue-50 hover:text-blue-600'
      }`}
    >
      {icon}
      <span className="font-medium">{label}</span>
    </Link>
  );
};

const Sidebar: React.FC = () => (
  <aside className="w-64 bg-white border-r border-slate-200 flex flex-col h-screen sticky top-0">
    <div className="p-6 border-b border-slate-100">
      <div className="flex items-center space-x-2">
        <div className="bg-blue-600 p-2 rounded-lg">
          <TrendingUp className="text-white w-6 h-6" />
        </div>
        <h1 className="text-xl font-bold text-slate-800 tracking-tight">Zenith POS</h1>
      </div>
    </div>

    <nav className="flex-1 p-4 space-y-2 overflow-y-auto">
      <NavItem to="/" icon={<LayoutDashboard size={20} />} label="Dashboard" />
      <NavItem to="/inventory" icon={<Package size={20} />} label="Inventory" />
      <NavItem to="/register" icon={<PlusCircle size={20} />} label="Add Product" />
      <NavItem to="/restock" icon={<RefreshCcw size={20} />} label="Restock (Inputs)" />
      <NavItem to="/sales" icon={<MinusCircle size={20} />} label="Daily Sales (Outputs)" />
      <NavItem to="/history" icon={<History size={20} />} label="History Log" />
    </nav>

    <div className="p-4 border-t border-slate-100 bg-slate-50">
      <div className="flex items-center space-x-3 text-slate-500 px-4 py-2 hover:text-slate-800 cursor-pointer transition-colors">
        <Settings size={20} />
        <span className="text-sm font-medium">Settings</span>
      </div>
    </div>
  </aside>
);

const App: React.FC = () => {
  const [syncing, setSyncing] = useState(false);
  const [lastSync, setLastSync] = useState(new Date().toLocaleTimeString());

  const handleSync = () => {
    setSyncing(true);
    setTimeout(() => {
      setSyncing(false);
      setLastSync(new Date().toLocaleTimeString());
    }, 1200);
  };

  return (
    <HashRouter>
      <div className="flex min-h-screen bg-slate-50">
        <Sidebar />

        <main className="flex-1 overflow-x-hidden">
          <header className="bg-white border-b border-slate-200 px-8 py-4 flex justify-between items-center sticky top-0 z-10">
            <h2 className="text-lg font-semibold text-slate-700">Management Console</h2>
            <div className="flex items-center space-x-4">
              <span className="text-xs text-slate-400 font-medium">Last Sync: {lastSync}</span>
              <button 
                onClick={handleSync}
                disabled={syncing}
                className="flex items-center space-x-2 bg-blue-50 text-blue-600 px-4 py-2 rounded-lg hover:bg-blue-100 transition-colors disabled:opacity-50"
              >
                <RefreshCcw size={16} className={syncing ? 'animate-spin' : ''} />
                <span className="text-sm font-semibold">{syncing ? 'Syncing...' : 'Sync Now'}</span>
              </button>
            </div>
          </header>

          <div className="p-8 max-w-7xl mx-auto">
            <Routes>
              <Route path="/" element={<Dashboard />} />
              <Route path="/inventory" element={<Inventory />} />
              <Route path="/register" element={<ProductRegistration />} />
              <Route path="/restock" element={<Restock />} />
              <Route path="/sales" element={<DailyClosingView />} />
              <Route path="/history" element={<HistoryView />} />
            </Routes>
          </div>
        </main>
      </div>
    </HashRouter>
  );
};

export default App;

import React, { useMemo } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, Cell, LineChart, Line, Legend 
} from 'recharts';
import { DollarSign, Package, TrendingUp, AlertTriangle } from 'lucide-react';
import { dataService } from '../services/dataService';

const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6'];

const StatCard: React.FC<{ title: string, value: string, icon: React.ReactNode, color: string, subtext?: string }> = ({ title, value, icon, color, subtext }) => (
  <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex items-start justify-between">
    <div>
      <p className="text-sm font-medium text-slate-500 mb-1">{title}</p>
      <h3 className="text-2xl font-bold text-slate-800">{value}</h3>
      {subtext && <p className="text-xs text-slate-400 mt-2">{subtext}</p>}
    </div>
    <div className={`${color} p-3 rounded-xl`}>
      {icon}
    </div>
  </div>
);

const Dashboard: React.FC = () => {
  const products = dataService.getProducts();
  const outputs = dataService.getOutputs();

  const stats = useMemo(() => {
    const totalEarnings = products.reduce((acc, p) => acc + p.totalEarned, 0);
    const totalInvestment = products.reduce((acc, p) => acc + p.totalInvested, 0);
    const netProfit = totalEarnings - totalInvestment;
    const lowStockCount = products.filter(p => p.stock < 10).length;

    return { totalEarnings, totalInvestment, netProfit, lowStockCount };
  }, [products]);

  const topSellingData = useMemo(() => {
    return products
      .map(p => ({ name: p.name, sales: p.totalEarned }))
      .sort((a, b) => b.sales - a.sales)
      .slice(0, 5);
  }, [products]);

  const profitabilityData = useMemo(() => {
    return [
      { name: 'Investment', value: stats.totalInvestment },
      { name: 'Net Profit', value: Math.max(0, stats.netProfit) }
    ];
  }, [stats]);

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard 
          title="Total Earnings" 
          value={`$${stats.totalEarnings.toLocaleString()}`} 
          icon={<DollarSign className="text-blue-600" />} 
          color="bg-blue-50" 
        />
        <StatCard 
          title="Total Investment" 
          value={`$${stats.totalInvestment.toLocaleString()}`} 
          icon={<Package className="text-emerald-600" />} 
          color="bg-emerald-50" 
        />
        <StatCard 
          title="Total Profitability" 
          value={`$${stats.netProfit.toLocaleString()}`} 
          icon={<TrendingUp className="text-amber-600" />} 
          color="bg-amber-50" 
          subtext={`${((stats.netProfit / (stats.totalInvestment || 1)) * 100).toFixed(1)}% Return`}
        />
        <StatCard 
          title="Low Stock Alerts" 
          value={stats.lowStockCount.toString()} 
          icon={<AlertTriangle className="text-red-600" />} 
          color="bg-red-50" 
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm">
          <h3 className="text-lg font-bold text-slate-800 mb-6">Top Selling Products</h3>
          <div className="h-80">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={topSellingData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 12}} />
                <YAxis axisLine={false} tickLine={false} tick={{fontSize: 12}} />
                <Tooltip 
                  cursor={{fill: '#f8fafc'}}
                  contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
                />
                <Bar dataKey="sales" fill="#3b82f6" radius={[4, 4, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm">
          <h3 className="text-lg font-bold text-slate-800 mb-6">Earnings vs Investment</h3>
          <div className="h-80 flex items-center justify-center">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={profitabilityData}
                  cx="50%"
                  cy="50%"
                  innerRadius={80}
                  outerRadius={120}
                  paddingAngle={5}
                  dataKey="value"
                >
                  {profitabilityData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                  ))}
                </Pie>
                <Tooltip />
                <Legend verticalAlign="bottom" height={36}/>
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm">
        <h3 className="text-lg font-bold text-slate-800 mb-4 flex items-center space-x-2">
          <AlertCircle className="text-blue-500" size={20} />
          <span>Strategic Focus Recommendations</span>
        </h3>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mt-4">
          {products.filter(p => (p.salePrice - p.costPrice) / p.salePrice > 0.4).slice(0, 3).map(p => (
            <div key={p.id} className="p-4 rounded-xl bg-blue-50 border border-blue-100">
              <span className="text-xs font-bold text-blue-600 uppercase tracking-wider">High Margin</span>
              <h4 className="font-semibold text-slate-800 mt-1">{p.name}</h4>
              <p className="text-sm text-slate-600 mt-1">
                Margin: {(((p.salePrice - p.costPrice) / p.salePrice) * 100).toFixed(0)}%
              </p>
              <p className="text-xs text-slate-400 mt-2">Recommended: Boost marketing for this item to maximize profitability.</p>
            </div>
          ))}
          {products.length === 0 && <p className="text-slate-500 italic col-span-3">Add products to see intelligent recommendations.</p>}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useRef } from 'react';
import { Camera, Upload, Check, AlertCircle, Loader2 } from 'lucide-react';
import { processTicketWithGemini } from '../services/geminiService';
import { dataService } from '../services/dataService';

const ProductRegistration: React.FC = () => {
  const [isLoading, setIsLoading] = useState(false);
  const [success, setSuccess] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState({
    code: '',
    name: '',
    grams: '',
    flavor: '',
    costPrice: '',
    salePrice: '',
    stock: '',
    category: 'General'
  });

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsLoading(true);
    setError(null);

    const reader = new FileReader();
    reader.onload = async (event) => {
      try {
        const base64 = event.target?.result as string;
        const results = await processTicketWithGemini(base64);

        if (results.length > 0) {
          const item = results[0]; // Take first item for simple registration
          setFormData({
            code: item.code || '',
            name: item.name,
            grams: item.grams || '',
            flavor: item.flavor || '',
            costPrice: item.costPrice.toString(),
            salePrice: (item.salePrice || item.costPrice * 1.3).toFixed(2),
            stock: item.quantity.toString(),
            category: 'General'
          });
        }
      } catch (err: any) {
        setError(err.message || 'Error processing OCR');
      } finally {
        setIsLoading(false);
      }
    };
    reader.readAsDataURL(file);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const product = {
      id: Math.random().toString(36).substr(2, 9),
      code: formData.code,
      name: formData.name,
      grams: formData.grams,
      flavor: formData.flavor,
      costPrice: parseFloat(formData.costPrice),
      salePrice: parseFloat(formData.salePrice),
      stock: parseInt(formData.stock),
      category: formData.category,
      totalInvested: parseFloat(formData.costPrice) * parseInt(formData.stock),
      totalEarned: 0
    };

    dataService.saveProduct(product);
    setSuccess(true);
    setTimeout(() => setSuccess(false), 3000);
    setFormData({ code: '', name: '', grams: '', flavor: '', costPrice: '', salePrice: '', stock: '', category: 'General' });
  };

  return (
    <div className="max-w-2xl mx-auto animate-in fade-in slide-in-from-bottom-4 duration-500">
      <div className="flex items-center justify-between mb-8">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">New Product</h2>
          <p className="text-slate-500">Register individual products or use AI to extract details from a photo.</p>
        </div>
        <button 
          onClick={() => fileInputRef.current?.click()}
          disabled={isLoading}
          className="flex items-center space-x-2 bg-slate-800 text-white px-6 py-3 rounded-xl hover:bg-slate-700 transition-all shadow-lg active:scale-95 disabled:opacity-50"
        >
          {isLoading ? <Loader2 className="animate-spin" size={20} /> : <Camera size={20} />}
          <span className="font-semibold">OCR Photo</span>
        </button>
        <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileUpload} />
      </div>

      {error && (
        <div className="mb-6 p-4 bg-red-50 border border-red-100 text-red-600 rounded-xl flex items-center space-x-2">
          <AlertCircle size={20} />
          <span>{error}</span>
        </div>
      )}

      <form onSubmit={handleSubmit} className="bg-white p-8 rounded-2xl border border-slate-200 shadow-xl space-y-6">
        <div className="grid grid-cols-2 gap-6">
          <div className="space-y-2">
            <label className="text-sm font-bold text-slate-700">Product Code</label>
            <input 
              required
              value={formData.code}
              onChange={(e) => setFormData({...formData, code: e.target.value})}
              className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 focus:outline-none transition-all"
              placeholder="e.g. 750100200..."
            />
          </div>
          <div className="space-y-2">
            <label className="text-sm font-bold text-slate-700">Category</label>
            <select 
              value={formData.category}
              onChange={(e) => setFormData({...formData, category: e.target.value})}
              className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 focus:outline-none transition-all"
            >
              <option>General</option>
              <option>Snacks</option>
              <option>Drinks</option>
              <option>Grains</option>
            </select>
          </div>
        </div>

        <div className="space-y-2">
          <label className="text-sm font-bold text-slate-700">Full Product Name</label>
          <input 
            required
            value={formData.name}
            onChange={(e) => setFormData({...formData, name: e.target.value})}
            className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 focus:outline-none transition-all"
            placeholder="e.g. Coca-Cola Original"
          />
        </div>

        <div className="grid grid-cols-2 gap-6">
          <div className="space-y-2">
            <label className="text-sm font-bold text-slate-700">Size (Grams/ml)</label>
            <input 
              value={formData.grams}
              onChange={(e) => setFormData({...formData, grams: e.target.value})}
              className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 focus:outline-none transition-all"
              placeholder="e.g. 600ml"
            />
          </div>
          <div className="space-y-2">
            <label className="text-sm font-bold text-slate-700">Flavor / Variant</label>
            <input 
              value={formData.flavor}
              onChange={(e) => setFormData({...formData, flavor: e.target.value})}
              className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 focus:outline-none transition-all"
              placeholder="e.g. Classic"
            />
          </div>
        </div>

        <div className="grid grid-cols-3 gap-6 pt-4 border-t border-slate-100">
          <div className="space-y-2">
            <label className="text-sm font-bold text-slate-700">Cost Price</label>
            <div className="relative">
              <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400">$</span>
              <input 
                required
                type="number" step="0.01"
                value={formData.costPrice}
                onChange={(e) => setFormData({...formData, costPrice: e.target.value})}
                className="w-full pl-8 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 focus:outline-none transition-all"
              />
            </div>
          </div>
          <div className="space-y-2">
            <label className="text-sm font-bold text-slate-700">Sale Price</label>
            <div className="relative">
              <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400">$</span>
              <input 
                required
                type="number" step="0.01"
