import React, { useState, useRef } from 'react';
import { ShoppingCart, Search, Plus, Trash2, Camera, Loader2, AlertCircle } from 'lucide-react';
import { dataService } from '../services/dataService';
import { processTicketWithGemini } from '../services/geminiService';
import { Product } from '../types';

const Restock: React.FC = () => {
  const [cart, setCart] = useState<any[]>([]);
  const [provider, setProvider] = useState('');
  const [invoiceId, setInvoiceId] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const products = dataService.getProducts();
  const fileInputRef = useRef<HTMLInputElement>(null);

  const filteredProducts = products.filter(p => 
    p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    p.code.includes(searchTerm)
  );

  const addToCart = (product: Product, quantity: number = 1) => {
    const existing = cart.find(item => item.productId === product.id);
    if (existing) {
      setCart(cart.map(item => 
        item.productId === product.id 
          ? { ...item, quantity: item.quantity + quantity, totalCost: (item.quantity + quantity) * item.unitCost }
          : item
      ));
    } else {
      setCart([...cart, {
        productId: product.id,
        productName: product.name,
        quantity,
        unitCost: product.costPrice,
        totalCost: product.costPrice * quantity
      }]);
    }
  };

  const handleOCR = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsLoading(true);
    const reader = new FileReader();
    reader.onload = async (event) => {
      try {
        const base64 = event.target?.result as string;
        const results = await processTicketWithGemini(base64);

        results.forEach(result => {
          const match = products.find(p => p.code === result.code || p.name.toLowerCase().includes(result.name.toLowerCase()));
          if (match) {
            addToCart(match, result.quantity);
          } else {
            // Future feature: create new product from OCR if not found
            console.log("Product not found in db:", result.name);
          }
        });
      } catch (err) {
        alert("OCR failed to process this ticket.");
      } finally {
        setIsLoading(false);
      }
    };
    reader.readAsDataURL(file);
  };

  const completeRestock = () => {
    if (cart.length === 0) return;

    cart.forEach(item => {
      dataService.saveInput({
        id: Math.random().toString(36).substr(2, 9),
        productId: item.productId,
        productName: item.productName,
        quantity: item.quantity,
        unitCost: item.unitCost,
        totalCost: item.totalCost,
        date: new Date().toISOString(),
        provider: provider || 'Standard Provider',
        invoiceId: invoiceId || 'INV-' + Date.now().toString().slice(-6),
        status: 'Paid'
      });
    });

    setCart([]);
    setProvider('');
    setInvoiceId('');
    alert("Restock logged successfully!");
  };

  const grandTotal = cart.reduce((acc, item) => acc + item.totalCost, 0);

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 animate-in fade-in slide-in-from-right-4 duration-500">
      <div className="lg:col-span-2 space-y-6">
        <div className="flex items-center justify-between">
          <h2 className="text-2xl font-bold text-slate-800">Restock Module</h2>
          <button 
            onClick={() => fileInputRef.current?.click()}
            className="flex items-center space-x-2 bg-emerald-600 text-white px-4 py-2 rounded-lg hover:bg-emerald-700 transition-all"
          >
            {isLoading ? <Loader2 className="animate-spin" size={18} /> : <Camera size={18} />}
            <span className="text-sm font-semibold">Bulk OCR Entry</span>
          </button>
          <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleOCR} />
        </div>

        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm space-y-4">
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input 
              type="text" 
              placeholder="Search products to add..." 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-10 pr-4 py-2 bg-slate-50 border border-slate-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition-all"
            />
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-3 max-h-96 overflow-y-auto pr-2">
            {filteredProducts.map(p => (
              <div key={p.id} className="p-3 border border-slate-100 rounded-xl hover:bg-blue-50 transition-colors flex items-center justify-between group">
                <div>
                  <h4 className="font-bold text-slate-800 text-sm">{p.name}</h4>
                  <p className="text-xs text-slate-400">Stock: {p.stock} | Cost: ${p.costPrice}</p>
                </div>
                <button 
                  onClick={() => addToCart(p)}
                  className="p-2 bg-blue-50 text-blue-600 rounded-lg group-hover:bg-blue-600 group-hover:text-white transition-all"
                >
                  <Plus size={16} />
                </button>
              </div>
            ))}
          </div>
        </div>
      </div>

      <div className="lg:col-span-1">
        <div className="bg-white rounded-2xl border border-slate-200 shadow-xl overflow-hidden flex flex-col h-full sticky top-24">
          <div className="p-6 bg-slate-800 text-white">
            <h3 className="text-lg font-bold flex items-center space-x-2">
              <ShoppingCart size={20} />
              <span>Purchase List</span>
            </h3>
          </div>

          <div className="p-6 flex-1 overflow-y-auto space-y-4 max-h-[400px]">
            {cart.map(item => (
              <div key={item.productId} className="flex items-center justify-between py-2 border-b border-slate-100">
                <div className="flex-1">
                  <p className="font-semibold text-slate-800 text-sm">{item.productName}</p>
                  <p className="text-xs text-slate-400">{item.quantity} units @ ${item.unitCost.toFixed(2)}</p>
                </div>
                <div className="text-right flex items-center space-x-3">
                  <span className="font-bold text-slate-700">${item.totalCost.toFixed(2)}</span>
                  <button 
                    onClick={() => setCart(cart.filter(i => i.productId !== item.productId))}
                    className="text-red-400 hover:text-red-600 p-1"
