          >
            Day
          </button>
          <button 
            onClick={() => setShift('Night')}
            className={`px-4 py-1.5 rounded-lg text-sm font-bold transition-all ${shift === 'Night' ? 'bg-white shadow text-blue-600' : 'text-slate-500'}`}
          >
            Night
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm space-y-4">
          <h3 className="font-bold text-slate-700 border-b border-slate-100 pb-2">Quick Add Sale</h3>
          <div className="space-y-4">
            <div className="space-y-2">
              <label className="text-xs font-bold text-slate-400 uppercase">Product</label>
              <select 
                onChange={(e) => {
                  if (e.target.value) addSaleItem(e.target.value, 1);
                  e.target.value = "";
                }}
