                  <option key={p.id} value={p.id}>{p.name} - ${p.salePrice} (Stock: {p.stock})</option>
                ))}
              </select>
            </div>

            <div className="pt-4 space-y-2 overflow-y-auto max-h-60">
              {salesItems.map((item, idx) => (
                <div key={idx} className="flex items-center justify-between p-3 bg-blue-50 rounded-xl border border-blue-100">
                  <div className="flex items-center space-x-3">
                    <div className="bg-blue-600 text-white w-6 h-6 rounded-full flex items-center justify-center text-xs font-bold">
