                </div>
              ))}
              {salesItems.length === 0 && <p className="text-slate-400 text-center py-6 italic text-sm">Add products to begin closing.</p>}
            </div>
          </div>
        </div>

        <div className="bg-slate-800 text-white p-8 rounded-2xl shadow-xl space-y-6 flex flex-col justify-between">
