/**
 * Creates necessary sheets and headers if they don't exist.
 */
function setupSheet() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheets = {
    "Products": ["id", "code", "name", "grams", "flavor", "costPrice", "salePrice", "stock", "category", "totalInvested", "totalEarned"],
    "Inputs": ["id", "productId", "productName", "quantity", "unitCost", "totalCost", "date", "provider", "invoiceId", "status"],
    "Outputs": ["id", "productId", "productName", "quantity", "salePrice", "totalSale", "date", "shift"],
    "Closings": ["id", "date", "totalSold", "netProfit", "cogs"]
  };

  for (let name in sheets) {
    let sheet = ss.getSheetByName(name);
    if (!sheet) {
      sheet = ss.insertSheet(name);
      sheet.appendRow(sheets[name]);
      sheet.getRange(1, 1, 1, sheets[name].length)
           .setFontWeight("bold")
           .setBackground("#f3f4f6")
           .setBorder(true, true, true, true, true, true);
      sheet.setFrozenRows(1);
    }
  }
  return "Sistema inicializado correctamente.";
}

function getProducts() {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("Products");
  if (!sheet) return [];
  const data = sheet.getDataRange().getValues();
  const headers = data[0];
  return data.slice(1).map(row => {
    let obj = {};
    headers.forEach((h, i) => obj[h] = row[i]);
    return obj;
  });
}

function saveProduct(product) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  let sheet = ss.getSheetByName("Products");
  if (!sheet) { setupSheet(); sheet = ss.getSheetByName("Products"); }

  const data = sheet.getDataRange().getValues();
  const headers = data[0];
  const idIndex = headers.indexOf("id");

  let rowIndex = -1;
  for (let i = 1; i < data.length; i++) {
    if (data[i][idIndex] == product.id) {
      rowIndex = i + 1;
      break;
    }
  }

  const rowData = headers.map(h => product[h] !== undefined ? product[h] : "");
  if (rowIndex > 0) {
    sheet.getRange(rowIndex, 1, 1, headers.length).setValues([rowData]);
  } else {
    sheet.appendRow(rowData);
  }
  return true;
}

function addInput(transaction) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheetByName("Inputs") || ss.insertSheet("Inputs");
  const headers = ["id", "productId", "productName", "quantity", "unitCost", "totalCost", "date", "provider", "invoiceId", "status"];

  if (sheet.getLastRow() === 0) sheet.appendRow(headers);
  sheet.appendRow(headers.map(h => transaction[h]));

  updateStock(transaction.productId, transaction.quantity, transaction.totalCost, 0, transaction.unitCost);
  return true;
}

function addOutput(transaction) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheetByName("Outputs") || ss.insertSheet("Outputs");
  const headers = ["id", "productId", "productName", "quantity", "salePrice", "totalSale", "date", "shift"];

  if (sheet.getLastRow() === 0) sheet.appendRow(headers);
  sheet.appendRow(headers.map(h => transaction[h]));

  updateStock(transaction.productId, -transaction.quantity, 0, transaction.totalSale);
  return true;
}

function updateStock(productId, stockChange, investmentChange, earningsChange, newCostPrice) {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("Products");
  if (!sheet) return;
  const data = sheet.getDataRange().getValues();
  const headers = data[0];
  const idIdx = headers.indexOf("id");
  const stockIdx = headers.indexOf("stock");
  const invIdx = headers.indexOf("totalInvested");
  const earnIdx = headers.indexOf("totalEarned");
  const costIdx = headers.indexOf("costPrice");

  for (let i = 1; i < data.length; i++) {
    if (data[i][idIdx] == productId) {
      const row = i + 1;
      const currentStock = Number(data[i][stockIdx]) || 0;
      const currentInv = Number(data[i][invIdx]) || 0;
      const currentEarn = Number(data[i][earnIdx]) || 0;

      sheet.getRange(row, stockIdx + 1).setValue(currentStock + stockChange);
      sheet.getRange(row, invIdx + 1).setValue(currentInv + (investmentChange || 0));
      sheet.getRange(row, earnIdx + 1).setValue(currentEarn + (earningsChange || 0));
      if (newCostPrice) {
        sheet.getRange(row, costIdx + 1).setValue(newCostPrice);
      }
      break;
    }
  }
}

function saveClosing(closing) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheetByName("Closings") || ss.insertSheet("Closings");
  const headers = ["id", "date", "totalSold", "netProfit", "cogs"];

