/**
 * Checks if we are running inside the Google Apps Script environment.
 */
// Fix: Access 'google' via window object to avoid TypeScript "Cannot find name 'google'" error
const isGasEnv = () => {
  const g = (window as any).google;
  return typeof g !== 'undefined' && g.script && g.script.run;
};

/**
 * Helper to call Google Apps Script functions as Promises with Fallback for local development
 */
const runGas = (functionName: string, ...args: any[]): Promise<any> => {
  const google = (window as any).google;
  if (isGasEnv()) {
    return new Promise((resolve, reject) => {
      google.script.run
        .withSuccessHandler(resolve)
        .withFailureHandler(reject)[functionName](...args);
    });
  } else {
    console.warn(`[Zenith POS] Global 'google' object not found. Function '${functionName}' executed in Mock Mode.`);
    return mockHandler(functionName, args);
  }
};

/**
 * Mock Handler for local testing (localStorage)
 */
const mockHandler = async (fn: string, args: any[]): Promise<any> => {
  const getStorage = (key: string) => JSON.parse(localStorage.getItem(key) || '[]');
  const setStorage = (key: string, data: any) => localStorage.setItem(key, JSON.stringify(data));

  switch (fn) {
    case 'getProducts': return getStorage('zenith_products');
    case 'getInputs': return getStorage('zenith_inputs');
    case 'getOutputs': return getStorage('zenith_outputs');
    case 'getClosings': return getStorage('zenith_closings');
    case 'setupSheet': return "Modo Simulación: Tablas creadas en almacenamiento local.";
    case 'saveProduct': 
      const p = args[0];
      const products = getStorage('zenith_products');
      const pIdx = products.findIndex((x: any) => x.id === p.id);
      if (pIdx > -1) products[pIdx] = p; else products.push(p);
      setStorage('zenith_products', products);
      return true;
    case 'addInput':
      const input = args[0];
      const inputs = getStorage('zenith_inputs');
      inputs.push(input);
      setStorage('zenith_inputs', inputs);
      // Mock stock update logic
      const prodsI = getStorage('zenith_products');
      const prodI = prodsI.find((x: any) => x.id === input.productId);
      if (prodI) {
        prodI.stock = (prodI.stock || 0) + input.quantity;
        prodI.totalInvested = (prodI.totalInvested || 0) + input.totalCost;
        setStorage('zenith_products', prodsI);
      }
      return true;
    case 'addOutput':
      const output = args[0];
      const outputs = getStorage('zenith_outputs');
      outputs.push(output);
      setStorage('zenith_outputs', outputs);
      // Mock stock update logic
      const prodsO = getStorage('zenith_products');
      const prodO = prodsO.find((x: any) => x.id === output.productId);
      if (prodO) {
        prodO.stock = (prodO.stock || 0) - output.quantity;
        prodO.totalEarned = (prodO.totalEarned || 0) + output.totalSale;
        setStorage('zenith_products', prodsO);
      }
      return true;
    case 'saveClosing':
      const closing = args[0];
      const closings = getStorage('zenith_closings');
      closings.push(closing);
      setStorage('zenith_closings', closings);
      return true;
    default: return null;
  }
};

export const dataService = {
  _products: [] as Product[],
  _inputs: [] as InputTransaction[],
  _outputs: [] as OutputTransaction[],
  _closings: [] as DailyClosing[],

  async fetchAll() {
    try {
      // Use Promise.all for faster initial load
      const [products, inputs, outputs, closings] = await Promise.all([
        runGas('getProducts'),
        runGas('getInputs'),
        runGas('getOutputs'),
        runGas('getClosings')
      ]);

      this._products = products || [];
      this._inputs = inputs || [];
      this._outputs = outputs || [];
      this._closings = closings || [];
    } catch (e) {
      console.error("Error fetching data:", e);
    }
  },

  getProducts(): Product[] { return this._products; },
  getInputs(): InputTransaction[] { return this._inputs; },
  getOutputs(): OutputTransaction[] { return this._outputs; },
  getClosings(): DailyClosing[] { return this._closings; },

  async saveProduct(product: Product) {
    await runGas('saveProduct', product);
    await this.fetchAll();
  },

  async saveInput(transaction: InputTransaction) {
    await runGas('addInput', transaction);
    await this.fetchAll();
  },

  async saveOutput(transaction: OutputTransaction) {
    await runGas('addOutput', transaction);
    await this.fetchAll();
  },

  async saveClosing(closing: DailyClosing) {
    await runGas('saveClosing', closing);
    await this.fetchAll();
  },

  async setup() {
    const msg = await runGas('setupSheet');
    await this.fetchAll();
    return msg;
  },

  async sync() {
    await this.fetchAll();
    return { success: true, timestamp: new Date().toISOString() };
  }
};

