function setupSheet() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheets = {
    "Products": ["id", "code", "name", "grams", "flavor", "costPrice", "salePrice", "stock", "category", "provider", "totalInvested", "totalEarned"],
    "Inputs": ["id", "productId", "productName", "quantity", "unitCost", "totalCost", "date", "provider", "invoiceId", "status"],
    "Outputs": ["id", "productId", "productName", "quantity", "salePrice", "totalSale", "date", "shift"],
    "Closings": ["id", "date", "totalSold", "netProfit", "cogs"],
    "PriceHistory": ["id", "productId", "productName", "field", "oldValue", "newValue", "date"]
  };

  for (let name in sheets) {
    let sheet = ss.getSheetByName(name);
    if (!sheet) {
      sheet = ss.insertSheet(name);
      sheet.appendRow(sheets[name]);
      sheet.getRange(1, 1, 1, sheets[name].length)
           .setFontWeight("bold")
           .setBackground("#f3f4f6")
           .setBorder(true, true, true, true, true, true);
      sheet.setFrozenRows(1);
    }
  }
  return "Estructura de tablas actualizada correctamente.";
}

function getProducts() {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("Products");
  if (!sheet) return [];
  const data = sheet.getDataRange().getValues();
  const headers = data[0];
  return data.slice(1).map(row => {
    let obj = {};
    headers.forEach((h, i) => obj[h] = row[i]);
    return obj;
  });
}

function saveProduct(product) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  let sheet = ss.getSheetByName("Products");
  if (!sheet) { setupSheet(); sheet = ss.getSheetByName("Products"); }

  const data = sheet.getDataRange().getValues();
  const headers = data[0];
  const idIndex = headers.indexOf("id");

  let rowIndex = -1;
  let oldProduct = null;

  for (let i = 1; i < data.length; i++) {
    if (data[i][idIndex] == product.id) {
      rowIndex = i + 1;
      oldProduct = {};
      headers.forEach((h, idx) => oldProduct[h] = data[i][idx]);
      break;
    }
  }

  // Audit Log: Check for changes in key fields
  if (oldProduct) {
    const fieldsToTrack = ["costPrice", "salePrice", "grams", "flavor", "name"];
    fieldsToTrack.forEach(field => {
      if (oldProduct[field] != product[field]) {
        logPriceChange(product.id, product.name, field, oldProduct[field], product[field]);
      }
    });
  }

  const rowData = headers.map(h => product[h] !== undefined ? product[h] : "");
  if (rowIndex > 0) {
    sheet.getRange(rowIndex, 1, 1, headers.length).setValues([rowData]);
  } else {
    sheet.appendRow(rowData);
  }
  return true;
}

function logPriceChange(productId, productName, field, oldValue, newValue) {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("PriceHistory");
  if (!sheet) return;
  sheet.appendRow([
    Utilities.getUuid(),
    productId,
    productName,
    field,
    oldValue,
    newValue,
    new Date().toISOString()
  ]);
}

function deleteProduct(productId) {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("Products");
  if (!sheet) return false;
  const data = sheet.getDataRange().getValues();
  const idIndex = data[0].indexOf("id");

  for (let i = 1; i < data.length; i++) {
    if (data[i][idIndex] == productId) {
      sheet.deleteRow(i + 1);
      return true;
    }
  }
  return false;
}

function getPriceHistory() {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("PriceHistory");
  if (!sheet) return [];
  const data = sheet.getDataRange().getValues();
  const headers = data[0];
  return data.slice(1).map(row => {
    let obj = {};
    headers.forEach((h, i) => obj[h] = row[i]);
    return obj;
  });
}

