function updateStock(pId, sC, iC, eC, nC) { let s = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("Products"); let d = s.getDataRange().getValues(); let h = d[0]; for(let i=1; i<d.length; i++) { if(d[i][h.indexOf("id")] == pId) { let r = i+1; s.getRange(r, h.indexOf("stock")+1).setValue(Number(d[i][h.indexOf("stock")]) + sC); s.getRange(r, h.indexOf("totalInvested")+1).setValue(Number(d[i][h.indexOf("totalInvested")]) + (iC||0)); s.getRange(r, h.indexOf("totalEarned")+1).setValue(Number(d[i][h.indexOf("totalEarned")]) + (eC||0)); if(nC) s.getRange(r, h.indexOf("costPrice")+1).setValue(nC); break; } } }

