function setupSheet() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheets = {
    "Products": ["id", "code", "name", "grams", "flavor", "costPrice", "salePrice", "stock", "category", "provider", "totalInvested", "totalEarned"],
    "Inputs": ["id", "productId", "productName", "quantity", "unitCost", "totalCost", "date", "provider", "invoiceId", "status"],
    "Outputs": ["id", "productId", "productName", "quantity", "salePrice", "totalSale", "date", "shift"],
    "Closings": ["id", "date", "totalSold", "netProfit", "cogs"],
    "PriceHistory": ["id", "productId", "productName", "field", "oldValue", "newValue", "date"],
    "PurchaseNotes": ["id", "date", "provider", "totalAmount", "status", "detailsJson"]
  };

  for (let name in sheets) {
    let sheet = ss.getSheetByName(name);
    if (!sheet) {
      sheet = ss.insertSheet(name);
      sheet.appendRow(sheets[name]);
      sheet.getRange(1, 1, 1, sheets[name].length)
           .setFontWeight("bold")
           .setBackground("#f3f4f6")
           .setBorder(true, true, true, true, true, true);
      sheet.setFrozenRows(1);
    }
  }
  return "Estructura de tablas actualizada correctamente.";
}

function getProducts() {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("Products");
  if (!sheet) return [];
  const data = sheet.getDataRange().getValues();
  const headers = data[0];
  return data.slice(1).map(row => {
    let obj = {};
    headers.forEach((h, i) => obj[h] = row[i]);
    return obj;
  });
}

function saveProduct(product) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  let sheet = ss.getSheetByName("Products");
  if (!sheet) { setupSheet(); sheet = ss.getSheetByName("Products"); }

  const data = sheet.getDataRange().getValues();
  const headers = data[0];
  const idIndex = headers.indexOf("id");

  let rowIndex = -1;
  let oldProduct = null;

  for (let i = 1; i < data.length; i++) {
    if (data[i][idIndex] == product.id) {
      rowIndex = i + 1;
      oldProduct = {};
      headers.forEach((h, idx) => oldProduct[h] = data[i][idx]);
      break;
    }
  }

  if (oldProduct) {
    const fieldsToTrack = ["costPrice", "salePrice", "grams", "flavor", "name"];
    fieldsToTrack.forEach(field => {
      if (oldProduct[field] != product[field]) {
        logPriceChange(product.id, product.name, field, oldProduct[field], product[field]);
      }
    });
  }

  const rowData = headers.map(h => product[h] !== undefined ? product[h] : "");
  if (rowIndex > 0) {
    sheet.getRange(rowIndex, 1, 1, headers.length).setValues([rowData]);
  } else {
    sheet.appendRow(rowData);
  }
  return true;
}

function logPriceChange(productId, productName, field, oldValue, newValue) {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("PriceHistory");
  if (!sheet) return;
  sheet.appendRow([Utilities.getUuid(), productId, productName, field, oldValue, newValue, new Date().toISOString()]);
}

function deleteProduct(productId) {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("Products");
  if (!sheet) return false;
  const data = sheet.getDataRange().getValues();
  const idIndex = data[0].indexOf("id");
  for (let i = 1; i < data.length; i++) {
    if (data[i][idIndex] == productId) {
      sheet.deleteRow(i + 1);
      return true;
    }
  }
  return false;
}

function saveRestockNote(note) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const noteSheet = ss.getSheetByName("PurchaseNotes") || ss.insertSheet("PurchaseNotes");
  const headers = ["id", "date", "provider", "totalAmount", "status", "detailsJson"];

  if (noteSheet.getLastRow() === 0) noteSheet.appendRow(headers);
  noteSheet.appendRow(headers.map(h => note[h]));

  const details = JSON.parse(note.detailsJson);
  details.forEach(item => {
    updateStock(item.productId, item.quantity, item.totalCost, 0, item.unitCost);
    // Also log in Inputs for compatibility
    addInput({
      id: Utilities.getUuid(),
      productId: item.productId,
      productName: item.productName,
      quantity: item.quantity,
      unitCost: item.unitCost,
      totalCost: item.totalCost,
      date: note.date,
      provider: note.provider,
      invoiceId: note.id,
      status: note.status
    });
  });
  return true;
}

function getPurchaseNotes() {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("PurchaseNotes");
  if (!sheet) return [];
  const data = sheet.getDataRange().getValues();
  const headers = data[0];
  return data.slice(1).map(row => {
    let obj = {};
    headers.forEach((h, i) => obj[h] = row[i]);
    return obj;
  });
}

function updateNoteStatus(noteId, newStatus) {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("PurchaseNotes");
  if (!sheet) return false;
  const data = sheet.getDataRange().getValues();
  const idIndex = data[0].indexOf("id");
  const statusIndex = data[0].indexOf("status");

  for (let i = 1; i < data.length; i++) {
    if (data[i][idIndex] == noteId) {
      sheet.getRange(i + 1, statusIndex + 1).setValue(newStatus);
      return true;
    }
  }
  return false;
}

function getPriceHistory() {
  const s = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("PriceHistory");
  return s ? s.getDataRange().getValues().slice(1).map(r => {
    let o = {}; s.getDataRange().getValues()[0].forEach((h, idx) => o[h] = r[idx]);
    return o;
  }) : [];
}

function getInputs() { const s = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("Inputs"); return s ? s.getDataRange().getValues().slice(1).map(r => { let o = {}; s.getDataRange().getValues()[0].forEach((h, idx) => o[h] = r[idx]); return o; }) : []; }
function getOutputs() { const s = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("Outputs"); return s ? s.getDataRange().getValues().slice(1).map(r => { let o = {}; s.getDataRange().getValues()[0].forEach((h, idx) => o[h] = r[idx]); return o; }) : []; }
function getClosings() { const s = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("Closings"); return s ? s.getDataRange().getValues().slice(1).map(r => { let o = {}; s.getDataRange().getValues()[0].forEach((h, idx) => o[h] = r[idx]); return o; }) : []; }
function saveClosing(c) { const s = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("Closings"); s.appendRow(["id", "date", "totalSold", "netProfit", "cogs"].map(h => c[h])); return true; }
function addInput(t) { const s = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("Inputs") || SpreadsheetApp.getActiveSpreadsheet().insertSheet("Inputs"); s.appendRow(["id", "productId", "productName", "quantity", "unitCost", "totalCost", "date", "provider", "invoiceId", "status"].map(h => t[h])); return true; }
function addOutput(t) { SpreadsheetApp.getActiveSpreadsheet().getSheetByName("Outputs").appendRow(["id", "productId", "productName", "quantity", "salePrice", "totalSale", "date", "shift"].map(h => t[h])); updateStock(t.productId, -t.quantity, 0, t.totalSale); return true; }

function updateStock(pId, sC, iC, eC, nC) {
  let s = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("Products");
  let d = s.getDataRange().getValues();
  let h = d[0];
  for(let i=1; i<d.length; i++) {
    if(d[i][h.indexOf("id")] == pId) {
      let r = i+1;
      s.getRange(r, h.indexOf("stock")+1).setValue(Number(d[i][h.indexOf("stock")]) + sC);
      s.getRange(r, h.indexOf("totalInvested")+1).setValue(Number(d[i][h.indexOf("totalInvested")]) + (iC||0));
      s.getRange(r, h.indexOf("totalEarned")+1).setValue(Number(d[i][h.indexOf("totalEarned")]) + (eC||0));
      if(nC) s.getRange(r, h.indexOf("costPrice")+1).setValue(nC);
      break;
    }
  }
}

import { Product, InputTransaction, OutputTransaction, DailyClosing, PriceHistory, PurchaseNote } from "../types";

const isGasEnv = () => {
  const g = (window as any).google;
  return typeof g !== 'undefined' && g.script && g.script.run;
};

const runGas = (functionName: string, ...args: any[]): Promise<any> => {
  const google = (window as any).google;
  if (isGasEnv()) {
    return new Promise((resolve, reject) => {
      google.script.run
        .withSuccessHandler(resolve)
        .withFailureHandler(reject)[functionName](...args);
    });
  } else {
    return mockHandler(functionName, args);
  }
};

const mockHandler = async (fn: string, args: any[]): Promise<any> => {
  const getStorage = (key: string) => JSON.parse(localStorage.getItem(key) || '[]');
  const setStorage = (key: string, data: any) => localStorage.setItem(key, JSON.stringify(data));

  switch (fn) {
    case 'getProducts': return getStorage('zenith_products');
    case 'getInputs': return getStorage('zenith_inputs');
    case 'getOutputs': return getStorage('zenith_outputs');
    case 'getClosings': return getStorage('zenith_closings');
    case 'getPriceHistory': return getStorage('zenith_price_history');
    case 'getPurchaseNotes': return getStorage('zenith_purchase_notes');
    case 'deleteProduct':
      const id = args[0];
      const prods = getStorage('zenith_products');
      setStorage('zenith_products', prods.filter((p: any) => p.id !== id));
      return true;
    case 'saveProduct': 
      const p = args[0];
      const products = getStorage('zenith_products');
      const pIdx = products.findIndex((x: any) => x.id === p.id);
      if (pIdx > -1) products[pIdx] = p; else products.push(p);
      setStorage('zenith_products', products);
      return true;
    case 'saveRestockNote':
      const note = args[0];
      const notes = getStorage('zenith_purchase_notes');
      notes.push(note);
      setStorage('zenith_purchase_notes', notes);
      // Logic for stock updates is done in fetchAll via re-fetching
      return true;
    case 'updateNoteStatus':
      const [nId, nStat] = args;
      const allNotes = getStorage('zenith_purchase_notes');
      const foundIdx = allNotes.findIndex((n: any) => n.id === nId);
      if (foundIdx > -1) allNotes[foundIdx].status = nStat;
      setStorage('zenith_purchase_notes', allNotes);
      return true;
    default: return null;
  }
};

export const dataService = {
  _products: [] as Product[],
  _inputs: [] as InputTransaction[],
  _outputs: [] as OutputTransaction[],
  _closings: [] as DailyClosing[],
  _priceHistory: [] as PriceHistory[],
  _purchaseNotes: [] as PurchaseNote[],

  async fetchAll() {
    try {
      const [products, inputs, outputs, closings, priceHistory, purchaseNotes] = await Promise.all([
        runGas('getProducts'),
        runGas('getInputs'),
        runGas('getOutputs'),
        runGas('getClosings'),
        runGas('getPriceHistory'),
        runGas('getPurchaseNotes')
      ]);

      this._products = products || [];
      this._inputs = inputs || [];
      this._outputs = outputs || [];
      this._closings = closings || [];
      this._priceHistory = priceHistory || [];
      this._purchaseNotes = purchaseNotes || [];
    } catch (e) {
      console.error("Error fetching data:", e);
    }
  },

  getProducts() { return this._products; },
  getInputs() { return this._inputs; },
  getOutputs() { return this._outputs; },
  getClosings() { return this._closings; },
  getPriceHistory() { return this._priceHistory; },
  getPurchaseNotes() { return this._purchaseNotes; },

  async saveProduct(product: Product) {
    await runGas('saveProduct', product);
    await this.fetchAll();
  },

  async deleteProduct(id: string) {
    await runGas('deleteProduct', id);
    await this.fetchAll();
  },

  async saveRestockNote(note: PurchaseNote) {
    await runGas('saveRestockNote', note);
    await this.fetchAll();
  },

  async updateNoteStatus(id: string, status: 'Paid' | 'Pending') {
    await runGas('updateNoteStatus', id, status);
    await this.fetchAll();
  },

  async saveInput(transaction: InputTransaction) {
    await runGas('addInput', transaction);
    await this.fetchAll();
  },

  async saveOutput(transaction: OutputTransaction) {
    await runGas('addOutput', transaction);
    await this.fetchAll();
  },

  async saveClosing(closing: DailyClosing) {
    await runGas('saveClosing', closing);
    await this.fetchAll();
  },

  async setup() {
    const msg = await runGas('setupSheet');
    await this.fetchAll();
    return msg;
  },

  async sync() {
    await this.fetchAll();
    return { success: true, timestamp: new Date().toISOString() };
  }
};

