  const [searchTerm, setSearchTerm] = useState('');
  const [isSearching, setIsSearching] = useState(false);

  const products = dataService.getProducts();
  const fileInputRef = useRef<HTMLInputElement>(null);

  const filteredProducts = useMemo(() => {
    if (!searchTerm) return [];
    return products.filter(p => 
      p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
      p.code.includes(searchTerm)
    ).slice(0, 5);
  }, [products, searchTerm]);

  const addToCart = (product: Product, quantity: number = 1) => {
    const existing = cart.find(item => item.productId === product.id);
    if (existing) {
      setCart(cart.map(item => 
        item.productId === product.id 
          ? { ...item, quantity: item.quantity + quantity, totalCost: (item.quantity + quantity) * item.unitCost }
          : item
      ));
    } else {
      setCart([...cart, {
        productId: product.id,
        productName: product.name,
        quantity,
        unitCost: product.costPrice,
        totalCost: product.costPrice * quantity
      }]);
    }
    setSearchTerm('');
    setIsSearching(false);
  };

  const handleOCR = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsLoading(true);
    const reader = new FileReader();
    reader.onload = async (event) => {
      try {
        const base64 = event.target?.result as string;
        const results = await processTicketWithGemini(base64);

        results.forEach(result => {
          const match = products.find(p => p.code === result.code || p.name.toLowerCase().includes(result.name.toLowerCase()));
          if (match) {
            addToCart(match, result.quantity);
          }
        });
      } catch (err) {
        alert("OCR falló al procesar el ticket.");
      } finally {
        setIsLoading(false);
      }
    };
    reader.readAsDataURL(file);
  };

  const completeRestock = async () => {
    if (cart.length === 0) return;

    setIsLoading(true);
    try {
      const note: PurchaseNote = {
        id: 'NOTE-' + Math.random().toString(36).substr(2, 9).toUpperCase(),
        date: new Date(date).toISOString(),
        provider: provider || 'Proveedor General',
        totalAmount: cart.reduce((acc, item) => acc + item.totalCost, 0),
        status,
        detailsJson: JSON.stringify(cart)
      };

      await dataService.saveRestockNote(note);
      setCart([]);
      setProvider('');
      alert("¡Reabastecimiento registrado exitosamente!");
    } catch (e) {
      alert("Error al guardar el reabastecimiento.");
    } finally {
      setIsLoading(false);
    }
  };

  const grandTotal = cart.reduce((acc, item) => acc + item.totalCost, 0);

