          </div>
          <button 
            onClick={() => fileInputRef.current?.click()}
            className="flex items-center space-x-2 bg-emerald-600 text-white px-5 py-2.5 rounded-xl hover:bg-emerald-700 transition-all shadow-lg shadow-emerald-200 active:scale-95"
          >
            {isLoading ? <Loader2 className="animate-spin" size={20} /> : <Camera size={20} />}
            <span className="font-bold">IA Ticket OCR</span>
          </button>
          <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleOCR} />
        </div>

        <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm space-y-6">
          <div className="relative">
            <label className="block text-sm font-bold text-slate-700 mb-2">Buscador Inteligente de Productos</label>
            <div className="relative group">
