function setupSheet() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheets = {
    "Products": ["id", "code", "name", "grams", "flavor", "costPrice", "salePrice", "stock", "category", "provider", "totalInvested", "totalEarned"],
    "Inputs": ["id", "productId", "productName", "quantity", "unitCost", "totalCost", "date", "provider", "invoiceId", "status"],
    "Outputs": ["id", "productId", "productName", "quantity", "salePrice", "totalSale", "date", "shift"],
    "Closings": ["id", "date", "totalSold", "netProfit", "cogs"],
    "PriceHistory": ["id", "productId", "productName", "field", "oldValue", "newValue", "date"],
    "PurchaseNotes": ["id", "date", "provider", "totalAmount", "status", "detailsJson"],
    "Envelopes": ["id", "name", "balance", "description"]
  };

  for (let name in sheets) {
    let sheet = ss.getSheetByName(name);
    if (!sheet) {
      sheet = ss.insertSheet(name);
      sheet.appendRow(sheets[name]);
      sheet.getRange(1, 1, 1, sheets[name].length)
           .setFontWeight("bold")
           .setBackground("#f3f4f6")
           .setBorder(true, true, true, true, true, true);
      sheet.setFrozenRows(1);
    }
  }

  const envSheet = ss.getSheetByName("Envelopes");
  if (envSheet.getLastRow() <= 1) {
    envSheet.appendRow(["ENV1", "Sobre 1 - Ganancia", 0, "Repartición parte 1/3"]);
    envSheet.appendRow(["ENV2", "Sobre 2 - Ganancia", 0, "Repartición parte 2/3"]);
    envSheet.appendRow(["ENV3", "Sobre 3 - Ganancia", 0, "Repartición parte 3/3"]);
    envSheet.appendRow(["ENV4", "Sobre 4 - Capital", 0, "Reposición de Mercancía"]);
  }

  return "Sistema inicializado correctamente.";
}

function getProducts() {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("Products");
  if (!sheet) return [];
  const data = sheet.getDataRange().getValues();
  const headers = data[0];
  return data.slice(1).map(row => {
    let obj = {}; headers.forEach((h, i) => obj[h] = row[i]);
    return obj;
  });
}

function getEnvelopes() {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("Envelopes");
  if (!sheet) return [];
  const data = sheet.getDataRange().getValues();
  const headers = data[0];
  return data.slice(1).map(row => {
    let obj = {}; headers.forEach((h, i) => obj[h] = row[i]);
    return obj;
  });
}

function updateEnvelopeBalance(id, amount) {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("Envelopes");
  const data = sheet.getDataRange().getValues();
  const idIdx = data[0].indexOf("id");
  const balIdx = data[0].indexOf("balance");

  for (let i = 1; i < data.length; i++) {
    if (data[i][idIdx] == id) {
      const current = Number(data[i][balIdx]) || 0;
      sheet.getRange(i + 1, balIdx + 1).setValue(current + amount);
      return true;
    }
  }
  return false;
}

function processPhysicalCount(counts, shift) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const products = getProducts();
  let totalSold = 0;
  let totalCOGS = 0;

  counts.forEach(c => {
    const prod = products.find(p => p.id === c.productId);
    if (prod && prod.stock > c.physicalCount) {
      const soldQty = prod.stock - c.physicalCount;
      const soldAmount = soldQty * prod.salePrice;
      const cogsAmount = soldQty * prod.costPrice;

      totalSold += soldAmount;
      totalCOGS += cogsAmount;

      // Log the sale
      addOutput({
        id: Utilities.getUuid(),
        productId: prod.id,
        productName: prod.name,
        quantity: soldQty,
        salePrice: prod.salePrice,
        totalSale: soldAmount,
        date: new Date().toISOString(),
        shift: shift
      });
    }
  });

  const netProfit = totalSold - totalCOGS;
  if (netProfit > 0) {
    const split = netProfit / 3;
    updateEnvelopeBalance("ENV1", split);
    updateEnvelopeBalance("ENV2", split);
    updateEnvelopeBalance("ENV3", split);
  }

  // Add COGS back to Capital
  updateEnvelopeBalance("ENV4", totalCOGS);

  // Save Closing
  saveClosing({
    id: Utilities.getUuid(),
    date: new Date().toISOString(),
    totalSold,
    netProfit,
    cogs: totalCOGS
  });

  return { totalSold, netProfit, totalCOGS };
}

function saveRestockNote(note) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const noteSheet = ss.getSheetByName("PurchaseNotes");
  const headers = ["id", "date", "provider", "totalAmount", "status", "detailsJson"];
  noteSheet.appendRow(headers.map(h => note[h]));

  const details = JSON.parse(note.detailsJson);
  details.forEach(item => {
    updateStock(item.productId, item.quantity, item.totalCost, 0, item.unitCost);
  });

  // If paid immediately, subtract from Envelope 4
  if (note.status === 'Paid') {
    updateEnvelopeBalance("ENV4", -note.totalAmount);
  }
  return true;
}

function updateNoteStatus(noteId, newStatus) {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("PurchaseNotes");
  const data = sheet.getDataRange().getValues();
  const idIdx = data[0].indexOf("id");
  const amtIdx = data[0].indexOf("totalAmount");
  const statusIdx = data[0].indexOf("status");

  for (let i = 1; i < data.length; i++) {
    if (data[i][idIdx] == noteId) {
      const amount = Number(data[i][amtIdx]);
      sheet.getRange(i + 1, statusIdx + 1).setValue(newStatus);
      if (newStatus === 'Paid') {
        updateEnvelopeBalance("ENV4", -amount);
      }
      return true;
    }
  }
}

// Utility functions
function updateStock(pId, sC, iC, eC, nC) {
  let s = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("Products");
  let d = s.getDataRange().getValues(); let h = d[0];
  for(let i=1; i<d.length; i++) {
    if(d[i][h.indexOf("id")] == pId) {
      let r = i+1;
      s.getRange(r, h.indexOf("stock")+1).setValue(Number(d[i][h.indexOf("stock")]) + sC);
      s.getRange(r, h.indexOf("totalInvested")+1).setValue(Number(d[i][h.indexOf("totalInvested")]) + (iC||0));
      s.getRange(r, h.indexOf("totalEarned")+1).setValue(Number(d[i][h.indexOf("totalEarned")]) + (eC||0));
      if(nC) s.getRange(r, h.indexOf("costPrice")+1).setValue(nC);
      break;
    }
  }
}
