import { Product, PurchaseNote } from '../types';

const Restock: React.FC = () => {
  const [cart, setCart] = useState<any[]>([]);
  const [provider, setProvider] = useState('');
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [status, setStatus] = useState<'Paid' | 'Pending'>('Paid');
  const [isLoading, setIsLoading] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [isSearching, setIsSearching] = useState(false);

  const products = dataService.getProducts();
  const envelopes = dataService.getEnvelopes();
  const capitalBalance = envelopes.find(e => e.id === "ENV4")?.balance || 0;
  const fileInputRef = useRef<HTMLInputElement>(null);

  const filteredProducts = useMemo(() => {
    if (!searchTerm) return [];
    return products.filter(p => p.name.toLowerCase().includes(searchTerm.toLowerCase()) || p.code.includes(searchTerm)).slice(0, 5);
  }, [products, searchTerm]);

  const addToCart = (product: Product, quantity: number = 1) => {
    const existing = cart.find(item => item.productId === product.id);
    if (existing) {
      setCart(cart.map(item => item.productId === product.id ? { ...item, quantity: item.quantity + quantity, totalCost: (item.quantity + quantity) * item.unitCost } : item));
    } else {
      setCart([...cart, { productId: product.id, productName: product.name, quantity, unitCost: product.costPrice, totalCost: product.costPrice * quantity }]);
    }
    setSearchTerm(''); setIsSearching(false);
  };

  const handleOCR = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]; if (!file) return;
    setIsLoading(true);
    const reader = new FileReader();
    reader.onload = async (event) => {
      try {
        const base64 = event.target?.result as string;
        const results = await processTicketWithGemini(base64);
        results.forEach(result => {
          const match = products.find(p => p.code === result.code || p.name.toLowerCase().includes(result.name.toLowerCase()));
          if (match) addToCart(match, result.quantity);
        });
      } catch (err) { alert("OCR Error"); } finally { setIsLoading(false); }
    };
    reader.readAsDataURL(file);
  };

  const completeRestock = async () => {
    if (cart.length === 0) return;
    const total = cart.reduce((acc, item) => acc + item.totalCost, 0);
    if (status === 'Paid' && capitalBalance < total) {
      if (!confirm("El saldo del Sobre 4 es insuficiente. ¿Deseas continuar de todas formas?")) return;
    }

    setIsLoading(true);
    try {
      const note: PurchaseNote = { id: 'NOTE-' + Math.random().toString(36).substr(2, 9).toUpperCase(), date: new Date(date).toISOString(), provider: provider || 'Proveedor Gral', totalAmount: total, status, detailsJson: JSON.stringify(cart) };
      await dataService.saveRestockNote(note);
      setCart([]); setProvider('');
      alert("¡Restock guardado!");
    } catch (e) { alert("Error"); } finally { setIsLoading(false); }
  };

  const grandTotal = cart.reduce((acc, item) => acc + item.totalCost, 0);

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 animate-in fade-in slide-in-from-right-4 duration-500">
      <div className="lg:col-span-2 space-y-6">
        <div className="flex items-center justify-between">
          <h2 className="text-2xl font-black text-slate-800">Módulo de Restock</h2>
          <div className="flex items-center space-x-4">
            <div className="bg-white px-6 py-3 rounded-2xl border-2 border-blue-50 flex items-center space-x-3 shadow-sm">
              <Banknote className="text-emerald-500" size={24} />
              <div>
                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Presupuesto Reposición</span>
                <span className="text-lg font-black text-slate-800">${capitalBalance.toLocaleString()}</span>
              </div>
            </div>
            <button onClick={() => fileInputRef.current?.click()} className="bg-emerald-600 text-white p-3 rounded-2xl hover:bg-emerald-700 transition-all shadow-lg"><Camera size={24} /></button>
            <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleOCR} />
          </div>
        </div>

        <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm space-y-6">
          <div className="relative">
            <label className="block text-sm font-black text-slate-700 mb-2">Buscador Autocomplete</label>
            <input 
              type="text" 
              placeholder="Nombre o Código..." 
              value={searchTerm}
              onFocus={() => setIsSearching(true)}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full p-4 bg-slate-50 border-2 border-transparent rounded-2xl focus:bg-white focus:border-blue-500 transition-all font-bold text-lg"
            />
            {isSearching && filteredProducts.length > 0 && (
              <div className="absolute top-full left-0 right-0 mt-2 bg-white border border-slate-200 rounded-2xl shadow-2xl z-50 overflow-hidden divide-y divide-slate-100">
                {filteredProducts.map(p => (
                  <button key={p.id} onClick={() => addToCart(p)} className="w-full p-4 flex items-center justify-between hover:bg-blue-50 transition-colors">
                    <div className="text-left"><p className="font-bold">{p.name}</p><p className="text-xs text-slate-400">Stock: {p.stock}</p></div>
                    <span className="bg-blue-100 text-blue-700 px-3 py-1 rounded-lg font-bold text-sm">${p.costPrice}</span>
                  </button>
                ))}
              </div>
            )}
          </div>
          <div className="grid grid-cols-2 gap-6">
            <input value={provider} onChange={(e) => setProvider(e.target.value)} className="w-full p-4 bg-slate-50 rounded-2xl font-bold" placeholder="Proveedor..." />
            <input type="date" value={date} onChange={(e) => setDate(e.target.value)} className="w-full p-4 bg-slate-50 rounded-2xl font-bold" />
          </div>
        </div>

        <div className="bg-white rounded-3xl border border-slate-200 overflow-hidden shadow-sm divide-y divide-slate-100">
          {cart.map(item => (
            <div key={item.productId} className="p-6 flex items-center justify-between">
              <div className="flex-1"><p className="font-bold text-lg">{item.productName}</p></div>
              <div className="flex items-center space-x-6">
                <input type="number" min="1" value={item.quantity} onChange={(e) => {
                  const val = parseInt(e.target.value) || 1;
                  setCart(cart.map(i => i.productId === item.productId ? {...i, quantity: val, totalCost: val * i.unitCost} : i));
                }} className="w-20 p-2 bg-slate-50 rounded-lg text-center font-bold" />
                <span className="text-xl font-black text-slate-800">${item.totalCost.toFixed(2)}</span>
                <button onClick={() => setCart(cart.filter(i => i.productId !== item.productId))} className="text-red-400 hover:text-red-600"><Trash2 size={20} /></button>
              </div>
            </div>
          ))}
          {cart.length === 0 && <div className="py-20 text-center text-slate-400 italic">Lista de compra vacía.</div>}
        </div>
      </div>

      <div className="lg:col-span-1">
        <div className="bg-slate-900 text-white p-8 rounded-[2rem] shadow-2xl h-full flex flex-col justify-between border-4 border-slate-800 sticky top-24">
          <div className="space-y-8">
            <h3 className="text-2xl font-black text-blue-400 flex items-center space-x-3"><ShoppingCart size={32}/><span>Total Nota</span></h3>
            <div className="space-y-4">
              <div className="flex justify-between text-slate-400 font-bold uppercase text-xs"><span>Subtotal:</span><span>${grandTotal.toLocaleString()}</span></div>
              <div className="flex justify-between items-end border-t border-slate-800 pt-6">
                <span className="text-slate-500 font-bold">Monto Final:</span>
                <span className="text-5xl font-black text-white tracking-tighter">${grandTotal.toLocaleString()}</span>
              </div>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <button onClick={() => setStatus('Paid')} className={`py-4 rounded-2xl font-black border-2 transition-all ${status === 'Paid' ? 'bg-emerald-500 border-emerald-400 text-white' : 'border-slate-800 text-slate-500'}`}>PAGADO</button>
              <button onClick={() => setStatus('Pending')} className={`py-4 rounded-2xl font-black border-2 transition-all ${status === 'Pending' ? 'bg-amber-500 border-amber-400 text-white' : 'border-slate-800 text-slate-500'}`}>DEUDA</button>
            </div>
          </div>
          <button onClick={completeRestock} disabled={cart.length === 0 || isLoading} className="w-full bg-blue-600 py-6 rounded-2xl font-black text-xl mt-12 hover:bg-blue-500 transition-all shadow-xl shadow-blue-900/50">REGISTRAR COMPRA</button>
        </div>
      </div>
    </div>
  );
};

