import { Product, InputTransaction, OutputTransaction, DailyClosing, PriceHistory, PurchaseNote, Envelope } from "../types";

const isGasEnv = () => {
  const g = (window as any).google;
  return typeof g !== 'undefined' && g.script && g.script.run;
};

const runGas = (functionName: string, ...args: any[]): Promise<any> => {
  const google = (window as any).google;
  if (isGasEnv()) {
    return new Promise((resolve, reject) => {
      google.script.run
        .withSuccessHandler(resolve)
        .withFailureHandler(reject)[functionName](...args);
    });
  } else {
    return mockHandler(functionName, args);
  }
};

const mockHandler = async (fn: string, args: any[]): Promise<any> => {
  const getStorage = (key: string) => JSON.parse(localStorage.getItem(key) || '[]');
  const setStorage = (key: string, data: any) => localStorage.setItem(key, JSON.stringify(data));

  switch (fn) {
    case 'getProducts': return getStorage('zenith_products');
    case 'getInputs': return getStorage('zenith_inputs');
    case 'getOutputs': return getStorage('zenith_outputs');
    case 'getClosings': return getStorage('zenith_closings');
    case 'getPriceHistory': return getStorage('zenith_price_history');
    case 'getPurchaseNotes': return getStorage('zenith_purchase_notes');
    case 'getEnvelopes': return getStorage('zenith_envelopes').length > 0 ? getStorage('zenith_envelopes') : [
      { id: "ENV1", name: "Sobre 1 - Ganancia", balance: 0, description: "1/3 Ganancia" },
      { id: "ENV2", name: "Sobre 2 - Ganancia", balance: 0, description: "1/3 Ganancia" },
      { id: "ENV3", name: "Sobre 3 - Ganancia", balance: 0, description: "1/3 Ganancia" },
      { id: "ENV4", name: "Sobre 4 - Capital", balance: 5000, description: "Fondo Reposición" },
    ];
    case 'processPhysicalCount':
      const [counts, shift] = args;
      const envs = getStorage('zenith_envelopes');
      // Simple mock logic for counts
      return { totalSold: 1000, netProfit: 300, totalCOGS: 700 };
    case 'updateEnvelopeBalance':
      const [envId, envAmt] = args;
      const envArr = getStorage('zenith_envelopes');
      const eIdx = envArr.findIndex((e:any) => e.id === envId);
      if(eIdx > -1) envArr[eIdx].balance += envAmt;
      setStorage('zenith_envelopes', envArr);
      return true;
    // Fix: Added mock cases for saveOutput and saveClosing
    case 'saveOutput':
      const [output] = args;
      const outputs = getStorage('zenith_outputs');
      outputs.push(output);
      setStorage('zenith_outputs', outputs);
      return true;
    case 'saveClosing':
      const [closing] = args;
      const closings = getStorage('zenith_closings');
      closings.push(closing);
      setStorage('zenith_closings', closings);
      return true;
    default: return null;
  }
};

export const dataService = {
  _products: [] as Product[],
  _inputs: [] as InputTransaction[],
  _outputs: [] as OutputTransaction[],
  _closings: [] as DailyClosing[],
  _priceHistory: [] as PriceHistory[],
  _purchaseNotes: [] as PurchaseNote[],
  _envelopes: [] as Envelope[],

  async fetchAll() {
    try {
      const [products, inputs, outputs, closings, priceHistory, purchaseNotes, envelopes] = await Promise.all([
        runGas('getProducts'),
        runGas('getInputs'),
        runGas('getOutputs'),
        runGas('getClosings'),
        runGas('getPriceHistory'),
        runGas('getPurchaseNotes'),
        runGas('getEnvelopes')
      ]);

      this._products = products || [];
      this._inputs = inputs || [];
      this._outputs = outputs || [];
      this._closings = closings || [];
      this._priceHistory = priceHistory || [];
      this._purchaseNotes = purchaseNotes || [];
      this._envelopes = envelopes || [];
    } catch (e) {
      console.error("Error fetching data:", e);
    }
  },

  getProducts() { return this._products; },
  getEnvelopes() { return this._envelopes; },
  getPurchaseNotes() { return this._purchaseNotes; },
  getOutputs() { return this._outputs; },
  getClosings() { return this._closings; },
  getPriceHistory() { return this._priceHistory; },
  getInputs() { return this._inputs; },

  async processPhysicalCount(counts: any[], shift: string) {
    const res = await runGas('processPhysicalCount', counts, shift);
    await this.fetchAll();
    return res;
  },

  async updateEnvelopeBalance(id: string, amount: number) {
    await runGas('updateEnvelopeBalance', id, amount);
    await this.fetchAll();
  },

  async updateNoteStatus(id: string, status: 'Paid' | 'Pending') {
    await runGas('updateNoteStatus', id, status);
    await this.fetchAll();
  },

  async saveRestockNote(note: PurchaseNote) {
    await runGas('saveRestockNote', note);
    await this.fetchAll();
  },

  // Fix: Added missing saveOutput method to handle DailyClosingView.tsx requirements
  async saveOutput(output: OutputTransaction) {
    await runGas('saveOutput', output);
    await this.fetchAll();
  },

  // Fix: Added missing saveClosing method to handle DailyClosingView.tsx requirements
  async saveClosing(closing: DailyClosing) {
    await runGas('saveClosing', closing);
    await this.fetchAll();
  },

  async saveProduct(p: Product) { await runGas('saveProduct', p); await this.fetchAll(); },
  async deleteProduct(id: string) { await runGas('deleteProduct', id); await this.fetchAll(); },
  async setup() { const msg = await runGas('setupSheet'); await this.fetchAll(); return msg; },
  async sync() { await this.fetchAll(); return { success: true }; }
};

