function getDashboardData() {
  const products = getProducts();
  const envelopes = getEnvelopes();
  const outputs = getOutputs();

  const netProfit = envelopes.filter(e => e.id !== 'ENV4').reduce((acc, e) => acc + (Number(e.balance) || 0), 0);
  const capital = envelopes.find(e => e.id === 'ENV4')?.balance || 0;

  const profitVsCapital = [
    { name: 'Utilidad Neta', value: netProfit },
    { name: 'Capital Resguardo', value: Number(capital) }
  ];

  const productMap = products.reduce((acc, p) => { acc[p.id] = p; return acc; }, {});
  const productStats = {};

  outputs.forEach(out => {
    const pId = out.productId;
    const p = productMap[pId];
    if (!productStats[pId]) {
      productStats[pId] = { name: out.productName || p?.name || '?', volume: 0, profit: 0 };
    }
    const qty = Number(out.quantity) || 0;
    const sale = Number(out.totalSale) || 0;
    const cost = p ? (Number(p.costPrice) * qty) : 0;
    productStats[pId].volume += qty;
    productStats[pId].profit += (sale - cost);
  });

  const statsArray = Object.values(productStats);
  return {
    envelopes,
    profitVsCapital,
    topVolume: statsArray.sort((a, b) => b.volume - a.volume).slice(0, 3),
    topProfit: statsArray.sort((a, b) => b.profit - a.profit).slice(0, 3)
  };
}

function processPhysicalCount(counts, shift) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const products = getProducts();
  let totalSold = 0;
  let totalCOGS = 0;

  counts.forEach(c => {
    const prod = products.find(p => p.id === c.productId || p.code === c.productId);
    if (prod && prod.stock > c.physicalCount) {
      const soldQty = prod.stock - c.physicalCount;
      const soldAmount = soldQty * prod.salePrice;
      const cogsAmount = soldQty * prod.costPrice;
      totalSold += soldAmount;
      totalCOGS += cogsAmount;

      addOutput({
        id: Utilities.getUuid(),
        productId: prod.id,
        productName: prod.name,
        quantity: soldQty,
        salePrice: prod.salePrice,
        totalSale: soldAmount,
        date: new Date().toISOString(),
        shift: shift
      });
    }
  });

  const netProfit = totalSold - totalCOGS;
  if (netProfit > 0) {
    const split = netProfit / 3;
    updateEnvelopeBalance("ENV1", split);
    updateEnvelopeBalance("ENV2", split);
    updateEnvelopeBalance("ENV3", split);
  }
  updateEnvelopeBalance("ENV4", totalCOGS);

  saveClosing({
    id: Utilities.getUuid(),
    date: new Date().toISOString(),
    totalSold,
    netProfit,
    cogs: totalCOGS
  });

  return { totalSold, netProfit, totalCOGS };
}

function updateEnvelopeBalance(id, amount) {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("Envelopes");
  const data = sheet.getDataRange().getValues();
  const idIdx = data[0].indexOf("id");
  const balIdx = data[0].indexOf("balance");
  for (let i = 1; i < data.length; i++) {
    if (data[i][idIdx] == id) {
      sheet.getRange(i + 1, balIdx + 1).setValue(Number(data[i][balIdx]) + amount);
      return true;
    }
  }
}

