function addOutput(t) {
  const s = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("Outputs");
  s.appendRow(["id", "productId", "productName", "quantity", "salePrice", "totalSale", "date", "shift"].map(h => t[h]));
