}

function updateStockFromSale(pId, qty, earned) {
  const s = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("Products");
  const d = s.getDataRange().getValues();
  const h = d[0];
  const idIdx = h.indexOf("id");
  const stIdx = h.indexOf("stock");
  const erIdx = h.indexOf("totalEarned");
  for(let i=1; i<d.length; i++) {
    if(d[i][idIdx] == pId) {
      s.getRange(i+1, stIdx+1).setValue(Number(d[i][stIdx]) - qty);
      s.getRange(i+1, erIdx+1).setValue(Number(d[i][erIdx]) + earned);
      break;
    }
  }
}

function saveClosing(c) {
  const s = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("Closings");
  s.appendRow(["id", "date", "totalSold", "netProfit", "cogs"].map(h => c[h]));
}

function saveRestockNote(note) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const noteSheet = ss.getSheetByName("PurchaseNotes");
  noteSheet.appendRow(["id", "date", "provider", "totalAmount", "status", "detailsJson"].map(h => note[h]));
  const details = JSON.parse(note.detailsJson);
  details.forEach(item => updateStockRestock(item.productId, item.quantity, item.totalCost, item.unitCost));
  if (note.status === 'Paid') updateEnvelopeBalance("ENV4", -note.totalAmount);
  return true;
}

function updateStockRestock(pId, qty, cost, unit) {
  const s = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("Products");
  const d = s.getDataRange().getValues(); const h = d[0];
  for(let i=1; i<d.length; i++) {
    if(d[i][h.indexOf("id")] == pId) {
      s.getRange(i+1, h.indexOf("stock")+1).setValue(Number(d[i][h.indexOf("stock")]) + qty);
      s.getRange(i+1, h.indexOf("totalInvested")+1).setValue(Number(d[i][h.indexOf("totalInvested")]) + cost);
      s.getRange(i+1, h.indexOf("costPrice")+1).setValue(unit);
      break;
    }
  }
}

function saveProduct(p) {
  const s = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("Products");
  const data = s.getDataRange().getValues();
  const h = data[0];
  let rowIndex = -1;
  for(let i=1; i<data.length; i++) { if(data[i][0] == p.id) { rowIndex = i+1; break; } }
  const row = h.map(k => p[k] !== undefined ? p[k] : "");
  if(rowIndex > 0) s.getRange(rowIndex, 1, 1, h.length).setValues([row]);
  else s.appendRow(row);
  return true;
}

