import React, { useState, useMemo } from 'react';
import { Save, Calculator, CheckCircle2, Wallet, ArrowRight, RefreshCcw, Search, AlertCircle } from 'lucide-react';
import { dataService } from '../services/dataService';

const DailyInventoryCount: React.FC = () => {
  const products = dataService.getProducts();
  const purchaseNotes = dataService.getPurchaseNotes();
  const envelopes = dataService.getEnvelopes();
  const [counts, setCounts] = useState<{ [key: string]: number }>({});
  const [searchTerm, setSearchTerm] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [summary, setSummary] = useState<any>(null);
  const [showDebtModal, setShowDebtModal] = useState(false);

  const filteredProducts = useMemo(() => {
    return products.filter(p => 
      p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
      p.code.includes(searchTerm)
    );
  }, [products, searchTerm]);

  const pendingNotes = useMemo(() => {
    const notes = purchaseNotes || [];
    return notes.filter((n: any) => n.status === 'Pending');
  }, [purchaseNotes]);

  const capitalBalance = envelopes.find(e => e.id === "ENV4")?.balance || 0;

  const handleCountChange = (id: string, val: string) => {
    setCounts({ ...counts, [id]: parseInt(val) || 0 });
  };

  const processClosing = async () => {
    if (Object.keys(counts).length === 0) return alert("Ingresa al menos un conteo físico.");

    setIsProcessing(true);
    try {
      const payload = Object.entries(counts).map(([id, val]) => ({ productId: id, physicalCount: val }));
      const res = await dataService.processPhysicalCount(payload, 'Daily Count');
      setSummary(res);
      if (pendingNotes.length > 0) setShowDebtModal(true);
    } catch (e) {
      alert("Error procesando el cierre.");
    } finally {
      setIsProcessing(false);
    }
  };

  const payNote = async (id: string) => {
    await dataService.updateNoteStatus(id, 'Paid');
    alert("Nota pagada con cargo al Sobre 4");
  };

  if (summary) {
    return (
      <div className="max-w-2xl mx-auto space-y-8 animate-in zoom-in-95 duration-500">
        <div className="bg-white p-10 rounded-[2.5rem] border-4 border-emerald-50 shadow-2xl space-y-8 text-center">
          <div className="bg-emerald-100 text-emerald-600 w-20 h-20 rounded-full flex items-center justify-center mx-auto mb-4">
            <CheckCircle2 size={48} />
          </div>
          <h2 className="text-3xl font-black text-slate-800 tracking-tight">Cierre de Caja Finalizado</h2>

          <div className="grid grid-cols-2 gap-4">
            <div className="p-6 bg-slate-50 rounded-3xl border border-slate-100">
              <span className="text-xs font-black text-slate-400 uppercase">Venta Bruta</span>
              <p className="text-2xl font-black text-blue-600">${summary.totalSold.toLocaleString()}</p>
            </div>
            <div className="p-6 bg-emerald-50 rounded-3xl border border-emerald-100">
              <span className="text-xs font-black text-slate-400 uppercase">Utilidad Real</span>
              <p className="text-2xl font-black text-emerald-600">${summary.netProfit.toLocaleString()}</p>
            </div>
          </div>

          <div className="p-6 bg-amber-50 rounded-3xl border border-amber-100 text-left space-y-2">
            <div className="flex items-center space-x-2 text-amber-700 font-black uppercase text-xs">
              <Wallet size={16} /> <span>Distribución de Flujo</span>
            </div>
            <p className="text-sm text-amber-600">
              Se depositaron <strong>${(summary.netProfit/3).toFixed(2)}</strong> en cada sobre de ganancia (1, 2, 3) 
              y <strong>${summary.totalCOGS.toLocaleString()}</strong> se recuperaron para el <strong>Sobre 4 (Capital)</strong>.
            </p>
          </div>

          <button 
            onClick={() => { setSummary(null); setCounts({}); }} 
            className="w-full bg-slate-900 text-white font-black py-5 rounded-2xl hover:bg-slate-800 transition-all flex items-center justify-center space-x-2"
          >
            <span>Nueva Operación</span>
            <ArrowRight size={20} />
          </button>
        </div>

        {showDebtModal && pendingNotes.length > 0 && (
          <div className="bg-white p-8 rounded-3xl border-2 border-amber-100 shadow-xl space-y-6">
            <div className="flex items-center space-x-3 text-amber-600">
              <AlertCircle size={24} />
              <h3 className="text-xl font-black">Cuentas por Pagar</h3>
            </div>
            <p className="text-slate-500 text-sm italic">
              Tienes {pendingNotes.length} facturas pendientes. Usa el capital del Sobre 4 (${capitalBalance.toLocaleString()}) para liquidar.
            </p>
            <div className="space-y-3">
              {pendingNotes.map((n: any) => (
                <div key={n.id} className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl border border-slate-200">
                  <div>
                    <span className="text-[10px] font-black text-slate-400 uppercase">{n.provider}</span>
                    <p className="font-black text-slate-800">${Number(n.totalAmount).toLocaleString()}</p>
                  </div>
                  <button 
                    onClick={() => payNote(n.id)}
                    disabled={capitalBalance < Number(n.totalAmount)}
                    className="bg-emerald-600 text-white px-4 py-2 rounded-xl font-bold text-xs hover:bg-emerald-700 transition-all disabled:opacity-30 disabled:grayscale"
                  >
                    Liquidar
                  </button>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    );
  }

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-500">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-3xl font-black text-slate-800 tracking-tight">Cierre por Conteo Físico</h2>
          <p className="text-slate-500 font-medium">Solo ingresa la cantidad de productos que ves en el estante.</p>
        </div>
        <div className="relative max-w-xs w-full">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
          <input 
            type="text"
            placeholder="Buscar producto..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full pl-11 pr-4 py-3 bg-white border-2 border-slate-100 rounded-2xl focus:border-blue-500 focus:outline-none font-bold"
          />
        </div>
      </div>

      <div className="bg-white rounded-[2.5rem] border border-slate-200 shadow-sm overflow-hidden">
        <div className="p-6 bg-slate-50 border-b border-slate-200 grid grid-cols-12 text-[10px] font-black uppercase text-slate-400 tracking-widest">
          <div className="col-span-5 md:col-span-6">Producto / Descripción</div>
          <div className="col-span-3 md:col-span-3 text-center">Stock Sistema</div>
          <div className="col-span-4 md:col-span-3 text-center">Conteo Real</div>
        </div>
        <div className="divide-y divide-slate-100 max-h-[550px] overflow-y-auto custom-scrollbar">
          {filteredProducts.map(p => (
            <div key={p.id} className="p-6 grid grid-cols-12 items-center hover:bg-blue-50/20 transition-colors">
              <div className="col-span-5 md:col-span-6">
                <span className="font-bold text-slate-800 block text-sm">{p.name}</span>
                <span className="text-[10px] text-slate-400 font-bold uppercase tracking-tighter">{p.provider} • {p.code}</span>
              </div>
              <div className="col-span-3 md:col-span-3 text-center">
                <span className="bg-slate-100 px-3 py-1 rounded-lg text-slate-600 font-black text-sm">{p.stock}</span>
              </div>
              <div className="col-span-4 md:col-span-3 flex justify-center">
                <input 
                  type="number"
                  placeholder="0"
                  value={counts[p.id] !== undefined ? counts[p.id] : ''}
                  onChange={(e) => handleCountChange(p.id, e.target.value)}
                  className="w-24 p-3 bg-blue-50/50 border-2 border-blue-100 rounded-2xl text-center font-black text-blue-600 focus:bg-white focus:border-blue-500 focus:outline-none transition-all"
                />
              </div>
            </div>
          ))}
          {filteredProducts.length === 0 && (
            <div className="p-20 text-center text-slate-300 font-bold italic">No hay productos en esta categoría.</div>
          )}
        </div>
        <div className="p-8 bg-slate-50 border-t border-slate-200 flex flex-col md:flex-row justify-between items-center gap-4">
          <div className="text-slate-400 text-xs font-bold uppercase tracking-widest flex items-center space-x-2">
            <Calculator size={16} />
            <span>Venta calculada por diferencia de inventario</span>
          </div>
          <button 
            onClick={processClosing}
            disabled={isProcessing || Object.keys(counts).length === 0}
            className="w-full md:w-auto flex items-center justify-center space-x-3 bg-blue-600 text-white px-12 py-5 rounded-2xl font-black hover:bg-blue-700 transition-all shadow-xl shadow-blue-200 active:scale-95 disabled:opacity-50"
          >
            {isProcessing ? <RefreshCcw className="animate-spin" /> : <Save size={24} />}
            <span className="text-lg">Ejecutar Cierre Maestro</span>
          </button>
        </div>
      </div>
    </div>
  );
};

