function processPhysicalCount(counts, shift) {
  const products = getProducts();
  let totalSold = 0;
  let totalCOGS = 0;

  counts.forEach(c => {
    const prod = products.find(p => p.id == c.productId || p.code == c.productId);
    if (prod && prod.stock > c.physicalCount) {
      const soldQty = prod.stock - c.physicalCount;
      const soldAmount = soldQty * prod.salePrice;
      const costAmount = soldQty * prod.costPrice;

      totalSold += soldAmount;
      totalCOGS += costAmount;

      addOutput({
        id: Utilities.getUuid(),
        productId: prod.id,
        productName: prod.name,
        quantity: soldQty,
        salePrice: prod.salePrice,
        totalSale: soldAmount,
        date: new Date().toISOString(),
        shift: shift
      });
    }
  });

  const netProfit = totalSold - totalCOGS;
  if (netProfit > 0) {
    const part = netProfit / 3;
    updateEnvelopeBalance("ENV1", part);
    updateEnvelopeBalance("ENV2", part);
    updateEnvelopeBalance("ENV3", part);
  }
  updateEnvelopeBalance("ENV4", totalCOGS);

  saveClosing({
    id: Utilities.getUuid(),
    date: new Date().toISOString(),
    totalSold,
    netProfit,
    cogs: totalCOGS
  });

  return { totalSold, netProfit, totalCOGS };
}

function updateEnvelopeBalance(id, amount) {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("Envelopes");
  const data = sheet.getDataRange().getValues();
  for (let i = 1; i < data.length; i++) {
    if (data[i][0] == id) {
      sheet.getRange(i + 1, 3).setValue(Number(data[i][2]) + amount);
      return true;
    }
  }
}

function getDashboardData() {
  const products = getProducts();
  const envelopes = getEnvelopes();
  const outputs = getOutputs();

  const netProfit = envelopes.filter(e => e.id !== 'ENV4').reduce((acc, e) => acc + Number(e.balance), 0);
  const capital = envelopes.find(e => e.id === 'ENV4')?.balance || 0;

  const stats = outputs.reduce((acc, out) => {
    if (!acc[out.productId]) acc[out.productId] = { name: out.productName, volume: 0, profit: 0 };
    const p = products.find(prod => prod.id == out.productId);
    acc[out.productId].volume += Number(out.quantity);
    acc[out.productId].profit += (Number(out.totalSale) - (Number(out.quantity) * (p?.costPrice || 0)));
    return acc;
  }, {});

  const statsArray = Object.values(stats);

  return {
    envelopes,
    profitVsCapital: [
      { name: 'Utilidad Neta', value: netProfit },
      { name: 'Fondo Resurtido', value: Number(capital) }
    ],
    topVolume: statsArray.sort((a, b) => b.volume - a.volume).slice(0, 3),
    topProfit: statsArray.sort((a, b) => b.profit - a.profit).slice(0, 3)
  };
}

