import React, { useState, useRef, useEffect } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { Camera, Check, AlertCircle, Loader2, ArrowLeft } from 'lucide-react';
import { processTicketWithGemini } from '../services/geminiService';
import { dataService } from '../services/dataService';

const ProductRegistration: React.FC = () => {
  const location = useLocation();
  const navigate = useNavigate();
  const [isLoading, setIsLoading] = useState(false);
  const [success, setSuccess] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const editMode = !!location.state?.product;

  const [formData, setFormData] = useState({
    id: '',
    code: '',
    name: '',
    grams: '',
    flavor: '',
    costPrice: '',
    salePrice: '',
    stock: '',
    category: 'General',
    provider: ''
  });

  useEffect(() => {
    if (location.state?.product) {
      const p = location.state.product;
      setFormData({
        id: p.id,
        code: p.code,
        name: p.name,
        grams: p.grams,
        flavor: p.flavor,
        costPrice: p.costPrice.toString(),
        salePrice: p.salePrice.toString(),
        stock: p.stock.toString(),
        category: p.category || 'General',
        provider: p.provider || ''
      });
    }
  }, [location.state]);

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsLoading(true);
    setError(null);

    const reader = new FileReader();
    reader.onload = async (event) => {
      try {
        const base64 = event.target?.result as string;
        const results = await processTicketWithGemini(base64);

        if (results.length > 0) {
          const item = results[0];
          setFormData(prev => ({
            ...prev,
            code: item.code || prev.code,
            name: item.name,
            grams: item.grams || prev.grams,
            flavor: item.flavor || prev.flavor,
            costPrice: item.costPrice.toString(),
            salePrice: (item.salePrice || item.costPrice * 1.3).toFixed(2),
            stock: item.quantity.toString()
          }));
        }
      } catch (err: any) {
        setError(err.message || 'Error procesando OCR');
      } finally {
        setIsLoading(false);
      }
    };
    reader.readAsDataURL(file);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    try {
      const existingProduct = editMode ? dataService.getProducts().find(p => p.id === formData.id) : null;

      const product = {
        id: editMode ? formData.id : Math.random().toString(36).substr(2, 9),
        code: formData.code,
        name: formData.name,
        grams: formData.grams,
        flavor: formData.flavor,
        costPrice: parseFloat(formData.costPrice),
        salePrice: parseFloat(formData.salePrice),
        stock: parseInt(formData.stock),
        category: formData.category,
        provider: formData.provider,
        totalInvested: editMode ? (existingProduct?.totalInvested || 0) : (parseFloat(formData.costPrice) * parseInt(formData.stock)),
        totalEarned: editMode ? (existingProduct?.totalEarned || 0) : 0
      };

      await dataService.saveProduct(product);
      setSuccess(true);
      if (editMode) {
        setTimeout(() => navigate('/inventory'), 1500);
      } else {
        setTimeout(() => setSuccess(false), 3000);
        setFormData({ id: '', code: '', name: '', grams: '', flavor: '', costPrice: '', salePrice: '', stock: '', category: 'General', provider: '' });
      }
    } catch (err) {
      setError("No se pudo guardar el producto.");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="max-w-2xl mx-auto animate-in fade-in slide-in-from-bottom-4 duration-500">
      <div className="flex items-center justify-between mb-10">
        <div className="flex items-center space-x-4">
          {editMode && (
            <button onClick={() => navigate('/inventory')} className="p-3 bg-white hover:bg-red-50 text-red-600 rounded-2xl transition-all border border-red-50 shadow-sm active:scale-95">
              <ArrowLeft size={24} />
            </button>
          )}
          <div>
            <h2 className="text-3xl font-black text-blue-900 tracking-tight">
              {editMode ? 'Editar Artículo' : 'Nuevo Producto'}
            </h2>
            <p className="text-slate-500 font-medium">
              {editMode ? `Actualizando ${formData.name}` : 'Registra productos o usa IA con foto.'}
            </p>
          </div>
        </div>
        {!editMode && (
          <button 
            onClick={() => fileInputRef.current?.click()}
            disabled={isLoading}
            className="flex items-center space-x-2 bg-blue-900 text-white px-8 py-4 rounded-2xl hover:bg-blue-800 transition-all shadow-xl shadow-blue-900/20 active:scale-95 disabled:opacity-50 font-black uppercase text-xs tracking-widest"
          >
            {isLoading ? <Loader2 className="animate-spin" size={20} /> : <Camera size={20} />}
            <span>IA Foto OCR</span>
          </button>
        )}
        <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileUpload} />
      </div>

      {error && (
        <div className="mb-8 p-5 bg-red-50 border-2 border-red-100 text-red-600 rounded-[2rem] flex items-center space-x-3 font-bold">
          <AlertCircle size={24} />
          <span>{error}</span>
        </div>
      )}

      <form onSubmit={handleSubmit} className="bg-white p-10 rounded-[2.5rem] border border-blue-100 shadow-2xl shadow-blue-900/5 space-y-8">
        <div className="grid grid-cols-2 gap-8">
          <div className="space-y-3">
            <label className="text-xs font-black text-blue-900 uppercase tracking-widest block px-1">Código de Barras</label>
            <input 
              required
              value={formData.code}
              onChange={(e) => setFormData({...formData, code: e.target.value})}
              className="w-full px-5 py-4 bg-blue-50/30 border-2 border-transparent rounded-2xl focus:bg-white focus:border-blue-500 focus:outline-none transition-all font-bold text-slate-800"
              placeholder="Ej. 750100..."
            />
          </div>
          <div className="space-y-3">
            <label className="text-xs font-black text-blue-900 uppercase tracking-widest block px-1">Categoría</label>
            <select 
              value={formData.category}
              onChange={(e) => setFormData({...formData, category: e.target.value})}
              className="w-full px-5 py-4 bg-blue-50/30 border-2 border-transparent rounded-2xl focus:bg-white focus:border-blue-500 focus:outline-none transition-all font-bold text-slate-800"
            >
              <option>General</option>
              <option>Abarrotes</option>
              <option>Snacks</option>
              <option>Bebidas</option>
              <option>Lácteos</option>
              <option>Higiene</option>
              <option>Farmacia</option>
            </select>
          </div>
        </div>

        <div className="space-y-3">
          <label className="text-xs font-black text-blue-900 uppercase tracking-widest block px-1">Nombre Comercial</label>
          <input 
            required
            value={formData.name}
            onChange={(e) => setFormData({...formData, name: e.target.value})}
            className="w-full px-5 py-4 bg-blue-50/30 border-2 border-transparent rounded-2xl focus:bg-white focus:border-blue-500 focus:outline-none transition-all font-bold text-slate-800"
            placeholder="Ej. Coca-Cola Original"
          />
        </div>

        <div className="grid grid-cols-2 gap-8">
          <div className="space-y-3">
            <label className="text-xs font-black text-blue-900 uppercase tracking-widest block px-1">Proveedor Oficial</label>
            <input 
              value={formData.provider}
              onChange={(e) => setFormData({...formData, provider: e.target.value})}
              className="w-full px-5 py-4 bg-blue-50/30 border-2 border-transparent rounded-2xl focus:bg-white focus:border-blue-500 focus:outline-none transition-all font-bold text-slate-800"
              placeholder="Ej. PepsiCo / Marinela"
            />
          </div>
          <div className="space-y-3">
            <label className="text-xs font-black text-blue-900 uppercase tracking-widest block px-1">Presentación (G/ML)</label>
            <input 
              value={formData.grams}
              onChange={(e) => setFormData({...formData, grams: e.target.value})}
              className="w-full px-5 py-4 bg-blue-50/30 border-2 border-transparent rounded-2xl focus:bg-white focus:border-blue-500 focus:outline-none transition-all font-bold text-slate-800"
              placeholder="Ej. 600ml"
            />
          </div>
        </div>

        <div className="grid grid-cols-3 gap-8 pt-6 border-t border-blue-50">
          <div className="space-y-3">
            <label className="text-xs font-black text-blue-900 uppercase tracking-widest block px-1">Costo ($)</label>
            <input 
              required
              type="number" step="0.01"
              value={formData.costPrice}
              onChange={(e) => setFormData({...formData, costPrice: e.target.value})}
              className="w-full px-5 py-4 bg-red-50/50 border-2 border-transparent rounded-2xl focus:bg-white focus:border-red-500 focus:outline-none transition-all font-black text-red-600 text-lg"
            />
          </div>
          <div className="space-y-3">
            <label className="text-xs font-black text-blue-900 uppercase tracking-widest block px-1">Venta ($)</label>
            <input 
              required
              type="number" step="0.01"
              value={formData.salePrice}
              onChange={(e) => setFormData({...formData, salePrice: e.target.value})}
              className="w-full px-5 py-4 bg-blue-50/50 border-2 border-transparent rounded-2xl focus:bg-white focus:border-blue-500 focus:outline-none transition-all font-black text-blue-600 text-lg"
            />
          </div>
          <div className="space-y-3">
            <label className="text-xs font-black text-blue-900 uppercase tracking-widest block px-1">Stock {editMode ? 'Actual' : 'Inicial'}</label>
            <input 
              required
              type="number"
              value={formData.stock}
              onChange={(e) => setFormData({...formData, stock: e.target.value})}
              className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent rounded-2xl focus:bg-white focus:border-slate-800 focus:outline-none transition-all font-black text-slate-800 text-lg"
            />
          </div>
        </div>

        <button 
          type="submit"
          disabled={isLoading}
          className="w-full bg-blue-600 text-white font-black py-6 rounded-2xl hover:bg-blue-700 transition-all shadow-xl shadow-blue-900/20 active:scale-95 flex items-center justify-center space-x-3 disabled:opacity-50 text-xl"
        >
          {success ? <Check size={32} /> : <span>{editMode ? 'Guardar Cambios' : 'Registrar en Inventario'}</span>}
        </button>
      </form>
    </div>
  );
};

export default ProductRegistration;

import React, { useState, useRef, useMemo } from 'react';
import { ShoppingCart, Search, Trash2, Camera, Banknote, CheckCircle2, Package, Tag, Calculator } from 'lucide-react';
import { dataService } from '../services/dataService';
import { processTicketWithGemini } from '../services/geminiService';
import { Product, PurchaseNote } from '../types';

const Restock: React.FC = () => {
  const [cart, setCart] = useState<any[]>([]);
  const [provider, setProvider] = useState('');
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [status, setStatus] = useState<'Paid' | 'Pending'>('Paid');
  const [isLoading, setIsLoading] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [isSearching, setIsSearching] = useState(false);

  const products = dataService.getProducts();
  const envelopes = dataService.getEnvelopes();
  const capitalBalance = envelopes.find(e => e.id === "ENV4")?.balance || 0;
  const fileInputRef = useRef<HTMLInputElement>(null);

  const filteredProducts = useMemo(() => {
    if (!searchTerm) return [];
    return products.filter(p => p.name.toLowerCase().includes(searchTerm.toLowerCase()) || p.code.includes(searchTerm)).slice(0, 5);
  }, [products, searchTerm]);

  const addToCart = (product: Product, quantity: number = 1) => {
    const existing = cart.find(item => item.productId === product.id);
    if (existing) {
      setCart(cart.map(item => item.productId === product.id ? { ...item, quantity: item.quantity + quantity, totalCost: (item.quantity + quantity) * item.unitCost } : item));
    } else {
      setCart([...cart, { productId: product.id, productName: product.name, quantity, unitCost: product.costPrice, totalCost: product.costPrice * quantity }]);
    }
    setSearchTerm(''); setIsSearching(false);
  };

  const handleOCR = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]; if (!file) return;
    setIsLoading(true);
    const reader = new FileReader();
    reader.onload = async (event) => {
      try {
        const base64 = event.target?.result as string;
        const results = await processTicketWithGemini(base64);
        results.forEach(result => {
          const match = products.find(p => p.code === result.code || p.name.toLowerCase().includes(result.name.toLowerCase()));
          if (match) addToCart(match, result.quantity);
        });
      } catch (err) { alert("Error en OCR"); } finally { setIsLoading(false); }
    };
    reader.readAsDataURL(file);
  };

  const completeRestock = async () => {
    if (cart.length === 0) return;
    const total = cart.reduce((acc, item) => acc + item.totalCost, 0);
    if (status === 'Paid' && capitalBalance < total) {
      if (!confirm("El saldo del Sobre 4 es insuficiente. ¿Deseas continuar de todas formas?")) return;
    }

    setIsLoading(true);
    try {
      const note: PurchaseNote = { id: 'NOTE-' + Math.random().toString(36).substr(2, 9).toUpperCase(), date: new Date(date).toISOString(), provider: provider || 'Proveedor Gral', totalAmount: total, status, detailsJson: JSON.stringify(cart) };
      await dataService.saveRestockNote(note);
      setCart([]); setProvider('');
      alert("¡Compra registrada correctamente!");
    } catch (e) { alert("Error al registrar"); } finally { setIsLoading(false); }
  };

  const grandTotal = cart.reduce((acc, item) => acc + item.totalCost, 0);

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-10 animate-in fade-in slide-in-from-right-4 duration-500">
      <div className="lg:col-span-2 space-y-8">
        <div className="flex items-center justify-between">
          <h2 className="text-4xl font-black text-blue-900 tracking-tighter">Entrada de Mercancía</h2>
          <div className="flex items-center space-x-4">
            <div className="bg-white px-8 py-4 rounded-3xl border-2 border-blue-50 flex items-center space-x-4 shadow-xl shadow-blue-900/5">
              <Banknote className="text-red-600" size={32} />
              <div>
                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest block px-1">Bóveda de Capital</span>
                <span className="text-2xl font-black text-blue-900">${capitalBalance.toLocaleString()}</span>
              </div>
            </div>
            <button onClick={() => fileInputRef.current?.click()} className="bg-red-600 text-white p-5 rounded-3xl hover:bg-red-700 transition-all shadow-xl shadow-red-900/30 active:scale-95"><Camera size={28} /></button>
            <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleOCR} />
          </div>
        </div>

        <div className="bg-white p-10 rounded-[2.5rem] border border-blue-100 shadow-xl space-y-8">
          <div className="relative">
            <label className="block text-xs font-black text-blue-900 uppercase tracking-widest mb-3 px-1">Buscador Inteligente</label>
            <div className="relative">
              <Search className="absolute left-5 top-1/2 -translate-y-1/2 text-blue-400" size={24} />
              <input 
                type="text" 
                placeholder="Nombre o Código del artículo..." 
                value={searchTerm}
                onFocus={() => setIsSearching(true)}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-16 pr-6 py-5 bg-blue-50/50 border-2 border-transparent rounded-3xl focus:bg-white focus:border-blue-500 transition-all font-black text-xl text-slate-800"
              />
            </div>
            {isSearching && filteredProducts.length > 0 && (
              <div className="absolute top-full left-0 right-0 mt-3 bg-white border border-blue-100 rounded-[2rem] shadow-2xl z-50 overflow-hidden divide-y divide-blue-50 animate-in fade-in slide-in-from-top-2 duration-200">
                {filteredProducts.map(p => (
                  <button key={p.id} onClick={() => addToCart(p)} className="w-full p-6 flex items-center justify-between hover:bg-blue-50 transition-all group">
                    <div className="text-left">
                      <p className="font-black text-slate-800 text-lg group-hover:text-blue-600 transition-colors">{p.name}</p>
                      <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">Stock Actual: {p.stock}</p>
                    </div>
                    <span className="bg-red-50 text-red-600 px-5 py-2 rounded-2xl font-black text-base shadow-sm">${p.costPrice}</span>
                  </button>
                ))}
              </div>
            )}
          </div>
          <div className="grid grid-cols-2 gap-8">
            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">Proveedor</label>
              <input value={provider} onChange={(e) => setProvider(e.target.value)} className="w-full p-5 bg-slate-50 border-2 border-transparent rounded-2xl font-black text-slate-800 focus:bg-white focus:border-slate-300 transition-all" placeholder="Ej. Marinela / Pepsi" />
            </div>
            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">Fecha Factura</label>
              <input type="date" value={date} onChange={(e) => setDate(e.target.value)} className="w-full p-5 bg-slate-50 border-2 border-transparent rounded-2xl font-black text-slate-800 focus:bg-white focus:border-slate-300 transition-all" />
            </div>
          </div>
        </div>

        <div className="bg-white rounded-[2.5rem] border border-blue-100 overflow-hidden shadow-xl shadow-blue-900/5 divide-y divide-blue-50">
          <div className="p-6 bg-blue-50/50 flex items-center justify-between">
            <h3 className="text-sm font-black text-blue-900 uppercase tracking-widest flex items-center gap-2">
              <Package size={18} /> <span>Lista de Carga</span>
            </h3>
            <span className="text-[10px] font-black text-blue-400 uppercase">{cart.length} artículos</span>
          </div>
          {cart.map(item => (
            <div key={item.productId} className="p-8 flex items-center justify-between hover:bg-slate-50/50 transition-colors group">
              <div className="flex-1">
                <p className="font-black text-xl text-slate-800">{item.productName}</p>
                <div className="flex items-center gap-4 mt-1">
                  <span className="text-xs font-bold text-slate-400 flex items-center gap-1"><Tag size={12}/> ${item.unitCost} c/u</span>
                </div>
              </div>
              <div className="flex items-center space-x-8">
                <div className="flex items-center bg-blue-50 rounded-2xl p-1 border border-blue-100">
                  <input type="number" min="1" value={item.quantity} onChange={(e) => {
                    const val = parseInt(e.target.value) || 1;
                    setCart(cart.map(i => i.productId === item.productId ? {...i, quantity: val, totalCost: val * i.unitCost} : i));
                  }} className="w-20 p-3 bg-white rounded-xl text-center font-black text-blue-600 focus:outline-none" />
                </div>
                <span className="text-2xl font-black text-slate-900 w-32 text-right tracking-tighter">${item.totalCost.toFixed(2)}</span>
                <button onClick={() => setCart(cart.filter(i => i.productId !== item.productId))} className="text-slate-300 hover:text-red-600 hover:rotate-90 transition-all"><Trash2 size={24} /></button>
              </div>
            </div>
          ))}
          {cart.length === 0 && (
            <div className="py-24 text-center space-y-4">
              <ShoppingCart className="mx-auto text-blue-100" size={64} />
              <p className="text-blue-300 font-black italic text-xl">Tu lista de compra está vacía.</p>
            </div>
          )}
        </div>
      </div>

      <div className="lg:col-span-1">
        <div className="bg-blue-900 text-white p-10 rounded-[3rem] shadow-2xl h-full flex flex-col justify-between border-4 border-blue-800 sticky top-24 overflow-hidden relative">
          <div className="absolute top-0 right-0 w-32 h-32 bg-red-600/10 rounded-full blur-3xl -mr-16 -mt-16"></div>

          <div className="space-y-10 relative z-10">
            <h3 className="text-3xl font-black text-red-500 flex items-center space-x-3 tracking-tighter">
              <Calculator size={36}/>
              <span>Total Nota</span>
            </h3>

            <div className="space-y-6">
              <div className="flex justify-between text-blue-300 font-black uppercase text-xs tracking-widest px-2">
                <span>Subtotal:</span>
                <span>${grandTotal.toLocaleString()}</span>
              </div>
              <div className="p-8 bg-white/5 rounded-[2rem] border border-white/10 shadow-inner">
                <span className="text-blue-400 font-black text-[10px] uppercase tracking-[0.2em] mb-2 block">Importe a Pagar</span>
                <span className="text-6xl font-black text-white tracking-tighter block">${grandTotal.toLocaleString()}</span>
              </div>
            </div>

            <div className="space-y-3">
              <p className="text-xs font-black text-blue-400 uppercase tracking-widest px-2 mb-4">Estado de la Factura</p>
              <div className="grid grid-cols-2 gap-4">
                <button 
                  onClick={() => setStatus('Paid')} 
                  className={`py-5 rounded-2xl font-black transition-all border-2 text-sm tracking-widest ${status === 'Paid' ? 'bg-red-600 border-red-500 text-white shadow-lg shadow-red-900/40' : 'border-blue-800 text-blue-400 hover:bg-blue-800'}`}
                >
                  PAGADO
                </button>
                <button 
                  onClick={() => setStatus('Pending')} 
                  className={`py-5 rounded-2xl font-black transition-all border-2 text-sm tracking-widest ${status === 'Pending' ? 'bg-amber-600 border-amber-500 text-white shadow-lg shadow-amber-900/40' : 'border-blue-800 text-blue-400 hover:bg-blue-800'}`}
                >
                  DEUDA
                </button>
              </div>
            </div>
          </div>

          <button 
            onClick={completeRestock} 
            disabled={cart.length === 0 || isLoading} 
            className="w-full bg-red-600 py-7 rounded-3xl font-black text-2xl mt-12 hover:bg-red-500 transition-all shadow-2xl shadow-red-900/50 active:scale-95 disabled:opacity-30 disabled:grayscale tracking-tighter"
          >
            REGISTRAR COMPRA
          </button>
        </div>
      </div>
    </div>
  );
};

export default Restock;

import React, { useState, useMemo } from 'react';
import { Save, Calculator, CheckCircle2, Wallet, ArrowRight, RefreshCcw, Search, AlertCircle, Store } from 'lucide-react';
import { dataService } from '../services/dataService';

const DailyInventoryCount: React.FC = () => {
  const products = dataService.getProducts();
  const purchaseNotes = dataService.getPurchaseNotes();
  const envelopes = dataService.getEnvelopes();
  const [counts, setCounts] = useState<{ [key: string]: number }>({});
  const [searchTerm, setSearchTerm] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [summary, setSummary] = useState<any>(null);
  const [showDebtModal, setShowDebtModal] = useState(false);

  const filteredProducts = useMemo(() => {
    return products.filter(p => 
      p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
      p.code.includes(searchTerm)
    );
  }, [products, searchTerm]);

  const pendingNotes = useMemo(() => {
    const notes = purchaseNotes || [];
    return notes.filter((n: any) => n.status === 'Pending');
  }, [purchaseNotes]);

  const capitalBalance = envelopes.find(e => e.id === "ENV4")?.balance || 0;

  const handleCountChange = (id: string, val: string) => {
    setCounts({ ...counts, [id]: parseInt(val) || 0 });
  };

  const processClosing = async () => {
    if (Object.keys(counts).length === 0) return alert("Ingresa al menos un conteo físico.");

    setIsProcessing(true);
    try {
      const payload = Object.entries(counts).map(([id, val]) => ({ productId: id, physicalCount: val }));
      const res = await dataService.processPhysicalCount(payload, 'Daily Count');
      setSummary(res);
      if (pendingNotes.length > 0) setShowDebtModal(true);
    } catch (e) {
      alert("Error procesando el cierre.");
    } finally {
      setIsProcessing(false);
    }
  };

  const payNote = async (id: string) => {
    await dataService.updateNoteStatus(id, 'Paid');
    alert("Nota pagada con éxito");
  };

  if (summary) {
    return (
      <div className="max-w-2xl mx-auto space-y-8 animate-in zoom-in-95 duration-500">
        <div className="bg-white p-12 rounded-[3rem] border-4 border-red-50 shadow-[0_35px_60px_-15px_rgba(0,0,0,0.1)] space-y-10 text-center relative overflow-hidden">
          <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-red-600 to-blue-900"></div>

          <div className="bg-emerald-100 text-emerald-600 w-24 h-24 rounded-full flex items-center justify-center mx-auto shadow-inner">
            <CheckCircle2 size={56} />
          </div>

          <div>
            <h2 className="text-4xl font-black text-blue-900 tracking-tighter mb-2">Cierre de Caja Éxito</h2>
            <p className="text-slate-400 font-bold uppercase text-[10px] tracking-[0.3em]">Operación tiendita Certificada</p>
          </div>

          <div className="grid grid-cols-2 gap-6">
            <div className="p-8 bg-blue-50/50 rounded-[2.5rem] border border-blue-100 shadow-sm group hover:bg-blue-600 transition-all duration-500">
              <span className="text-[10px] font-black text-blue-400 uppercase tracking-widest block mb-1 group-hover:text-blue-100">Venta Bruta</span>
              <p className="text-3xl font-black text-blue-900 group-hover:text-white transition-colors">${summary.totalSold.toLocaleString()}</p>
            </div>
            <div className="p-8 bg-red-50/50 rounded-[2.5rem] border border-red-100 shadow-sm group hover:bg-red-600 transition-all duration-500">
              <span className="text-[10px] font-black text-red-400 uppercase tracking-widest block mb-1 group-hover:text-red-100">Utilidad Real</span>
              <p className="text-3xl font-black text-red-600 group-hover:text-white transition-colors">${summary.netProfit.toLocaleString()}</p>
            </div>
          </div>

          <div className="p-8 bg-slate-900 rounded-[2.5rem] text-left space-y-4 border-2 border-slate-800 shadow-xl shadow-slate-900/40">
            <div className="flex items-center space-x-3 text-red-500 font-black uppercase text-xs tracking-widest">
              <Wallet size={18} /> <span>Auditoría de Flujos</span>
            </div>
            <p className="text-sm text-slate-300 font-medium leading-relaxed">
              La utilidad se ha dividido en <strong className="text-white">3 partes iguales</strong> para los sobres operativos. El 100% del costo (<strong className="text-red-400">${summary.totalCOGS.toLocaleString()}</strong>) ha sido blindado en el <strong className="text-blue-400">Sobre 4 de Capital</strong>.
