function setupSheet() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheets = {
    "Products": ["id", "code", "name", "grams", "flavor", "costPrice", "salePrice", "stock", "category", "provider", "totalInvested", "totalEarned"],
    "Outputs": ["id", "productId", "productName", "quantity", "salePrice", "totalSale", "date", "shift"],
    "Closings": ["id", "date", "totalSold", "netProfit", "cogs"],
    "PurchaseNotes": ["id", "date", "provider", "totalAmount", "status", "detailsJson"],
    "Envelopes": ["id", "name", "balance", "description", "lastResetDate"],
    "EnvelopeHistory": ["id", "envelopeId", "envelopeName", "amount", "startDate", "endDate", "durationText", "notes"],
    "PriceHistory": ["id", "productId", "productName", "field", "oldValue", "newValue", "date"]
  };

  for (let name in sheets) {
    let sheet = ss.getSheetByName(name);
    if (!sheet) {
      sheet = ss.insertSheet(name);
      sheet.appendRow(sheets[name]);
      sheet.getRange(1, 1, 1, sheets[name].length).setFontWeight("bold").setBackground("#f3f4f6");
      sheet.setFrozenRows(1);
    }
  }

  // Inicializar Sobres
  const envSheet = ss.getSheetByName("Envelopes");
  if (envSheet.getLastRow() <= 1) {
    const now = new Date().toISOString();
    const envData = [
      ["ENV1", "Sobre 1 - Operativo", 0, "1/3 Utilidad Neta", now],
      ["ENV2", "Sobre 2 - Ahorro", 0, "1/3 Utilidad Neta", now],
      ["ENV3", "Sobre 3 - Expansión", 0, "1/3 Utilidad Neta", now],
      ["ENV4", "Sobre 4 - Capital", 0, "Fondo Resurtido (Costos)", now]
    ];
    envSheet.getRange(2, 1, envData.length, 5).setValues(envData);
  }

  return "tiendita inicializada con éxito.";
}

function withdrawEnvelope(withdrawal) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const envSheet = ss.getSheetByName("Envelopes");
  const histSheet = ss.getSheetByName("EnvelopeHistory");

  const data = envSheet.getDataRange().getValues();
  for (let i = 1; i < data.length; i++) {
    if (data[i][0] == withdrawal.envelopeId) {
      // 1. Resetear balance y actualizar fecha en Envelopes
      envSheet.getRange(i + 1, 3).setValue(0);
      envSheet.getRange(i + 1, 5).setValue(new Date().toISOString());

      // 2. Guardar en Historial
      histSheet.appendRow([
        withdrawal.id,
        withdrawal.envelopeId,
        withdrawal.envelopeName,
        withdrawal.amount,
        withdrawal.startDate,
        withdrawal.endDate,
        withdrawal.durationText,
        withdrawal.notes
      ]);
      return true;
    }
  }
  return false;
}

function processPhysicalCount(counts, shift) {
  const products = getProducts();
  let totalSold = 0;
  let totalCOGS = 0;

  counts.forEach(c => {
    const prod = products.find(p => p.id == c.productId || p.code == c.productId);
    if (prod && prod.stock > c.physicalCount) {
      const soldQty = prod.stock - c.physicalCount;
      const soldAmount = soldQty * prod.salePrice;
      const costAmount = soldQty * prod.costPrice;

      totalSold += soldAmount;
      totalCOGS += costAmount;

      addOutput({
        id: Utilities.getUuid(),
        productId: prod.id,
        productName: prod.name,
        quantity: soldQty,
        salePrice: prod.salePrice,
        totalSale: soldAmount,
        date: new Date().toISOString(),
        shift: shift
      });
    }
  });

  const netProfit = totalSold - totalCOGS;
  if (netProfit > 0) {
    const part = netProfit / 3;
    updateEnvelopeBalance("ENV1", part);
    updateEnvelopeBalance("ENV2", part);
    updateEnvelopeBalance("ENV3", part);
  }
  updateEnvelopeBalance("ENV4", totalCOGS);

  saveClosing({
    id: Utilities.getUuid(),
    date: new Date().toISOString(),
    totalSold,
    netProfit,
    cogs: totalCOGS
  });

  return { totalSold, netProfit, totalCOGS };
}

function updateEnvelopeBalance(id, amount) {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("Envelopes");
  const data = sheet.getDataRange().getValues();
  for (let i = 1; i < data.length; i++) {
    if (data[i][0] == id) {
      sheet.getRange(i + 1, 3).setValue(Number(data[i][2]) + amount);
      return true;
    }
  }
}

function getDashboardData() {
  const products = getProducts();
  const envelopes = getEnvelopes();
  const outputs = getOutputs();

  const netProfit = envelopes.filter(e => e.id !== 'ENV4').reduce((acc, e) => acc + Number(e.balance), 0);
  const capital = envelopes.find(e => e.id === 'ENV4')?.balance || 0;

  const stats = outputs.reduce((acc, out) => {
    if (!acc[out.productId]) acc[out.productId] = { name: out.productName, volume: 0, profit: 0 };
    const p = products.find(prod => prod.id == out.productId);
    acc[out.productId].volume += Number(out.quantity);
    acc[out.productId].profit += (Number(out.totalSale) - (Number(out.quantity) * (p?.costPrice || 0)));
    return acc;
  }, {});

  const statsArray = Object.values(stats);

  return {
    envelopes,
    profitVsCapital: [
      { name: 'Utilidad Neta', value: netProfit },
      { name: 'Fondo Resurtido', value: Number(capital) }
    ],
    topVolume: statsArray.sort((a, b) => b.volume - a.volume).slice(0, 3),
    topProfit: statsArray.sort((a, b) => b.profit - a.profit).slice(0, 3)
  };
}

function getProducts() { const s = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("Products"); if(!s) return []; const d = s.getDataRange().getValues(); const h = d[0]; return d.slice(1).map(r => { let o = {}; h.forEach((k, i) => o[k] = r[i]); return o; }); }
function getEnvelopes() { const s = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("Envelopes"); if(!s) return []; const d = s.getDataRange().getValues(); const h = d[0]; return d.slice(1).map(r => { let o = {}; h.forEach((k, i) => o[k] = r[i]); return o; }); }
function getEnvelopeHistory() { const s = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("EnvelopeHistory"); if(!s) return []; const d = s.getDataRange().getValues(); const h = d[0]; return d.slice(1).map(r => { let o = {}; h.forEach((k, i) => o[k] = r[i]); return o; }); }
function getOutputs() { const s = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("Outputs"); if(!s) return []; const d = s.getDataRange().getValues(); const h = d[0]; return d.slice(1).map(r => { let o = {}; h.forEach((k, i) => o[k] = r[i]); return o; }); }
function addOutput(t) { const s = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("Outputs"); s.appendRow(["id", "productId", "productName", "quantity", "salePrice", "totalSale", "date", "shift"].map(h => t[h])); updateStock(t.productId, -t.quantity, 0, t.totalSale); }
function updateStock(pId, qty, inv, earn) { const s = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("Products"); const d = s.getDataRange().getValues(); for(let i=1; i<d.length; i++) { if(d[i][0] == pId) { s.getRange(i+1, 8).setValue(Number(d[i][7]) + qty); s.getRange(i+1, 11).setValue(Number(d[i][10]) + inv); s.getRange(i+1, 12).setValue(Number(d[i][11]) + earn); break; } } }
function saveClosing(c) { SpreadsheetApp.getActiveSpreadsheet().getSheetByName("Closings").appendRow(["id", "date", "totalSold", "netProfit", "cogs"].map(h => c[h])); }
function getPurchaseNotes() { const s = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("PurchaseNotes"); return s ? s.getDataRange().getValues().slice(1).map(r => { let o = {}; s.getDataRange().getValues()[0].forEach((h, i) => o[h] = r[i]); return o; }) : []; }
function saveRestockNote(note) { 
  SpreadsheetApp.getActiveSpreadsheet().getSheetByName("PurchaseNotes").appendRow(["id", "date", "provider", "totalAmount", "status", "detailsJson"].map(h => note[h])); 
  const details = JSON.parse(note.detailsJson);
  details.forEach(item => updateStock(item.productId, item.quantity, item.totalCost, 0));
  if(note.status === 'Paid') updateEnvelopeBalance("ENV4", -note.totalAmount);
  return true;
}
function updateNoteStatus(id, status) {
