              <Banknote className="text-red-600" size={32} />
              <div>
                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest block px-1">Bóveda de Capital</span>
                <span className="text-2xl font-black text-blue-900">${capitalBalance.toLocaleString()}</span>
              </div>
            </div>
            <button onClick={() => fileInputRef.current?.click()} className="bg-red-600 text-white p-5 rounded-3xl hover:bg-red-700 transition-all shadow-xl shadow-red-900/30 active:scale-95"><Camera size={28} /></button>
            <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleOCR} />
          </div>
        </div>

        <div className="bg-white p-10 rounded-[2.5rem] border border-blue-100 shadow-xl space-y-8">
          <div className="relative">
            <label className="block text-xs font-black text-blue-900 uppercase tracking-widest mb-3 px-1">Buscador Inteligente</label>
            <div className="relative">
              <Search className="absolute left-5 top-1/2 -translate-y-1/2 text-blue-400" size={24} />
              <input 
                type="text" 
                placeholder="Nombre o Código del artículo..." 
                value={searchTerm}
                onFocus={() => setIsSearching(true)}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-16 pr-6 py-5 bg-blue-50/50 border-2 border-transparent rounded-3xl focus:bg-white focus:border-blue-500 transition-all font-black text-xl text-slate-800"
              />
            </div>
            {isSearching && filteredProducts.length > 0 && (
              <div className="absolute top-full left-0 right-0 mt-3 bg-white border border-blue-100 rounded-[2rem] shadow-2xl z-50 overflow-hidden divide-y divide-blue-50 animate-in fade-in slide-in-from-top-2 duration-200">
                {filteredProducts.map(p => (
                  <button key={p.id} onClick={() => addToCart(p)} className="w-full p-6 flex items-center justify-between hover:bg-blue-50 transition-all group">
                    <div className="text-left">
                      <p className="font-black text-slate-800 text-lg group-hover:text-blue-600 transition-colors">{p.name}</p>
                      <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">Stock Actual: {p.stock}</p>
                    </div>
                    <span className="bg-red-50 text-red-600 px-5 py-2 rounded-2xl font-black text-base shadow-sm">${p.costPrice}</span>
