function setupSheet() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheets = {
    "Products": ["id", "code", "name", "grams", "flavor", "costPrice", "salePrice", "stock", "category", "provider", "totalInvested", "totalEarned"],
    "Outputs": ["id", "productId", "productName", "quantity", "salePrice", "totalSale", "date", "shift"],
    "Closings": ["id", "date", "totalSold", "netProfit", "cogs"],
    "PurchaseNotes": ["id", "date", "provider", "totalAmount", "status", "detailsJson"],
    "Envelopes": ["id", "name", "balance", "description", "lastResetDate"],
    "EnvelopeHistory": ["id", "envelopeId", "envelopeName", "amount", "startDate", "endDate", "durationText", "notes"],
    "PriceHistory": ["id", "productId", "productName", "field", "oldValue", "newValue", "date"]
  };

  for (let name in sheets) {
    let sheet = ss.getSheetByName(name);
    if (!sheet) {
      sheet = ss.insertSheet(name);
      sheet.appendRow(sheets[name]);
    }
  }

  // Inicializar Sobres si están vacíos
  const envSheet = ss.getSheetByName("Envelopes");
  if (envSheet.getLastRow() <= 1) {
    const now = new Date().toISOString();
    const envData = [
      ["ENV1", "Sobre 1 - Operativo", 0, "1/3 Utilidad", now],
      ["ENV2", "Sobre 2 - Ahorro", 0, "1/3 Utilidad", now],
      ["ENV3", "Sobre 3 - Expansión", 0, "1/3 Utilidad", now],
      ["ENV4", "Sobre 4 - Capital", 0, "Fondo Resurtido", now]
    ];
    envSheet.getRange(2, 1, envData.length, 5).setValues(envData);
  }
  return "Tienda lista.";
}

// Funciones CRUD para React
function getProducts() {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("Products");
  if(!sheet) return [];
  const data = sheet.getDataRange().getValues();
  const headers = data[0];
  return data.slice(1).map(r => {
    let obj = {};
    headers.forEach((h, i) => obj[h] = r[i]);
    return obj;
  });
}

function getDashboardData() {
  const envSheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("Envelopes");
  const data = envSheet.getDataRange().getValues();
  const envelopes = data.slice(1).map(r => ({ id: r[0], name: r[1], balance: r[2] }));
  return { envelopes };
}

function saveProduct(p) {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("Products");
  sheet.appendRow([p.id, p.code, p.name, p.grams, p.flavor, p.costPrice, p.salePrice, p.stock, p.category, p.provider, p.totalInvested, p.totalEarned]);
  return true;
}

