const isGasEnv = () => {
  const g = (window as any).google;
  return typeof g !== 'undefined' && g.script && g.script.run;
};

const runGas = (functionName: string, ...args: any[]): Promise<any> => {
  const google = (window as any).google;
  if (isGasEnv()) {
    return new Promise((resolve, reject) => {
      google.script.run
        .withSuccessHandler(resolve)
        .withFailureHandler(reject)[functionName](...args);
    });
  } else {
    // Mock para desarrollo local
    console.warn(`Ejecutando mock para: ${functionName}`);
    return new Promise((resolve) => {
      setTimeout(() => {
        if (functionName === 'getProducts') resolve([]);
        if (functionName === 'getDashboardData') resolve({
          envelopes: [
            { id: "ENV1", name: "Operativo", balance: 0, description: "1/3 Utilidad", lastResetDate: new Date().toISOString() },
            { id: "ENV4", name: "Capital", balance: 0, description: "Fondo Resurtido", lastResetDate: new Date().toISOString() }
          ],
          profitVsCapital: [{name: 'Utilidad', value: 0}, {name: 'Capital', value: 0}],
          topVolume: [],
          topProfit: []
        });
        resolve(null);
      }, 500);
    });
  }
};

const processTicketWithGemini = async (base64Image: string) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });
  const prompt = `Analyze this purchase ticket/invoice image. Extract the following information for each item as a JSON array.
  Look for: Name/Description, Cost Price per unit, and Quantity.`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: {
        parts: [
          { inlineData: { data: base64Image.split(',')[1] || base64Image, mimeType: "image/jpeg" } },
          { text: prompt }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING },
              costPrice: { type: Type.NUMBER },
              quantity: { type: Type.NUMBER },
            },
            required: ["name", "costPrice", "quantity"]
          }
        }
      }
    });
    return JSON.parse(response.text || "[]");
  } catch (error) {
    console.error("Gemini OCR error:", error);
    throw new Error("Fallo al procesar imagen con IA.");
  }
};

