const ProductRegistration = () => {
  const [form, setForm] = useState({ name: '', cost: '', sale: '', stock: '', code: '' });
  const [loading, setLoading] = useState(false);
  const fileRef = useRef<HTMLInputElement>(null);

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    await runGas('saveProduct', { ...form, id: Math.random().toString(36).substr(2, 9) });
    setForm({ name: '', cost: '', sale: '', stock: '', code: '' });
    setLoading(false);
    alert("Producto guardado exitosamente");
  };

  const handleOCR = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]; if (!file) return;
    setLoading(true);
    const reader = new FileReader();
    reader.onload = async (ev) => {
        try {
            const results = await processTicketWithGemini(ev.target?.result as string);
            if (results.length > 0) {
                setForm(f => ({ ...f, name: results[0].name, cost: results[0].costPrice.toString(), stock: results[0].quantity.toString() }));
            }
        } catch (err) { alert("Error en OCR"); } finally { setLoading(false); }
    };
    reader.readAsDataURL(file);
  };

  return (
