            <button onClick={() => { setSyncing(true); runGas('setupSheet').then(() => setSyncing(false)); }} className="flex items-center space-x-2 text-red-600 font-bold">
              <RefreshCcw className={syncing ? 'animate-spin' : ''} size={18} />
              <span>{syncing ? 'Sincronizando...' : 'Sincronizar'}</span>
            </button>
          </header>
