function doGet() {
  return HtmlService.createHtmlOutputFromFile('index')
    .setTitle('tiendita - Gestión POS')
    .setXFrameOptionsMode(HtmlService.XFrameOptionsMode.ALLOWALL)
    .addMetaTag('viewport', 'width=device-width, initial-scale=1');
}

function getDashboardData() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  let sheet = ss.getSheetByName("Envelopes");
  if (!sheet) { setupSheet(); sheet = ss.getSheetByName("Envelopes"); }
  const data = sheet.getDataRange().getValues();
  const envs = data.slice(1).map(r => ({ id: r[0], name: r[1], balance: r[2] || 0 }));
  return {
    envelopes: envs,
    profitVsCapital: [
      { name: 'Utilidad', value: envs.filter(e => e.id !== 'ENV4').reduce((a, b) => a + b.balance, 0) },
      { name: 'Capital', value: envs.find(e => e.id === 'ENV4')?.balance || 0 }
    ]
  };
}

function saveProduct(p) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  let sheet = ss.getSheetByName("Products") || ss.insertSheet("Products");
  sheet.appendRow([p.id, p.code, p.name, "", "", p.cost, p.sale, p.stock]);
  return true;
}

function setupSheet() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheets = {
    "Products": ["id", "code", "name", "grams", "flavor", "costPrice", "salePrice", "stock"],
    "Envelopes": ["id", "name", "balance", "description", "lastResetDate"]
  };
  for (let name in sheets) {
    if (!ss.getSheetByName(name)) {
      let s = ss.insertSheet(name);
      s.appendRow(sheets[name]);
      if (name === "Envelopes") {
        const now = new Date().toISOString();
        s.appendRow(["ENV1", "Operativo", 0, "1/3 Utilidad", now]);
        s.appendRow(["ENV2", "Ahorro", 0, "1/3 Utilidad", now]);
        s.appendRow(["ENV3", "Ganancia", 0, "1/3 Utilidad", now]);
        s.appendRow(["ENV4", "Capital", 0, "Fondo Resurtido", now]);
      }
    }
  }
  return "OK";
}

payload.text:
Para desplegar en **Vercel** y usar **Google Sheets** como base de datos, necesitamos cambiar la arquitectura. Ya no usaremos `google.script.run` (que solo funciona dentro de Google), sino que haremos peticiones `fetch` a tu script de Google actuando como una **API REST**.

### Especificaciones de la Solución para Vercel:

1.  **Frontend (Vercel)**: Una aplicación React profesional que se comunica con el exterior mediante `fetch`.
2.  **Backend (Google Apps Script API)**: Tu script de Google ahora recibirá datos en formato JSON, los guardará en la hoja y responderá con JSON.
3.  **Seguridad y CORS**: El script de Google debe configurarse para permitir peticiones externas (CORS) devolviendo `ContentService`.
4.  **Configuración de IA**: Seguimos usando **Gemini 2.5/3** para el OCR de tickets directamente desde el cliente (Vercel) para máxima velocidad.

### Paso 1: Actualiza tu código en Google Apps Script (`Code.gs`)
Copia esto en tu editor de Google Sheets. Es vital para que Vercel pueda "hablar" con la hoja.

```javascript
// --- Code.gs (En Google Apps Script) ---

function doPost(e) {
  const params = JSON.parse(e.postData.contents);
  const action = params.action;
  const data = params.data;

  let result;
  if (action === 'saveProduct') result = saveProduct(data);
  if (action === 'saveClosing') result = saveClosing(data);
  if (action === 'processPhysicalCount') result = processPhysicalCount(data.counts, data.shift);
  if (action === 'setup') result = setupSheet();

  return ContentService.createTextOutput(JSON.stringify({success: true, result: result}))
    .setMimeType(ContentService.MimeType.JSON);
}

function doGet(e) {
  const action = e.parameter.action;
  let data;

  if (action === 'getDashboardData') data = getDashboardData();
  if (action === 'getProducts') data = getProducts();

  return ContentService.createTextOutput(JSON.stringify(data))
    .setMimeType(ContentService.MimeType.JSON);
}

// ... (Mantén tus funciones getDashboardData, saveProduct, etc., del paso anterior) ...
```
*Nota: Asegúrate de publicar el script como "Web App", con acceso a "Anyone" (incluso anónimo) para que Vercel pueda conectar.*

### Paso 2: Código para Vercel (Frontend)

