function doGet(e) {
  const action = e.parameter.action;
  let result;

  if (action === 'getDashboardData') result = getDashboardData();
  if (action === 'getProducts') result = getProducts();
  if (action === 'getEnvelopes') result = getEnvelopes();

  return ContentService.createTextOutput(JSON.stringify(result))
    .setMimeType(ContentService.MimeType.JSON);
}

function doPost(e) {
  const params = JSON.parse(e.postData.contents);
  const action = params.action;
  const data = params.data;
  let result;

  if (action === 'saveProduct') result = saveProduct(data);
  if (action === 'setup') result = setupSheet();

  return ContentService.createTextOutput(JSON.stringify({success: true, result: result}))
    .setMimeType(ContentService.MimeType.JSON);
}

function getDashboardData() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  let envSheet = ss.getSheetByName("Envelopes") || setupSheet();
  const data = envSheet.getDataRange().getValues();
  const envs = data.slice(1).map(r => ({ id: r[0], name: r[1], balance: r[2] || 0 }));

  return {
    envelopes: envs,
    profitVsCapital: [
      { name: 'Utilidad', value: envs.filter(e => e.id !== 'ENV4').reduce((a, b) => a + b.balance, 0) },
      { name: 'Capital', value: envs.find(e => e.id === 'ENV4')?.balance || 0 }
    ]
  };
}

function getProducts() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheetByName("Products");
  if (!sheet) return [];
  const data = sheet.getDataRange().getValues();
  return data.slice(1).map(r => ({
    id: r[0],
    code: r[1],
    name: r[2],
    costPrice: r[5],
    salePrice: r[6],
    stock: r[7]
  }));
}

function saveProduct(p) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheetByName("Products") || ss.insertSheet("Products");
  sheet.appendRow([p.id, p.code, p.name, "", "", p.cost, p.sale, p.stock]);
  return true;
}

function setupSheet() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  if (!ss.getSheetByName("Products")) {
    const s = ss.insertSheet("Products");
    s.appendRow(["id", "code", "name", "grams", "flavor", "costPrice", "salePrice", "stock"]);
  }
  if (!ss.getSheetByName("Envelopes")) {
    const s = ss.insertSheet("Envelopes");
    s.appendRow(["id", "name", "balance", "description", "lastResetDate"]);
    const now = new Date().toISOString();
    s.appendRow(["ENV1", "Operativo", 0, "Utilidad", now]);
    s.appendRow(["ENV4", "Capital", 0, "Resurtido", now]);
  }
  return ss.getSheetByName("Envelopes");
}

payload.text:
Para conectar **Vercel** (Frontend) con **Google Apps Script** (Base de Datos), seguiremos una arquitectura de **API REST**. Vercel enviará peticiones y Google Sheets responderá.

Aquí tienes el paso a paso detallado para realizar la conexión:

### Paso 1: Configurar el "Backend" en Google Apps Script (`Code.gs`)

Debes modificar tu archivo `.gs` para que pueda recibir peticiones externas desde Vercel. Google Apps Script usa las funciones `doGet(e)` y `doPost(e)` para esto.

1.  Abre tu **Google Sheet**.
2.  Ve a **Extensiones > Apps Script**.
3.  Reemplaza el contenido de `Code.gs` por este código (que está preparado para recibir comandos desde fuera):

```javascript
/**
 * BACKEND API PARA VERCEL
 */

function doGet(e) {
  const action = e.parameter.action;
  let result;

  if (action === 'getDashboardData') result = getDashboardData();
  if (action === 'getProducts') result = getProducts();
  if (action === 'getEnvelopes') result = getEnvelopes();

  return ContentService.createTextOutput(JSON.stringify(result))
    .setMimeType(ContentService.MimeType.JSON);
}

function doPost(e) {
  const params = JSON.parse(e.postData.contents);
  const action = params.action;
  const data = params.data;
  let result;

  if (action === 'saveProduct') result = saveProduct(data);
  if (action === 'withdrawEnvelope') result = withdrawEnvelope(data);
  if (action === 'processPhysicalCount') result = processPhysicalCount(data.counts, data.shift);

  return ContentService.createTextOutput(JSON.stringify({success: true, result: result}))
    .setMimeType(ContentService.MimeType.JSON);
}

// ... AQUÍ PEGA TUS FUNCIONES EXISTENTES (getDashboardData, saveProduct, etc.) ...
// Asegúrate de que las funciones no dependan de Session.getActiveUser() si vas a usar acceso anónimo.
```

### Paso 2: Implementar (Deploy) la Web App

Este es el paso más importante para que Vercel pueda "ver" tu script.

1.  En el editor de Apps Script, haz clic en el botón azul **Implementar (Deploy)** > **Nueva implementación**.
2.  Selecciona el tipo **Aplicación web**.
3.  **Descripción**: "API para Vercel".
4.  **Ejecutar como**: "Yo" (Tu cuenta).
5.  **Quién tiene acceso**: **"Cualquiera" (Anyone)**. *Esto es vital para que Vercel no sea bloqueado por Google.*
6.  Haz clic en **Implementar**.
7.  **Copia la URL de la aplicación web** (termina en `/exec`). La necesitarás ahora.

---

### Paso 3: Actualizar el Frontend en Vercel (`index.tsx`)

Ahora debemos decirle a tu aplicación de React que deje de usar `google.script.run` (que solo funciona dentro de Google) y empiece a usar `fetch` hacia la URL que acabas de copiar.

