    });
  } else {
    try {
      // Para GET (Lectura)
      if (functionName.startsWith('get')) {
        const response = await fetch(`${GAS_API_URL}?action=${functionName}`, {
          method: 'GET',
          redirect: 'follow'
        });
        if (!response.ok) throw new Error('Error en respuesta de Google');
        return await response.json();
      } 
      // Para POST (Escritura)
      else {
        // Usamos una URL con parámetro para evitar problemas de CORS en el cuerpo
        const response = await fetch(`${GAS_API_URL}?action=${functionName}`, {
          method: 'POST',
          mode: 'no-cors', // Google Apps Script requiere no-cors para POST externos
          headers: { 'Content-Type': 'text/plain' },
          body: JSON.stringify(args[0] || {})
        });
        // Como es no-cors, no podemos leer la respuesta, pero asumimos éxito si no hay error de red
        return { success: true };
      }
    } catch (e) {
      console.error(`Error en ${functionName}:`, e);
      return null;
    }
  }
};

