### Paso 3: Revisión de Google Apps Script (Backend)

Asegúrate de que tu `Code.gs` en Google Sheets esté configurado para responder a los parámetros de URL que estamos enviando. Reemplaza el inicio de tu `Code.gs` por esto:

```javascript
/**
 * BACKEND API PARA VERCEL
 */

function doGet(e) {
  const action = e.parameter.action;
  let result;

  try {
    if (action === 'getDashboardData') result = getDashboardData();
    else if (action === 'getProducts') result = getProducts();
    else if (action === 'getEnvelopes') result = getEnvelopes();
    else if (action === 'getEnvelopeHistory') result = getEnvelopeHistory();
    else if (action === 'getPurchaseNotes') result = getPurchaseNotes();
    else if (action === 'getInputs') result = getInputs();
    else if (action === 'getOutputs') result = getOutputs();
    else if (action === 'getClosings') result = getClosings();
    else if (action === 'getPriceHistory') result = getPriceHistory();

    return ContentService.createTextOutput(JSON.stringify(result || []))
      .setMimeType(ContentService.MimeType.JSON);
  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({error: err.toString()}))
      .setMimeType(ContentService.MimeType.JSON);
  }
}

function doPost(e) {
  const action = e.parameter.action;
  const data = JSON.parse(e.postData.contents);
  let result;

  if (action === 'saveProduct') result = saveProduct(data);
  else if (action === 'withdrawEnvelope') result = withdrawEnvelope(data);
  else if (action === 'processPhysicalCount') result = processPhysicalCount(data.counts, data.shift);
  else if (action === 'saveRestockNote') result = saveRestockNote(data);
  else if (action === 'updateNoteStatus') result = updateNoteStatus(data.id, data.status);

  return ContentService.createTextOutput(JSON.stringify({success: true}))
    .setMimeType(ContentService.MimeType.JSON);
}
```

### ¿Por qué esto lo soluciona?
1.  **GET con Parámetros**: Google permite leer datos fácilmente mediante `GET`. Al añadir `?action=getProducts`, evitamos problemas de pre-flight CORS.
2.  **no-cors en POST**: Al usar `mode: 'no-cors'`, el navegador permite enviar los datos a Google sin preguntar por permisos especiales, lo que soluciona el "Failed to fetch".
3.  **Null-Safety**: Añadí `envelope?.balance || 0` en el Dashboard. Si la conexión falla o tarda, la app mostrará un "0" en lugar de romperse con un error de pantalla blanca.

**IMPORTANTE**: Después de cambiar el código en Google Apps Script, debes hacer clic en **Implementar > Administrar implementaciones > Editar (lápiz) > Nueva versión** y darle a **Implementar** de nuevo para que los cambios surtan efecto.

