/**
 * tiendita - Backend API v2.8
 * Maneja persistencia real en Google Sheets con soporte para edición y borrado
 */

function doPost(e) {
  const params = JSON.parse(e.postData.contents);
  const action = params.action;
  const data = params.data;

  let result;
  try {
    switch(action) {
      case 'getProducts': result = getProducts(); break;
      case 'getEnvelopes': result = getEnvelopes(); break;
      case 'getDashboardData': result = getDashboardData(); break;
      case 'saveProduct': result = saveProduct(data); break;
      case 'deleteProduct': result = deleteProduct(data); break;
      case 'saveRestockNote': result = saveRestockNote(data); break;
      case 'updateNoteStatus': result = updateNoteStatus(data.id, data.status); break;
      case 'processPhysicalCount': result = processPhysicalCount(data.counts, data.shift); break;
      case 'withdrawEnvelope': result = withdrawEnvelope(data); break;
      case 'saveOutput': result = saveOutput(data); break;
      case 'saveClosing': result = saveClosing(data); break;
      case 'deleteRecord': result = deleteRecord(data.sheet, data.id); break;
      case 'updateRecord': result = updateRecord(data.sheet, data.id, data.data); break;
      case 'getEnvelopeHistory': result = getSheetData("EnvelopeHistory"); break;
      case 'getPurchaseNotes': result = getSheetData("PurchaseNotes"); break;
      case 'getInputs': result = getSheetData("Inputs"); break;
      case 'getOutputs': result = getSheetData("Outputs"); break;
      case 'getClosings': result = getSheetData("Closings"); break;
      case 'getPriceHistory': result = getSheetData("PriceHistory"); break;
      case 'setup': result = setupSheet(); break;
      default: throw new Error("Acción no reconocida: " + action);
    }

    return ContentService.createTextOutput(JSON.stringify(result))
      .setMimeType(ContentService.MimeType.JSON);
  } catch (error) {
    return ContentService.createTextOutput(JSON.stringify({error: error.toString()}))
      .setMimeType(ContentService.MimeType.JSON);
  }
}

function getSheet(name) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  let sheet = ss.getSheetByName(name);
  if (!sheet) {
    setupSheet();
    sheet = ss.getSheetByName(name);
  }
  return sheet;
}

function getSheetData(name) {
  const sheet = getSheet(name);
  const values = sheet.getDataRange().getValues();
  if (values.length <= 1) return [];
  const headers = values[0];
  return values.slice(1).map(row => {
    let obj = {};
    headers.forEach((h, i) => obj[h] = row[i]);
    return obj;
  });
}

function deleteRecord(sheetName, id) {
  const sheet = getSheet(sheetName);
  const data = sheet.getDataRange().getValues();
  for(let i=1; i<data.length; i++) {
    if(data[i][0] == id) {
      sheet.deleteRow(i + 1);
      return {success: true};
    }
  }
  return {success: false, error: "ID no encontrado en " + sheetName};
}

function updateRecord(sheetName, id, newData) {
  const sheet = getSheet(sheetName);
  const data = sheet.getDataRange().getValues();
  const headers = data[0];

  for(let i=1; i<data.length; i++) {
    if(data[i][0] == id) {
      const rowNum = i + 1;
      for(let key in newData) {
        const colIdx = headers.indexOf(key);
        if(colIdx > -1) {
          sheet.getRange(rowNum, colIdx + 1).setValue(newData[key]);
        }
      }
      return {success: true};
    }
  }
  return {success: false, error: "ID no encontrado para actualizar en " + sheetName};
}

function getProducts() { return getSheetData("Products"); }
function getEnvelopes() { return getSheetData("Envelopes"); }

function saveProduct(p) {
  const sheet = getSheet("Products");
  const data = sheet.getDataRange().getValues();
  let foundIndex = -1;
  for(let i=1; i<data.length; i++) { if(data[i][0] === p.id) { foundIndex = i + 1; break; } }
  const row = [p.id, p.code, p.name, p.grams, p.flavor, p.costPrice, p.salePrice, p.stock, p.category, p.provider, p.totalInvested, p.totalEarned];
  if(foundIndex > -1) { sheet.getRange(foundIndex, 1, 1, row.length).setValues([row]); } else { sheet.appendRow(row); }
  return {success: true};
}

function deleteProduct(id) {
  const sheet = getSheet("Products");
  const data = sheet.getDataRange().getValues();
  for(let i=1; i<data.length; i++) { if(data[i][0] === id) { sheet.deleteRow(i + 1); break; } }
  return {success: true};
}

function saveRestockNote(note) {
  const noteSheet = getSheet("PurchaseNotes");
  noteSheet.appendRow([note.id, note.date, note.provider, note.totalAmount, note.status, note.detailsJson]);
  const details = JSON.parse(note.detailsJson);
  const inputSheet = getSheet("Inputs");
  const productSheet = getSheet("Products");
  const productData = productSheet.getDataRange().getValues();
  details.forEach(item => {
    inputSheet.appendRow([Utilities.getUuid(), item.productId, item.productName, item.quantity, item.unitCost, item.totalCost, note.date, note.provider]);
    for(let i=1; i<productData.length; i++) {
      if(productData[i][0] === item.productId) {
        let currentStock = Number(productData[i][7]);
        let currentInvested = Number(productData[i][10]);
        productSheet.getRange(i+1, 8).setValue(currentStock + item.quantity);
        productSheet.getRange(i+1, 6).setValue(item.unitCost);
        productSheet.getRange(i+1, 11).setValue(currentInvested + item.totalCost);
      }
    }
  });
  if (note.status === 'Paid') { updateEnvelopeBalance("ENV4", -note.totalAmount); }
  return {success: true};
}

function updateNoteStatus(id, status) {
  const sheet = getSheet("PurchaseNotes");
  const data = sheet.getDataRange().getValues();
  for(let i=1; i<data.length; i++) {
    if(data[i][0] === id) {
      sheet.getRange(i+1, 5).setValue(status);
      if(status === 'Paid') { updateEnvelopeBalance("ENV4", -Number(data[i][3])); }
      break;
    }
  }
  return {success: true};
}

function processPhysicalCount(counts, shift) {
  const productSheet = getSheet("Products");
  const outputSheet = getSheet("Outputs");
  const productData = productSheet.getDataRange().getValues();
  const date = new Date().toISOString();
  let totalSold = 0;
  let totalCOGS = 0;
  counts.forEach(count => {
    for(let i=1; i<productData.length; i++) {
      if(productData[i][0] === count.productId) {
        const systemStock = Number(productData[i][7]);
        const diff = systemStock - count.physicalCount;
        if (diff > 0) {
          const salePrice = Number(productData[i][6]);
          const costPrice = Number(productData[i][5]);
          const totalSale = diff * salePrice;
          const totalCost = diff * costPrice;
          totalSold += totalSale;
          totalCOGS += totalCost;
          outputSheet.appendRow([Utilities.getUuid(), count.productId, productData[i][2], diff, salePrice, totalSale, date, shift]);
          productSheet.getRange(i+1, 8).setValue(count.physicalCount);
          let currentEarned = Number(productData[i][11]);
          productSheet.getRange(i+1, 12).setValue(currentEarned + totalSale);
        }
      }
    }
  });
  const netProfit = totalSold - totalCOGS;
  saveClosing({id: Utilities.getUuid(), date, totalSold, netProfit, cogs: totalCOGS});
  const profitPerEnv = netProfit / 3;
  updateEnvelopeBalance("ENV1", profitPerEnv);
  updateEnvelopeBalance("ENV2", profitPerEnv);
  updateEnvelopeBalance("ENV3", profitPerEnv);
  updateEnvelopeBalance("ENV4", totalCOGS);
  return { totalSold, netProfit, totalCOGS };
}

function updateEnvelopeBalance(id, amount) {
  const sheet = getSheet("Envelopes");
  const data = sheet.getDataRange().getValues();
  for(let i=1; i<data.length; i++) { if(data[i][0] === id) { const current = Number(data[i][2]); sheet.getRange(i+1, 3).setValue(current + amount); break; } }
}

function withdrawEnvelope(w) {
  const sheet = getSheet("Envelopes");
  const histSheet = getSheet("EnvelopeHistory");
  const data = sheet.getDataRange().getValues();
  for(let i=1; i<data.length; i++) { if(data[i][0] === w.envelopeId) { sheet.getRange(i+1, 3).setValue(0); sheet.getRange(i+1, 5).setValue(new Date().toISOString()); break; } }
  histSheet.appendRow([w.id, w.envelopeId, w.envelopeName, w.amount, w.startDate, w.endDate, w.durationText, w.notes]);
  return {success: true};
}

function saveClosing(c) { getSheet("Closings").appendRow([c.id, c.date, c.totalSold, c.netProfit, c.cogs]); return {success: true}; }
function saveOutput(o) { getSheet("Outputs").appendRow([o.id, o.productId, o.productName, o.quantity, o.salePrice, o.totalSale, o.date, o.shift]); return {success: true}; }

function getDashboardData() {
  const envs = getEnvelopes();
  const products = getProducts();
  const closings = getSheetData("Closings");
  let totalProfit = 0;
  let totalCapital = 0;
  envs.forEach(e => { if(e.id === "ENV4") totalCapital = e.balance; else totalProfit += e.balance; });
  return {
    envelopes: envs,
    profitVsCapital: [ {name: 'Utilidad Acum.', value: totalProfit}, {name: 'Capital Stock', value: totalCapital} ],
    topVolume: products.sort((a,b) => b.totalEarned - a.totalEarned).slice(0, 5).map(p => ({name: p.name, volume: p.totalEarned / (p.salePrice || 1)})),
    topProfit: products.sort((a,b) => b.totalEarned - a.totalEarned).slice(0, 5).map(p => ({name: p.name, profit: p.totalEarned}))
  };
}

function setupSheet() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheets = {
    "Products": ["id", "code", "name", "grams", "flavor", "costPrice", "salePrice", "stock", "category", "provider", "totalInvested", "totalEarned"],
    "Envelopes": ["id", "name", "balance", "description", "lastResetDate"],
    "EnvelopeHistory": ["id", "envelopeId", "envelopeName", "amount", "startDate", "endDate", "durationText", "notes"],
    "PurchaseNotes": ["id", "date", "provider", "totalAmount", "status", "detailsJson"],
    "Inputs": ["id", "productId", "productName", "quantity", "unitCost", "totalCost", "date", "provider"],
    "Outputs": ["id", "productId", "productName", "quantity", "salePrice", "totalSale", "date", "shift"],
    "Closings": ["id", "date", "totalSold", "netProfit", "cogs"],
    "PriceHistory": ["id", "productId", "productName", "field", "oldValue", "newValue", "date"]
  };
  for (let name in sheets) {
    if (!ss.getSheetByName(name)) {
      let s = ss.insertSheet(name);
      s.appendRow(sheets[name]);
      if (name === "Envelopes") {
        const now = new Date().toISOString();
        s.appendRow(["ENV1", "Sobre 1 - Operativo", 0, "1/3 de Utilidad para gastos", now]);
        s.appendRow(["ENV2", "Sobre 2 - Ahorro", 0, "1/3 de Utilidad para fondo", now]);
        s.appendRow(["ENV3", "Sobre 3 - Ganancia", 0, "1/3 de Utilidad personal", now]);
        s.appendRow(["ENV4", "Sobre 4 - Capital", 0, "Fondo de Resurtido (100% Costo)", now]);
      }
    }
  }
  return {success: true};
}

import { Product, InputTransaction, OutputTransaction, DailyClosing, PriceHistory, PurchaseNote, Envelope, EnvelopeWithdrawal } from "../types";

// URL actualizada proporcionada por el usuario
const APPS_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbwwXsD4dL-jN23_zmOzjtLTYacDy9yk45WsfGMGcKVrBRBQacsjztbDizwWxDvud55dbQ/exec";

const callApi = async (action: string, data: any = null) => {
  if (!APPS_SCRIPT_URL) {
    console.error("URL de Google Apps Script no configurada.");
    return null;
  }

  try {
    const response = await fetch(APPS_SCRIPT_URL, {
      method: 'POST',
      mode: 'cors',
      headers: { 'Content-Type': 'text/plain' },
      body: JSON.stringify({ action, data })
    });

    if (!response.ok) {
      throw new Error(`HTTP error! status: ${response.status}`);
    }

    return await response.json();
  } catch (error) {
    console.error(`Error en API (${action}):`, error);
    return null;
  }
};

export const dataService = {
  _products: [] as Product[],
  _envelopes: [] as Envelope[],
  _envelopeHistory: [] as EnvelopeWithdrawal[],
  _purchaseNotes: [] as PurchaseNote[],
  _inputs: [] as InputTransaction[],
  _outputs: [] as OutputTransaction[],
  _closings: [] as DailyClosing[],
  _priceHistory: [] as PriceHistory[],

  async fetchAll() {
    try {
      const [products, envelopes, envHistory, purchaseNotes, inputs, outputs, closings, priceHistory] = await Promise.all([
        callApi('getProducts'),
        callApi('getEnvelopes'),
        callApi('getEnvelopeHistory'),
        callApi('getPurchaseNotes'),
        callApi('getInputs'),
        callApi('getOutputs'),
        callApi('getClosings'),
        callApi('getPriceHistory'),
      ]);

      this._products = Array.isArray(products) ? products : [];
      this._envelopes = Array.isArray(envelopes) ? envelopes : [];
      this._envelopeHistory = Array.isArray(envHistory) ? envHistory : [];
      this._purchaseNotes = Array.isArray(purchaseNotes) ? purchaseNotes : [];
      this._inputs = Array.isArray(inputs) ? inputs : [];
      this._outputs = Array.isArray(outputs) ? outputs : [];
      this._closings = Array.isArray(closings) ? closings : [];
      this._priceHistory = Array.isArray(priceHistory) ? priceHistory : [];
    } catch (e) { 
      console.error("Error cargando datos:", e); 
    }
  },

  getProducts() { return this._products; },
  getEnvelopes() { return this._envelopes; },
  getEnvelopeHistory() { return this._envelopeHistory; },
  getPurchaseNotes() { return this._purchaseNotes; },
  getInputs() { return this._inputs; },
  getOutputs() { return this._outputs; },
  getClosings() { return this._closings; },
  getPriceHistory() { return this._priceHistory; },

  async getDashboardData() { 
    return await callApi('getDashboardData'); 
  },

  async withdrawEnvelope(withdrawal: EnvelopeWithdrawal) {
    await callApi('withdrawEnvelope', withdrawal);
    await this.fetchAll();
  },

  async processPhysicalCount(counts: any[], shift: string) {
    const res = await callApi('processPhysicalCount', { counts, shift });
    await this.fetchAll();
    return res;
  },

  async saveRestockNote(note: PurchaseNote) {
    await callApi('saveRestockNote', note);
    await this.fetchAll();
  },

  async updateNoteStatus(id: string, status: string) {
    await callApi('updateNoteStatus', { id, status });
    await this.fetchAll();
  },

  async saveProduct(p: Product) { 
    await callApi('saveProduct', p); 
    await this.fetchAll(); 
  },

  async deleteProduct(id: string) { 
    await callApi('deleteProduct', id); 
    await this.fetchAll(); 
  },

  async deleteRecord(sheet: string, id: string) {
    const res = await callApi('deleteRecord', { sheet, id });
    await this.fetchAll();
    return res;
  },

  async updateRecord(sheet: string, id: string, data: any) {
    const res = await callApi('updateRecord', { sheet, id, data });
    await this.fetchAll();
    return res;
  },

  async saveOutput(o: OutputTransaction) {
    await callApi('saveOutput', o);
    await this.fetchAll();
  },

  async saveClosing(c: DailyClosing) {
    await callApi('saveClosing', c);
    await this.fetchAll();
  },

  async setup() { 
    return await callApi('setup'); 
  },

  async sync() { 
    await this.fetchAll(); 
    return { success: true }; 
  }
};

