                    <td className="px-4 py-4 text-center text-slate-400 font-bold text-xs">
                      ${row.vendido.toLocaleString()}
                    </td>
                    <td className="px-4 py-4 text-center font-black text-blue-600 text-sm">
                      ${row.ganadoTotal.toLocaleString()}
