                />
              </div>

              <button 
                type="submit" 
                disabled={isProcessing}
                className="w-full bg-red-600 hover:bg-red-700 text-white font-black py-5 rounded-2xl transition-all shadow-xl shadow-red-900/20 flex items-center justify-center space-x-3 text-lg"
