 * Soporte para persistencia robusta de capital y gestión de historial.
 */

function doPost(e) {
  const params = JSON.parse(e.postData.contents);
  const action = params.action;
  const data = params.data;

  let result;
  try {
    switch(action) {
      case 'getProducts': result = getProducts(); break;
      case 'getEnvelopes': result = getEnvelopes(); break;
      case 'getDashboardData': result = getDashboardData(); break;
      case 'saveProduct': result = saveProduct(data); break;
      case 'saveEnvelope': result = saveEnvelope(data); break;
      case 'deleteProduct': result = deleteProduct(data); break;
      case 'withdrawEnvelope': result = withdrawEnvelope(data); break;
      case 'deleteWithdrawal': result = deleteWithdrawal(data); break;
      case 'updateWithdrawal': result = updateWithdrawal(data); break;
      case 'getEnvelopeHistory': result = getSheetData("EnvelopeHistory"); break;
      case 'getPurchaseNotes': result = getSheetData("PurchaseNotes"); break;
      case 'getInputs': result = getSheetData("Inputs"); break;
      case 'getOutputs': result = getSheetData("Outputs"); break;
      case 'getClosings': result = getSheetData("Closings"); break;
      case 'getPriceHistory': result = getSheetData("PriceHistory"); break;
      case 'processPhysicalCount': result = processPhysicalCount(data.counts, data.shift); break;
      case 'setup': result = setupSheet(); break;
      default: throw new Error("Acción no reconocida: " + action);
    }
    return ContentService.createTextOutput(JSON.stringify(result)).setMimeType(ContentService.MimeType.JSON);
  } catch (error) {
    return ContentService.createTextOutput(JSON.stringify({error: error.toString()})).setMimeType(ContentService.MimeType.JSON);
  }
}

function saveEnvelope(env) {
  const sheet = getSheet("Envelopes");
  const data = sheet.getDataRange().getValues();
  let foundIndex = -1;

  // Búsqueda robusta (trim y string)
  const targetId = env.id.toString().trim();
  for(let i=1; i<data.length; i++) {
    if(data[i][0].toString().trim() === targetId) {
      foundIndex = i + 1;
      break;
    }
  }

  const row = [
    env.id, 
    env.name, 
    Number(env.balance), 
    env.description || "", 
    env.lastResetDate || new Date().toISOString()
  ];

  if(foundIndex > -1) {
    sheet.getRange(foundIndex, 1, 1, row.length).setValues([row]);
  } else {
    sheet.appendRow(row);
  }
  return {success: true};
}

function deleteWithdrawal(withdrawalId) {
  const histSheet = getSheet("EnvelopeHistory");
  const histData = histSheet.getDataRange().getValues();
  let rowIndex = -1;
  let wData = null;

  for(let i=1; i<histData.length; i++) {
    if(histData[i][0].toString().trim() === withdrawalId.toString().trim()) {
      wData = { envId: histData[i][1], amount: Number(histData[i][3]) };
      rowIndex = i + 1;
      break;
    }
  }

  if (rowIndex > -1) {
    // Revertir el dinero al sobre
    updateEnvelopeBalance(wData.envId, wData.amount);
    histSheet.deleteRow(rowIndex);
    return {success: true};
  }
  throw new Error("Retiro no encontrado");
}

function updateWithdrawal(newW) {
  const histSheet = getSheet("EnvelopeHistory");
  const histData = histSheet.getDataRange().getValues();
  let rowIndex = -1;
  let oldAmount = 0;

  for(let i=1; i<histData.length; i++) {
    if(histData[i][0].toString().trim() === newW.id.toString().trim()) {
      oldAmount = Number(histData[i][3]);
      rowIndex = i + 1;
      break;
    }
  }

  if (rowIndex > -1) {
    const diff = Number(newW.amount) - oldAmount;
    // Ajustar el sobre: Si el nuevo retiro es mayor, el sobre baja.
    updateEnvelopeBalance(newW.envelopeId, -diff);

    const row = [
      newW.id, newW.envelopeId, newW.envelopeName, Number(newW.amount), 
      newW.startDate, newW.endDate, newW.durationText, newW.notes || ""
    ];
    histSheet.getRange(rowIndex, 1, 1, row.length).setValues([row]);
    return {success: true};
  }
  throw new Error("Retiro no encontrado para actualizar");
}

function updateEnvelopeBalance(id, amount) {
  const sheet = getSheet("Envelopes");
  const data = sheet.getDataRange().getValues();
  const targetId = id.toString().trim();
  for(let i=1; i<data.length; i++) {
    if(data[i][0].toString().trim() === targetId) {
      const current = Number(data[i][2]);
      sheet.getRange(i+1, 3).setValue(current + amount);
      break;
    }
  }
}

// Las demás funciones de utilidad (getSheet, getSheetData, getProducts, saveProduct, etc.) 
// se asumen presentes según la versión v3.7 del usuario.
function getSheet(name) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  let sheet = ss.getSheetByName(name);
  if (!sheet) { setupSheet(); sheet = ss.getSheetByName(name); }
  return sheet;
}

function getSheetData(name) {
  const sheet = getSheet(name);
  const values = sheet.getDataRange().getValues();
  if (values.length <= 1) return [];
  const headers = values[0];
  return values.slice(1).map(row => {
    let obj = {};
    headers.forEach((h, i) => obj[h] = row[i]);
    return obj;
  });
}

function getProducts() { return getSheetData("Products"); }

function saveProduct(p) {
  const sheet = getSheet("Products");
  const data = sheet.getDataRange().getValues();
  let foundIndex = -1;
  for(let i=1; i<data.length; i++) { if(data[i][0] === p.id) { foundIndex = i + 1; break; } }
  const row = [p.id, p.code || "", p.name, p.grams || "", p.flavor || "", p.costPrice || 0, p.salePrice || 0, p.stock || 0, p.category || "", p.provider || "", p.totalInvested || 0, p.totalEarned || 0, p.totalInputs || 0, p.totalOutputs || 0];
  if(foundIndex > -1) { sheet.getRange(foundIndex, 1, 1, row.length).setValues([row]); } else { sheet.appendRow(row); }
  return {success: true};
}

function deleteProduct(id) {
  const sheet = getSheet("Products");
  const data = sheet.getDataRange().getValues();
  for(let i=1; i<data.length; i++) { if(data[i][0] === id) { sheet.deleteRow(i + 1); break; } }
  return {success: true};
}

function withdrawEnvelope(w) {
  const sheet = getSheet("Envelopes");
  const histSheet = getSheet("EnvelopeHistory");
  const data = sheet.getDataRange().getValues();
  for(let i=1; i<data.length; i++) { 
    if(data[i][0].toString().trim() === w.envelopeId.toString().trim()) { 
      sheet.getRange(i+1, 3).setValue(0); 
      sheet.getRange(i+1, 5).setValue(new Date().toISOString());
      break; 
    } 
  }
  histSheet.appendRow([w.id, w.envelopeId, w.envelopeName, Number(w.amount), w.startDate, w.endDate, w.durationText, w.notes || ""]);
  return {success: true};
}

function processPhysicalCount(counts, shift) {
  const productSheet = getSheet("Products");
  const outputSheet = getSheet("Outputs");
  const productData = productSheet.getDataRange().getValues();
  const headers = productData[0];
  const outputCol = headers.indexOf("totalOutputs") + 1;
  const date = new Date().toISOString();
  let totalSold = 0; let totalCOGS = 0;
  counts.forEach(count => {
    for(let i=1; i<productData.length; i++) {
      if(productData[i][0] === count.productId) {
        const systemStock = Number(productData[i][7]);
        const diff = systemStock - count.physicalCount;
        if (diff > 0) {
          const salePrice = Number(productData[i][6]); const costPrice = Number(productData[i][5]);
          const totalSale = diff * salePrice; const totalCost = diff * costPrice;
          totalSold += totalSale; totalCOGS += totalCost;
          outputSheet.appendRow([Utilities.getUuid(), count.productId, productData[i][2], diff, salePrice, totalSale, date, shift]);
          productSheet.getRange(i+1, 8).setValue(count.physicalCount);
          let currentEarned = Number(productData[i][11]); productSheet.getRange(i+1, 12).setValue(currentEarned + totalSale);
          if(outputCol > 0) { let currentOutputs = Number(productData[i][outputCol - 1] || 0); productSheet.getRange(i+1, outputCol).setValue(currentOutputs + diff); }
        }
      }
    }
  });
  const netProfit = totalSold - totalCOGS;
  const sheetClosing = getSheet("Closings"); sheetClosing.appendRow([Utilities.getUuid(), date, totalSold, netProfit, totalCOGS]);
  const profitPerEnv = netProfit / 3;
  updateEnvelopeBalance("ENV1", profitPerEnv); updateEnvelopeBalance("ENV2", profitPerEnv); updateEnvelopeBalance("ENV3", profitPerEnv); updateEnvelopeBalance("ENV4", totalCOGS);
  return { totalSold, netProfit, totalCOGS };
}

function setupSheet() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheets = {
    "Products": ["id", "code", "name", "grams", "flavor", "costPrice", "salePrice", "stock", "category", "provider", "totalInvested", "totalEarned", "totalInputs", "totalOutputs"],
    "Envelopes": ["id", "name", "balance", "description", "lastResetDate"],
    "EnvelopeHistory": ["id", "envelopeId", "envelopeName", "amount", "startDate", "endDate", "durationText", "notes"],
    "PurchaseNotes": ["id", "date", "provider", "totalAmount", "status", "detailsJson"],
    "Inputs": ["id", "productId", "productName", "quantity", "unitCost", "totalCost", "date", "provider"],
    "Outputs": ["id", "productId", "productName", "quantity", "salePrice", "totalSale", "date", "shift"],
    "Closings": ["id", "date", "totalSold", "netProfit", "cogs"],
    "PriceHistory": ["id", "productId", "productName", "field", "oldValue", "newValue", "date"]
  };
  for (let name in sheets) {
    if (!ss.getSheetByName(name)) {
      let s = ss.insertSheet(name); s.appendRow(sheets[name]);
      if (name === "Envelopes") {
        const now = new Date().toISOString();
        s.appendRow(["ENV1", "Sobre 1 - Operativo", 0, "1/3 de Utilidad para gastos", now]);
        s.appendRow(["ENV2", "Sobre 2 - Ahorro", 0, "1/3 de Utilidad para fondo", now]);
        s.appendRow(["ENV3", "Sobre 3 - Ganancia", 0, "1/3 de Utilidad personal", now]);
        s.appendRow(["ENV4", "Sobre 4 - Capital", 0, "Fondo de Resurtido (100% Costo)", now]);
      }
    }
  }
  return {success: true};
}

import { Product, InputTransaction, OutputTransaction, DailyClosing, PriceHistory, PurchaseNote, Envelope, EnvelopeWithdrawal } from "../types";

const APPS_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbzTUE7hJMazOJQXOeF0OoOHdauxZi-l7rSJtJHN9B9fL9upxhXnZsw4Obq1YFv6Dn1pLw/exec";

const callApi = async (action: string, data: any = null) => {
  if (!APPS_SCRIPT_URL) return null;
  try {
    const response = await fetch(APPS_SCRIPT_URL, {
      method: 'POST',
      mode: 'cors',
      headers: { 'Content-Type': 'text/plain' },
      body: JSON.stringify({ action, data })
    });
    return await response.json();
  } catch (error) {
    console.error(`Error en API (${action}):`, error);
    return null;
  }
};

export const dataService = {
  _products: [] as Product[],
  _envelopes: [] as Envelope[],
  _envelopeHistory: [] as EnvelopeWithdrawal[],
  _purchaseNotes: [] as PurchaseNote[],
  _inputs: [] as InputTransaction[],
  _outputs: [] as OutputTransaction[],
  _closings: [] as DailyClosing[],
  _priceHistory: [] as PriceHistory[],

  async fetchAll() {
    try {
      const [products, envelopes, envHistory, purchaseNotes, inputs, outputs, closings, priceHistory] = await Promise.all([
        callApi('getProducts'),
        callApi('getEnvelopes'),
        callApi('getEnvelopeHistory'),
        callApi('getPurchaseNotes'),
        callApi('getInputs'),
        callApi('getOutputs'),
        callApi('getClosings'),
        callApi('getPriceHistory'),
      ]);
      this._products = products || [];
      this._envelopes = envelopes || [];
      this._envelopeHistory = envHistory || [];
      this._purchaseNotes = purchaseNotes || [];
      this._inputs = inputs || [];
      this._outputs = outputs || [];
      this._closings = closings || [];
      this._priceHistory = priceHistory || [];
    } catch (e) { console.error(e); }
  },

  getProducts() { return this._products; },
  getEnvelopes() { return this._envelopes; },
  getEnvelopeHistory() { return this._envelopeHistory; },
  getPurchaseNotes() { return this._purchaseNotes; },
  getInputs() { return this._inputs; },
  getOutputs() { return this._outputs; },
  getClosings() { return this._closings; },
  getPriceHistory() { return this._priceHistory; },

  async saveEnvelope(e: Envelope) {
    await callApi('saveEnvelope', e);
    await this.fetchAll();
  },

  async withdrawEnvelope(withdrawal: EnvelopeWithdrawal) {
    await callApi('withdrawEnvelope', withdrawal);
    await this.fetchAll();
  },

  async deleteWithdrawal(id: string) {
    await callApi('deleteWithdrawal', id);
    await this.fetchAll();
  },

  async updateWithdrawal(withdrawal: EnvelopeWithdrawal) {
    await callApi('updateWithdrawal', withdrawal);
    await this.fetchAll();
  },

  async saveProduct(p: Product) { await callApi('saveProduct', p); await this.fetchAll(); },
  async deleteProduct(id: string) { await callApi('deleteProduct', id); await this.fetchAll(); },
  async updateNoteStatus(id: string, status: string) { await callApi('updateNoteStatus', { id, status }); await this.fetchAll(); },
  async processPhysicalCount(counts: any[], shift: string) { const res = await callApi('processPhysicalCount', { counts, shift }); await this.fetchAll(); return res; },
  async sync() { await this.fetchAll(); return { success: true }; }
};

