/**
 * tiendita - Backend API v4.0
 * Búsqueda robusta de IDs y gestión completa de eliminación.
 */

function doPost(e) {
  const params = JSON.parse(e.postData.contents);
  const action = params.action;
  const data = params.data;

  let result;
  try {
    switch(action) {
      case 'getProducts': result = getProducts(); break;
      case 'getEnvelopes': result = getEnvelopes(); break;
      case 'getDashboardData': result = getDashboardData(); break;
      case 'saveProduct': result = saveProduct(data); break;
      case 'saveEnvelope': result = saveEnvelope(data); break;
      case 'deleteProduct': result = deleteProduct(data); break;
      case 'withdrawEnvelope': result = withdrawEnvelope(data); break;
      case 'deleteWithdrawal': result = deleteWithdrawal(data); break;
      case 'updateWithdrawal': result = updateWithdrawal(data); break;
      case 'deleteInput': result = deleteInput(data); break;
      case 'deletePurchaseNote': result = deletePurchaseNote(data); break;
      case 'getEnvelopeHistory': result = getSheetData("EnvelopeHistory"); break;
      case 'getPurchaseNotes': result = getSheetData("PurchaseNotes"); break;
      case 'getInputs': result = getSheetData("Inputs"); break;
      case 'getOutputs': result = getSheetData("Outputs"); break;
      case 'getClosings': result = getSheetData("Closings"); break;
      case 'getPriceHistory': result = getSheetData("PriceHistory"); break;
      case 'updateNoteStatus': result = updateNoteStatus(data.id, data.status); break;
      case 'processPhysicalCount': result = processPhysicalCount(data.counts, data.shift); break;
      case 'setup': result = setupSheet(); break;
      default: throw new Error("Acción no reconocida: " + action);
    }
    return ContentService.createTextOutput(JSON.stringify(result)).setMimeType(ContentService.MimeType.JSON);
  } catch (error) {
    return ContentService.createTextOutput(JSON.stringify({error: error.toString()})).setMimeType(ContentService.MimeType.JSON);
  }
}

// --- FUNCIONES DE PERSISTENCIA ROBUSTA ---

function saveEnvelope(env) {
  const sheet = getSheet("Envelopes");
  const data = sheet.getDataRange().getValues();
  let foundIndex = -1;
  const targetId = env.id.toString().trim().toUpperCase();
  for(let i=1; i<data.length; i++) {
    if(data[i][0].toString().trim().toUpperCase() === targetId) {
      foundIndex = i + 1; break;
    }
  }
  const row = [env.id, env.name, Number(env.balance), env.description || "", env.lastResetDate || new Date().toISOString()];
  if(foundIndex > -1) { sheet.getRange(foundIndex, 1, 1, row.length).setValues([row]); } 
  else { sheet.appendRow(row); }
  return {success: true};
}

function saveProduct(p) {
  const sheet = getSheet("Products");
  const data = sheet.getDataRange().getValues();
  let foundIndex = -1;
  const targetId = p.id.toString().trim();
  for(let i=1; i<data.length; i++) {
    if(data[i][0].toString().trim() === targetId) {
      foundIndex = i + 1; break;
    }
  }
  const row = [p.id, p.code || "", p.name, p.grams || "", p.flavor || "", Number(p.costPrice) || 0, Number(p.salePrice) || 0, Number(p.stock) || 0, p.category || "", p.provider || "", Number(p.totalInvested) || 0, Number(p.totalEarned) || 0, Number(p.totalInputs) || 0, Number(p.totalOutputs) || 0];
  if(foundIndex > -1) { sheet.getRange(foundIndex, 1, 1, row.length).setValues([row]); } 
  else { sheet.appendRow(row); }
  return {success: true};
}

// --- FUNCIONES DE ELIMINACIÓN ---

function deleteProduct(id) {
  const sheet = getSheet("Products");
  const data = sheet.getDataRange().getValues();
  const targetId = id.toString().trim();
  for(let i=1; i<data.length; i++) {
    if(data[i][0].toString().trim() === targetId) {
      sheet.deleteRow(i + 1); break;
    }
  }
  return {success: true};
}

function deleteInput(id) {
  const sheet = getSheet("Inputs");
  const data = sheet.getDataRange().getValues();
  const targetId = id.toString().trim();
  for(let i=1; i<data.length; i++) {
    if(data[i][0].toString().trim() === targetId) {
      const prodId = data[i][1];
      const qty = Number(data[i][3]);
      // Revertir stock del producto
      adjustProductStock(prodId, -qty);
      sheet.deleteRow(i + 1);
      break;
    }
  }
  return {success: true};
}

function deletePurchaseNote(id) {
  const sheet = getSheet("PurchaseNotes");
  const data = sheet.getDataRange().getValues();
  const targetId = id.toString().trim();
  for(let i=1; i<data.length; i++) {
    if(data[i][0].toString().trim() === targetId) {
      sheet.deleteRow(i + 1); break;
    }
  }
  return {success: true};
}

function deleteWithdrawal(withdrawalId) {
  const histSheet = getSheet("EnvelopeHistory");
  const histData = histSheet.getDataRange().getValues();
  const targetId = withdrawalId.toString().trim();
  for(let i=1; i<histData.length; i++) {
    if(histData[i][0].toString().trim() === targetId) {
      updateEnvelopeBalance(histData[i][1], Number(histData[i][3]));
      histSheet.deleteRow(i + 1);
      break;
    }
  }
  return {success: true};
}

// --- UTILIDADES ---

function adjustProductStock(id, diff) {
  const sheet = getSheet("Products");
  const data = sheet.getDataRange().getValues();
  const targetId = id.toString().trim();
  for(let i=1; i<data.length; i++) {
    if(data[i][0].toString().trim() === targetId) {
      const current = Number(data[i][7]);
      sheet.getRange(i+1, 8).setValue(current + diff);
      break;
    }
  }
}

function updateEnvelopeBalance(id, amount) {
  const sheet = getSheet("Envelopes");
  const data = sheet.getDataRange().getValues();
  const targetId = id.toString().trim().toUpperCase();
  for(let i=1; i<data.length; i++) {
    if(data[i][0].toString().trim().toUpperCase() === targetId) {
      const current = Number(data[i][2]);
      sheet.getRange(i+1, 3).setValue(current + amount);
      break;
    }
  }
}

function getSheet(name) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  let sheet = ss.getSheetByName(name);
  if (!sheet) { setupSheet(); sheet = ss.getSheetByName(name); }
  return sheet;
}

function getSheetData(name) {
  const sheet = getSheet(name);
  const values = sheet.getDataRange().getValues();
  if (values.length <= 1) return [];
  const headers = values[0];
  return values.slice(1).map(row => {
    let obj = {};
    headers.forEach((h, i) => obj[h] = row[i]);
    return obj;
  });
}

import { Product, InputTransaction, OutputTransaction, DailyClosing, PriceHistory, PurchaseNote, Envelope, EnvelopeWithdrawal } from "../types";

const APPS_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbzTUE7hJMazOJQXOeF0OoOHdauxZi-l7rSJtJHN9B9fL9upxhXnZsw4Obq1YFv6Dn1pLw/exec";

const callApi = async (action: string, data: any = null) => {
  if (!APPS_SCRIPT_URL) return null;
  try {
    const response = await fetch(APPS_SCRIPT_URL, {
      method: 'POST',
      mode: 'cors',
      headers: { 'Content-Type': 'text/plain' },
      body: JSON.stringify({ action, data })
    });
    return await response.json();
  } catch (error) {
    console.error(`Error en API (${action}):`, error);
    return null;
  }
};

export const dataService = {
  _products: [] as Product[],
  _envelopes: [] as Envelope[],
  _envelopeHistory: [] as EnvelopeWithdrawal[],
  _purchaseNotes: [] as PurchaseNote[],
  _inputs: [] as InputTransaction[],
  _outputs: [] as OutputTransaction[],
  _closings: [] as DailyClosing[],
  _priceHistory: [] as PriceHistory[],

  async fetchAll() {
    try {
      const [products, envelopes, envHistory, purchaseNotes, inputs, outputs, closings, priceHistory] = await Promise.all([
        callApi('getProducts'),
        callApi('getEnvelopes'),
        callApi('getEnvelopeHistory'),
        callApi('getPurchaseNotes'),
        callApi('getInputs'),
        callApi('getOutputs'),
        callApi('getClosings'),
        callApi('getPriceHistory'),
      ]);
      this._products = products || [];
      this._envelopes = envelopes || [];
      this._envelopeHistory = envHistory || [];
      this._purchaseNotes = purchaseNotes || [];
      this._inputs = inputs || [];
      this._outputs = outputs || [];
      this._closings = closings || [];
      this._priceHistory = priceHistory || [];
    } catch (e) { console.error(e); }
  },

  getProducts() { return this._products; },
  getEnvelopes() { return this._envelopes; },
  getEnvelopeHistory() { return this._envelopeHistory; },
  getPurchaseNotes() { return this._purchaseNotes; },
  getInputs() { return this._inputs; },
  getOutputs() { return this._outputs; },
  getClosings() { return this._closings; },
  getPriceHistory() { return this._priceHistory; },

  async saveEnvelope(e: Envelope) { await callApi('saveEnvelope', e); await this.fetchAll(); },
  async withdrawEnvelope(withdrawal: EnvelopeWithdrawal) { await callApi('withdrawEnvelope', withdrawal); await this.fetchAll(); },
  async deleteWithdrawal(id: string) { await callApi('deleteWithdrawal', id); await this.fetchAll(); },
  async updateWithdrawal(withdrawal: EnvelopeWithdrawal) { await callApi('updateWithdrawal', withdrawal); await this.fetchAll(); },

  async deleteInput(id: string) { await callApi('deleteInput', id); await this.fetchAll(); },
  async deletePurchaseNote(id: string) { await callApi('deletePurchaseNote', id); await this.fetchAll(); },

  async saveProduct(p: Product) { await callApi('saveProduct', p); await this.fetchAll(); },
  async deleteProduct(id: string) { await callApi('deleteProduct', id); await this.fetchAll(); },
  async updateNoteStatus(id: string, status: string) { await callApi('updateNoteStatus', { id, status }); await this.fetchAll(); },
  async processPhysicalCount(counts: any[], shift: string) { const res = await callApi('processPhysicalCount', { counts, shift }); await this.fetchAll(); return res; },
  async sync() { await this.fetchAll(); return { success: true }; }
};

import React, { useState, useEffect, useMemo } from 'react';
import { Search, Save, AlertCircle, RefreshCw, Check, Trash2 } from 'lucide-react';
import { dataService } from '../services/dataService';
import { Product } from '../types';

const ProductsTable: React.FC = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [products, setProducts] = useState<Product[]>([]);
  const [localChanges, setLocalChanges] = useState<{ [key: string]: { costPrice: number, salePrice: number } }>({});
  const [isSaving, setIsSaving] = useState(false);
  const [saveStatus, setSaveStatus] = useState<'idle' | 'success'>('idle');

  const refreshLocalProducts = () => {
    setProducts([...dataService.getProducts()]);
  };

  useEffect(() => {
    refreshLocalProducts();
  }, []);

  const filteredProducts = useMemo(() => {
    return products.filter(p => 
      p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
      p.code.includes(searchTerm)
    );
  }, [products, searchTerm]);

  const handlePriceChange = (id: string, field: 'costPrice' | 'salePrice', value: string) => {
    const numValue = parseFloat(value) || 0;
    const currentProduct = products.find(p => p.id === id);
    if (!currentProduct) return;

    setLocalChanges(prev => ({
      ...prev,
      [id]: {
        ...(prev[id] || { costPrice: currentProduct.costPrice, salePrice: currentProduct.salePrice }),
        [field]: numValue
      }
    }));
  };

  const calculateRow = (product: Product) => {
    const changes = localChanges[product.id];
    const pc = changes ? changes.costPrice : product.costPrice;
    const pv = changes ? changes.salePrice : product.salePrice;
    const stock = product.stock || 0;
    const entradas = product.totalInputs || 0;
    const salidas = product.totalOutputs || 0;

    const gananciaUnitaria = pv - pc;
    const rentabilidad = pc > 0 ? (gananciaUnitaria / pc) * 100 : 0;
    const invertido = pc * stock;
    const vendido = pv * salidas;
    const ganadoTotal = gananciaUnitaria * salidas;
    const porcGanancia = invertido > 0 ? (ganadoTotal / invertido) * 100 : 0;

    return { pc, pv, gananciaUnitaria, rentabilidad, invertido, vendido, ganadoTotal, porcGanancia, entradas, salidas, stock };
  };

  const saveChanges = async (product: Product) => {
    const changes = localChanges[product.id];
    if (!changes) return;

    setIsSaving(true);
    try {
      const updatedProduct = {
        ...product,
        costPrice: changes.costPrice,
        salePrice: changes.salePrice
      };
      await dataService.saveProduct(updatedProduct);

      const newLocalChanges = { ...localChanges };
      delete newLocalChanges[product.id];
      setLocalChanges(newLocalChanges);

      setSaveStatus('success');
      refreshLocalProducts();
      setTimeout(() => setSaveStatus('idle'), 2000);
    } catch (e) {
      alert("Error al guardar cambios");
