function saveProduct(p) {
  const headers = ["id", "code", "name", "grams", "flavor", "costPrice", "salePrice", "stock", "category", "provider", "totalInvested", "totalEarned", "totalInputs", "totalOutputs"];
  return saveToSheet("Products", headers, p, "id");
}

function saveEnvelope(env) {
  const headers = ["id", "name", "balance", "description", "lastResetDate"];
  return saveToSheet("Envelopes", headers, env, "id");
}

function savePurchaseNote(note) {
  const headers = ["id", "date", "provider", "totalAmount", "status", "detailsJson"];
  const res = saveToSheet("PurchaseNotes", headers, note, "id");

  if (note.status === 'Paid') {
    // Restar del Sobre 4 (Capital)
    const total = Number(note.totalAmount);
    updateEnvelopeBalance("ENV4", -total);
  }

  // Actualizar Stocks y Entradas
  const details = JSON.parse(note.detailsJson);
  const prodSheet = getSheet("Products");
  const prodData = prodSheet.getDataRange().getValues();
  const prodHeaders = prodData[0];

  details.forEach(item => {
    let foundRow = -1;
    for(let i=1; i<prodData.length; i++) {
      if(prodData[i][0].toString() === item.productId.toString()) {
        foundRow = i + 1;
        break;
      }
    }

    if(foundRow > -1) {
      const stockIdx = prodHeaders.indexOf("stock");
      const inputsIdx = prodHeaders.indexOf("totalInputs");
      const investedIdx = prodHeaders.indexOf("totalInvested");

      const currentStock = Number(prodData[foundRow-1][stockIdx]);
      const currentInputs = Number(prodData[foundRow-1][inputsIdx]);
      const currentInvested = Number(prodData[foundRow-1][investedIdx]);

      prodSheet.getRange(foundRow, stockIdx + 1).setValue(currentStock + Number(item.quantity));
      prodSheet.getRange(foundRow, inputsIdx + 1).setValue(currentInputs + Number(item.quantity));
      prodSheet.getRange(foundRow, investedIdx + 1).setValue(currentInvested + Number(item.totalCost));

      // Registrar en Inputs Log
      getSheet("Inputs").appendRow([
        "INP-" + Utilities.getUuid(),
        item.productId,
        item.productName,
        item.quantity,
        item.unitCost,
        item.totalCost,
        note.date,
        note.provider,
        note.id,
        note.status
      ]);
    }
  });

  return res;
}

function processPhysicalCount(counts, shift) {
  const prodSheet = getSheet("Products");
  const prodData = prodSheet.getDataRange().getValues();
  const prodHeaders = prodData[0];

  let totalSold = 0;
  let totalCOGS = 0;
  let netProfit = 0;

  counts.forEach(c => {
    let foundRow = -1;
    for(let i=1; i<prodData.length; i++) {
      if(prodData[i][0].toString() === c.productId.toString()) {
        foundRow = i+1;
        break;
      }
    }

    if(foundRow > -1) {
      const stockIdx = prodHeaders.indexOf("stock");
      const saleIdx = prodHeaders.indexOf("salePrice");
      const costIdx = prodHeaders.indexOf("costPrice");
      const earnedIdx = prodHeaders.indexOf("totalEarned");
      const outIdx = prodHeaders.indexOf("totalOutputs");

      const sysStock = Number(prodData[foundRow-1][stockIdx]);
      const physStock = Number(c.physicalCount);
      const diff = sysStock - physStock;

      if(diff > 0) {
        const cost = Number(prodData[foundRow-1][costIdx]);
        const price = Number(prodData[foundRow-1][saleIdx]);
        const earned = Number(prodData[foundRow-1][earnedIdx]);
        const outs = Number(prodData[foundRow-1][outIdx]);

        const saleValue = diff * price;
        const costValue = diff * cost;
        const profit = saleValue - costValue;

        totalSold += saleValue;
        totalCOGS += costValue;
        netProfit += profit;

        // Actualizar Producto
        prodSheet.getRange(foundRow, stockIdx + 1).setValue(physStock);
        prodSheet.getRange(foundRow, earnedIdx + 1).setValue(earned + profit);
        prodSheet.getRange(foundRow, outIdx + 1).setValue(outs + diff);

        // Registrar Salida
        getSheet("Outputs").appendRow([
          "OUT-" + Utilities.getUuid(),
          c.productId,
          prodData[foundRow-1][prodHeaders.indexOf("name")],
          diff,
          price,
          saleValue,
          new Date().toISOString(),
          shift
        ]);
      }
    }
  });

  // REPARTO DE SOBRES
  // 1. Devolver el Costo de lo vendido al Sobre 4 (Capital)
  updateEnvelopeBalance("ENV4", totalCOGS);

  // 2. Dividir la utilidad en 3 partes para ENV1, ENV2, ENV3
  const part = netProfit / 3;
  updateEnvelopeBalance("ENV1", part);
  updateEnvelopeBalance("ENV2", part);
  updateEnvelopeBalance("ENV3", part);

  // Registrar Cierre
  getSheet("Closings").appendRow([
    "CLS-" + Utilities.getUuid(),
    new Date().toISOString(),
    totalSold,
    netProfit,
    totalCOGS
  ]);

  return { success: true, totalSold, netProfit, totalCOGS };
}

