function doPost(e) {
  let params;
  try {
    params = JSON.parse(e.postData.contents);
  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({error: "Invalid JSON format"})).setMimeType(ContentService.MimeType.JSON);
  }

  const action = params.action;
  const data = params.data;

  let result;
  try {
    switch(action) {
      // Obtención de datos
      case 'getProducts': result = getSheetData("Products"); break;
      case 'getEnvelopes': result = getSheetData("Envelopes"); break;
      case 'getEnvelopeHistory': result = getSheetData("EnvelopeHistory"); break;
      case 'getPurchaseNotes': result = getSheetData("PurchaseNotes"); break;
      case 'getInputs': result = getSheetData("Inputs"); break;
      case 'getOutputs': result = getSheetData("Outputs"); break;
      case 'getClosings': result = getSheetData("Closings"); break;
      case 'getPriceHistory': result = getSheetData("PriceHistory"); break;

      // Guardado y Actualización
      case 'saveProduct': result = saveProduct(data); break;
      case 'saveEnvelope': result = saveEnvelope(data); break;
      case 'savePurchaseNote': result = savePurchaseNote(data); break;
      case 'saveOutput': result = saveOutput(data); break;
      case 'saveClosing': result = saveClosing(data); break;
      case 'updateNoteStatus': result = updateNoteStatus(data.id, data.status); break;
      case 'updateWithdrawal': result = updateWithdrawal(data); break;

      // Operaciones especiales
      case 'withdrawEnvelope': result = withdrawEnvelope(data); break;
      case 'processPhysicalCount': result = processPhysicalCount(data.counts, data.shift); break;

      // Eliminación
      case 'deleteProduct': result = deleteProduct(data); break;
      case 'deleteInput': result = deleteInput(data); break;
      case 'deletePurchaseNote': result = deletePurchaseNote(data); break;
      case 'deleteWithdrawal': result = deleteWithdrawal(data); break;

      case 'setup': result = setupSheet(); break;
      default: throw new Error("Acción no reconocida: " + action);
    }
    return ContentService.createTextOutput(JSON.stringify(result)).setMimeType(ContentService.MimeType.JSON);
  } catch (error) {
    return ContentService.createTextOutput(JSON.stringify({error: error.toString()})).setMimeType(ContentService.MimeType.JSON);
  }
}

// --- LOGICA DE NEGOCIO ---

function saveProduct(p) {
  const headers = ["id", "code", "name", "grams", "flavor", "costPrice", "salePrice", "stock", "category", "provider", "totalInvested", "totalEarned", "totalInputs", "totalOutputs"];
  return saveToSheet("Products", headers, p, "id");
}

function saveEnvelope(env) {
  const headers = ["id", "name", "balance", "description", "lastResetDate"];
  return saveToSheet("Envelopes", headers, env, "id");
}

function savePurchaseNote(note) {
  const headers = ["id", "date", "provider", "totalAmount", "status", "detailsJson"];

  // Verificamos si es una nota nueva antes de descontar balance
  const isNew = !existsInSheet("PurchaseNotes", note.id, "id");
  const res = saveToSheet("PurchaseNotes", headers, note, "id");

  if (isNew && note.status === 'Paid') {
    updateEnvelopeBalance("ENV4", -Number(note.totalAmount));
  }

  // Actualizar stock solo si es nueva nota
  if (isNew && note.detailsJson) {
    const details = JSON.parse(note.detailsJson);
    const prodSheet = getSheet("Products");
    const prodData = prodSheet.getDataRange().getValues();
    const prodHeaders = prodData[0];

    details.forEach(item => {
      let foundRow = -1;
      for(let i=1; i<prodData.length; i++) {
        if(prodData[i][0].toString() === item.productId.toString()) {
          foundRow = i + 1;
          break;
        }
      }

      if(foundRow > -1) {
        const stockIdx = prodHeaders.indexOf("stock");
        const inputsIdx = prodHeaders.indexOf("totalInputs");
        const investedIdx = prodHeaders.indexOf("totalInvested");

        const currentStock = Number(prodData[foundRow-1][stockIdx] || 0);
        const currentInputs = Number(prodData[foundRow-1][inputsIdx] || 0);
        const currentInvested = Number(prodData[foundRow-1][investedIdx] || 0);

        prodSheet.getRange(foundRow, stockIdx + 1).setValue(currentStock + Number(item.quantity));
        prodSheet.getRange(foundRow, inputsIdx + 1).setValue(currentInputs + Number(item.quantity));
        prodSheet.getRange(foundRow, investedIdx + 1).setValue(currentInvested + Number(item.totalCost));

        getSheet("Inputs").appendRow([
          "INP-" + Utilities.getUuid(),
          item.productId,
          item.productName,
          item.quantity,
          item.unitCost,
          item.totalCost,
          note.date,
          note.provider,
          note.id,
          note.status
        ]);
      }
    });
  }

  return res;
}

function processPhysicalCount(counts, shift) {
  const prodSheet = getSheet("Products");
  const prodData = prodSheet.getDataRange().getValues();
  const prodHeaders = prodData[0];

  let totalSold = 0;
  let totalCOGS = 0;
  let netProfit = 0;

  counts.forEach(c => {
    let foundRow = -1;
    for(let i=1; i<prodData.length; i++) {
      if(prodData[i][0].toString() === c.productId.toString()) {
        foundRow = i+1;
        break;
      }
    }

    if(foundRow > -1) {
      const stockIdx = prodHeaders.indexOf("stock");
      const saleIdx = prodHeaders.indexOf("salePrice");
      const costIdx = prodHeaders.indexOf("costPrice");
      const earnedIdx = prodHeaders.indexOf("totalEarned");
      const outIdx = prodHeaders.indexOf("totalOutputs");

      const sysStock = Number(prodData[foundRow-1][stockIdx] || 0);
      const physStock = Number(c.physicalCount);
      const diff = sysStock - physStock;

      if(diff > 0) {
        const cost = Number(prodData[foundRow-1][costIdx] || 0);
        const price = Number(prodData[foundRow-1][saleIdx] || 0);
        const earned = Number(prodData[foundRow-1][earnedIdx] || 0);
        const outs = Number(prodData[foundRow-1][outIdx] || 0);

        const saleValue = diff * price;
        const costValue = diff * cost;
        const profit = saleValue - costValue;

        totalSold += saleValue;
        totalCOGS += costValue;
        netProfit += profit;

        prodSheet.getRange(foundRow, stockIdx + 1).setValue(physStock);
        prodSheet.getRange(foundRow, earnedIdx + 1).setValue(earned + profit);
        prodSheet.getRange(foundRow, outIdx + 1).setValue(outs + diff);

        getSheet("Outputs").appendRow([
          "OUT-" + Utilities.getUuid(),
          c.productId,
          prodData[foundRow-1][prodHeaders.indexOf("name")],
          diff,
          price,
          saleValue,
          new Date().toISOString(),
          shift || "Corte Diario"
        ]);
      }
    }
  });

  // Reparto automático de dinero (Solo si hay utilidad positiva)
  updateEnvelopeBalance("ENV4", totalCOGS);
  if (netProfit > 0) {
    const part = netProfit / 3;
    updateEnvelopeBalance("ENV1", part);
    updateEnvelopeBalance("ENV2", part);
    updateEnvelopeBalance("ENV3", part);
  }

  getSheet("Closings").appendRow([
    "CLS-" + Utilities.getUuid(),
    new Date().toISOString(),
    totalSold,
    netProfit,
    totalCOGS
  ]);

  return { success: true, totalSold, netProfit, totalCOGS };
}

function updateEnvelopeBalance(id, amount) {
  const sheet = getSheet("Envelopes");
  const data = sheet.getDataRange().getValues();
  for(let i=1; i<data.length; i++) {
    if(data[i][0].toString() === id.toString()) {
      const current = Number(data[i][2] || 0);
      sheet.getRange(i+1, 3).setValue(current + amount);
      if(amount < 0 && id !== "ENV4") {
        sheet.getRange(i+1, 5).setValue(new Date().toISOString());
      }
      return true;
    }
  }
  return false;
}

function withdrawEnvelope(w) {
  const headers = ["id", "envelopeId", "envelopeName", "amount", "startDate", "endDate", "durationText", "notes"];
  const res = saveToSheet("EnvelopeHistory", headers, w, "id");
  updateEnvelopeBalance(w.envelopeId, -Number(w.amount));
  return res;
}

function updateWithdrawal(w) {
  const headers = ["id", "envelopeId", "envelopeName", "amount", "startDate", "endDate", "durationText", "notes"];
  const historySheet = getSheet("EnvelopeHistory");
  const values = historySheet.getDataRange().getValues();
  let oldAmount = 0;
  let foundRow = -1;

  for(let i=1; i<values.length; i++) {
    if(values[i][0].toString() === w.id.toString()) {
      oldAmount = Number(values[i][3]);
      foundRow = i + 1;
      break;
    }
  }

  if (foundRow > -1) {
    const diff = oldAmount - Number(w.amount);
    updateEnvelopeBalance(w.envelopeId, diff);
    return saveToSheet("EnvelopeHistory", headers, w, "id");
  }
  return {error: "Withdrawal not found"};
}

// --- UTILIDADES DE PERSISTENCIA ---

function existsInSheet(name, targetId, key) {
  const sheet = getSheet(name);
  const data = sheet.getDataRange().getValues();
  if (data.length <= 1) return false;
  for(let i=1; i<data.length; i++) {
    if(data[i][0].toString() === targetId.toString()) return true;
  }
  return false;
}

function saveToSheet(name, headers, obj, key) {
  const sheet = getSheet(name);
  const data = sheet.getDataRange().getValues();
  if (data.length === 0 || data[0][0] !== headers[0]) {
    sheet.clear();
    sheet.appendRow(headers);
  }

  const rowData = headers.map(h => obj[h] !== undefined ? obj[h] : "");
  const targetId = obj[key].toString();
  const values = sheet.getDataRange().getValues();
  let found = -1;
  for(let i=1; i<values.length; i++) {
    if(values[i][0].toString() === targetId) { found = i+1; break; }
  }

  if(found > -1) sheet.getRange(found, 1, 1, headers.length).setValues([rowData]);
  else sheet.appendRow(rowData);
  return {success: true};
}

function getSheetData(name) {
  const sheet = getSheet(name);
  const values = sheet.getDataRange().getValues();
  if (values.length <= 1) return [];
  const headers = values[0];
  return values.slice(1).map(row => {
    let obj = {};
    headers.forEach((h, i) => {
      let val = row[i];
      if (val instanceof Date) val = val.toISOString();
      obj[h] = val;
    });
    return obj;
  });
}

function getSheet(name) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  let sheet = ss.getSheetByName(name);
  if (!sheet) sheet = ss.insertSheet(name);
  return sheet;
}

function deleteRow(sheetName, id) {
  const sheet = getSheet(sheetName);
  const data = sheet.getDataRange().getValues();
  for(let i=1; i<data.length; i++) {
    if(data[i][0].toString() === id.toString()) {
      sheet.deleteRow(i+1);
      break;
    }
  }
}

function deleteProduct(id) { deleteRow("Products", id); return {success: true}; }
function deleteInput(id) { deleteRow("Inputs", id); return {success: true}; }
function deletePurchaseNote(id) { deleteRow("PurchaseNotes", id); return {success: true}; }

function deleteWithdrawal(id) { 
  const historySheet = getSheet("EnvelopeHistory");
  const data = historySheet.getDataRange().getValues();
  for(let i=1; i<data.length; i++) {
    if(data[i][0].toString() === id.toString()) {
      const envId = data[i][1];
      const amount = Number(data[i][3]);
      updateEnvelopeBalance(envId, amount);
      historySheet.deleteRow(i+1);
      break;
    }
  }
  return {success: true}; 
}

function updateNoteStatus(id, status) {
  const sheet = getSheet("PurchaseNotes");
  const data = sheet.getDataRange().getValues();
  for(let i=1; i<data.length; i++) {
    if(data[i][0].toString() === id.toString()) {
      const currentStatus = data[i][4];
      if (currentStatus !== 'Paid' && status === 'Paid') {
        updateEnvelopeBalance("ENV4", -Number(data[i][3] || 0));
      }
      sheet.getRange(i+1, 5).setValue(status);
      break;
    }
  }
  return {success: true};
}

function setupSheet() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheets = ["Products", "Envelopes", "Inputs", "Outputs", "Closings", "PurchaseNotes", "EnvelopeHistory", "PriceHistory"];
  sheets.forEach(s => getSheet(s));

  // Sobres Iniciales
  const envSheet = getSheet("Envelopes");
  if (envSheet.getLastRow() <= 1) {
    const initialEnvelopes = [
      ["ENV1", "Sobre 1 - Operación", 0, "Utilidad para gastos operativos 1.", new Date().toISOString()],
      ["ENV2", "Sobre 2 - Operación", 0, "Utilidad para gastos operativos 2.", new Date().toISOString()],
      ["ENV3", "Sobre 3 - Operación", 0, "Utilidad para gastos operativos 3.", new Date().toISOString()],
      ["ENV4", "Sobre 4 - Capital", 0, "Bóveda sagrada de capital para resurtido.", new Date().toISOString()],
    ];
    envSheet.getRange(1, 1, 1, 5).setValues([["id", "name", "balance", "description", "lastResetDate"]]);
    envSheet.getRange(2, 1, initialEnvelopes.length, 5).setValues(initialEnvelopes);
  }
  return {success: true};
}

function saveOutput(o) {
