function existsInSheet(name, targetId, key) {
  const sheet = getSheet(name);
  const data = sheet.getDataRange().getValues();
  if (data.length <= 1) return false;
  for(let i=1; i<data.length; i++) {
    if(data[i][0].toString() === targetId.toString()) return true;
  }
  return false;
}

function saveToSheet(name, headers, obj, key) {
  const sheet = getSheet(name);
  const values = sheet.getDataRange().getValues();

  if (values.length === 0 || (values.length === 1 && values[0][0] === "")) {
    sheet.clear();
    sheet.appendRow(headers);
  }

  const rowData = headers.map(h => obj[h] !== undefined ? obj[h] : "");
  const targetId = obj[key].toString();
  let found = -1;
  for(let i=1; i<values.length; i++) {
    if(values[i][0].toString() === targetId) { found = i+1; break; }
  }

  if(found > -1) sheet.getRange(found, 1, 1, headers.length).setValues([rowData]);
  else sheet.appendRow(rowData);
  return {success: true};
}

function getSheetData(name) {
  const sheet = getSheet(name);
  const values = sheet.getDataRange().getValues();
  if (values.length <= 1) return [];
  const headers = values[0];
  return values.slice(1).map(row => {
    let obj = {};
    headers.forEach((h, i) => {
      let val = row[i];
      if (val instanceof Date) val = val.toISOString();
      obj[h] = val;
    });
    return obj;
  });
}

function getSheet(name) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  let sheet = ss.getSheetByName(name);
  if (!sheet) {
    sheet = ss.insertSheet(name);
  }
  return sheet;
}

function deleteRow(sheetName, id) {
  const sheet = getSheet(sheetName);
  const data = sheet.getDataRange().getValues();
  for(let i=1; i<data.length; i++) {
    if(data[i][0].toString() === id.toString()) {
      sheet.deleteRow(i+1);
      return true;
    }
  }
  return false;
}

function deleteProduct(id) { deleteRow("Products", id); return {success: true}; }
function deleteInput(id) { deleteRow("Inputs", id); return {success: true}; }
function deletePurchaseNote(id) { deleteRow("PurchaseNotes", id); return {success: true}; }

function deleteWithdrawal(id) { 
  const historySheet = getSheet("EnvelopeHistory");
  const data = historySheet.getDataRange().getValues();
  for(let i=1; i<data.length; i++) {
    if(data[i][0].toString() === id.toString()) {
      const envId = data[i][1];
      const amount = Number(data[i][3]);
      updateEnvelopeBalance(envId, amount);
      historySheet.deleteRow(i+1);
      break;
    }
  }
  return {success: true}; 
}

function updateNoteStatus(id, status) {
  const sheet = getSheet("PurchaseNotes");
  const data = sheet.getDataRange().getValues();
  for(let i=1; i<data.length; i++) {
    if(data[i][0].toString() === id.toString()) {
      const currentStatus = data[i][4];
      if (currentStatus !== 'Paid' && status === 'Paid') {
        updateEnvelopeBalance("ENV4", -Number(data[i][3] || 0));
      }
      sheet.getRange(i+1, 5).setValue(status);
      break;
    }
  }
  return {success: true};
}

function setupSheet() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheets = ["Products", "Envelopes", "Inputs", "Outputs", "Closings", "PurchaseNotes", "EnvelopeHistory", "PriceHistory"];
  sheets.forEach(s => getSheet(s));

  const envSheet = getSheet("Envelopes");
  const envData = envSheet.getDataRange().getValues();
  if (envData.length <= 1 || envData[1][0] === "") {
    const initialEnvelopes = [
      ["ENV1", "Sobre 1 - Operación", 0, "Utilidad para gastos operativos 1.", new Date().toISOString()],
      ["ENV2", "Sobre 2 - Operación", 0, "Utilidad para gastos operativos 2.", new Date().toISOString()],
      ["ENV3", "Sobre 3 - Operación", 0, "Utilidad para gastos operativos 3.", new Date().toISOString()],
      ["ENV4", "Sobre 4 - Capital", 0, "Bóveda sagrada de capital para resurtido.", new Date().toISOString()],
    ];
    envSheet.getRange(1, 1, 1, 5).setValues([["id", "name", "balance", "description", "lastResetDate"]]);
    envSheet.getRange(2, 1, initialEnvelopes.length, 5).setValues(initialEnvelopes);
  }
  return {success: true};
}

function saveOutput(o) {
  const headers = ["id", "productId", "productName", "quantity", "salePrice", "totalSale", "date", "shift"];
  return saveToSheet("Outputs", headers, o, "id");
}

function saveClosing(c) {
  const headers = ["id", "date", "totalSold", "netProfit", "cogs"];
  return saveToSheet("Closings", headers, c, "id");
}

import React, { useState, useRef, useEffect } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { Camera, Check, AlertCircle, Loader2, ArrowLeft } from 'lucide-react';
import { processTicketWithGemini } from '../services/geminiService';
import { dataService } from '../services/dataService';

const ProductRegistration: React.FC = () => {
  const location = useLocation();
  const navigate = useNavigate();
  const [isLoading, setIsLoading] = useState(false);
  const [success, setSuccess] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const editMode = !!location.state?.product;

  const [formData, setFormData] = useState({
    id: '',
    code: '',
    name: '',
    grams: '',
    flavor: '',
    costPrice: '',
    salePrice: '',
    stock: '',
    category: 'General',
    provider: ''
  });

  useEffect(() => {
    if (location.state?.product) {
      const p = location.state.product;
      setFormData({
        id: p.id,
        code: p.code,
        name: p.name,
        grams: p.grams,
        flavor: p.flavor,
        costPrice: p.costPrice.toString(),
        salePrice: p.salePrice.toString(),
        stock: p.stock.toString(),
        category: p.category || 'General',
        provider: p.provider || ''
      });
    }
  }, [location.state]);

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsLoading(true);
    setError(null);

    const reader = new FileReader();
    reader.onload = async (event) => {
      try {
        const base64 = event.target?.result as string;
        const results = await processTicketWithGemini(base64);

        if (results.length > 0) {
          const item = results[0];
          setFormData(prev => ({
            ...prev,
            code: item.code || prev.code,
            name: item.name,
            grams: item.grams || prev.grams,
            flavor: item.flavor || prev.flavor,
            costPrice: item.costPrice.toString(),
            salePrice: (item.salePrice || item.costPrice * 1.3).toFixed(2),
            stock: item.quantity.toString()
          }));
        }
      } catch (err: any) {
        setError(err.message || 'Error procesando OCR');
      } finally {
        setIsLoading(false);
      }
    };
    reader.readAsDataURL(file);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    try {
      const allProducts = dataService.getProducts();
      const existingProduct = editMode ? allProducts.find(p => p.id === formData.id) : null;

      const product = {
        id: editMode ? formData.id : Math.random().toString(36).substr(2, 9),
        code: formData.code,
        name: formData.name,
        grams: formData.grams,
        flavor: formData.flavor,
        costPrice: parseFloat(formData.costPrice),
        salePrice: parseFloat(formData.salePrice),
        stock: parseInt(formData.stock),
        category: formData.category,
        provider: formData.provider,
        totalInvested: editMode && existingProduct ? existingProduct.totalInvested : (parseFloat(formData.costPrice) * parseInt(formData.stock)),
        totalEarned: editMode && existingProduct ? existingProduct.totalEarned : 0,
        totalInputs: editMode && existingProduct ? existingProduct.totalInputs : parseInt(formData.stock),
        totalOutputs: editMode && existingProduct ? existingProduct.totalOutputs : 0
      };

      const res = await dataService.saveProduct(product);
      if (res && !res.error) {
        setSuccess(true);
        if (editMode) {
          setTimeout(() => navigate('/inventory'), 1500);
        } else {
          setTimeout(() => setSuccess(false), 3000);
          setFormData({ id: '', code: '', name: '', grams: '', flavor: '', costPrice: '', salePrice: '', stock: '', category: 'General', provider: '' });
        }
      } else {
        throw new Error(res?.error || "Error al guardar");
      }
    } catch (err: any) {
      setError(err.message || "No se pudo guardar el producto.");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="max-w-2xl mx-auto animate-in fade-in slide-in-from-bottom-4 duration-500">
      <div className="flex items-center justify-between mb-10">
        <div className="flex items-center space-x-4">
          {editMode && (
            <button onClick={() => navigate('/inventory')} className="p-3 bg-white hover:bg-red-50 text-red-600 rounded-2xl transition-all border border-red-50 shadow-sm active:scale-95">
              <ArrowLeft size={24} />
            </button>
          )}
          <div>
            <h2 className="text-3xl font-black text-blue-900 tracking-tight">
              {editMode ? 'Editar Artículo' : 'Nuevo Producto'}
            </h2>
            <p className="text-slate-500 font-medium">
              {editMode ? `Actualizando ${formData.name}` : 'Registra productos o usa IA con foto.'}
            </p>
          </div>
        </div>
        {!editMode && (
          <button 
            onClick={() => fileInputRef.current?.click()}
            disabled={isLoading}
            className="flex items-center space-x-2 bg-blue-900 text-white px-8 py-4 rounded-2xl hover:bg-blue-800 transition-all shadow-xl shadow-blue-900/20 active:scale-95 disabled:opacity-50 font-black uppercase text-xs tracking-widest"
          >
            {isLoading ? <Loader2 className="animate-spin" size={20} /> : <Camera size={20} />}
            <span>IA Foto OCR</span>
          </button>
        )}
        <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileUpload} />
      </div>

      {error && (
        <div className="mb-8 p-5 bg-red-50 border-2 border-red-100 text-red-600 rounded-[2rem] flex items-center space-x-3 font-bold">
          <AlertCircle size={24} />
          <span>{error}</span>
        </div>
      )}

      <form onSubmit={handleSubmit} className="bg-white p-10 rounded-[2.5rem] border border-blue-100 shadow-2xl shadow-blue-900/5 space-y-8">
        <div className="grid grid-cols-2 gap-8">
          <div className="space-y-3">
            <label className="text-xs font-black text-blue-900 uppercase tracking-widest block px-1">Código de Barras</label>
            <input 
              required
              value={formData.code}
              onChange={(e) => setFormData({...formData, code: e.target.value})}
              className="w-full px-5 py-4 bg-blue-50/30 border-2 border-transparent rounded-2xl focus:bg-white focus:border-blue-500 focus:outline-none transition-all font-bold text-slate-800"
              placeholder="Ej. 750100..."
            />
          </div>
          <div className="space-y-3">
            <label className="text-xs font-black text-blue-900 uppercase tracking-widest block px-1">Categoría</label>
            <select 
              value={formData.category}
              onChange={(e) => setFormData({...formData, category: e.target.value})}
              className="w-full px-5 py-4 bg-blue-50/30 border-2 border-transparent rounded-2xl focus:bg-white focus:border-blue-500 focus:outline-none transition-all font-bold text-slate-800"
            >
              <option>General</option>
              <option>Abarrotes</option>
              <option>Snacks</option>
              <option>Bebidas</option>
              <option>Lácteos</option>
              <option>Higiene</option>
              <option>Farmacia</option>
            </select>
          </div>
        </div>

        <div className="space-y-3">
          <label className="text-xs font-black text-blue-900 uppercase tracking-widest block px-1">Nombre Comercial</label>
          <input 
            required
            value={formData.name}
            onChange={(e) => setFormData({...formData, name: e.target.value})}
            className="w-full px-5 py-4 bg-blue-50/30 border-2 border-transparent rounded-2xl focus:bg-white focus:border-blue-500 focus:outline-none transition-all font-bold text-slate-800"
            placeholder="Ej. Coca-Cola Original"
          />
        </div>

        <div className="grid grid-cols-2 gap-8">
          <div className="space-y-3">
            <label className="text-xs font-black text-blue-900 uppercase tracking-widest block px-1">Proveedor Oficial</label>
            <input 
              value={formData.provider}
              onChange={(e) => setFormData({...formData, provider: e.target.value})}
              className="w-full px-5 py-4 bg-blue-50/30 border-2 border-transparent rounded-2xl focus:bg-white focus:border-blue-500 focus:outline-none transition-all font-bold text-slate-800"
              placeholder="Ej. PepsiCo / Marinela"
            />
          </div>
          <div className="space-y-3">
            <label className="text-xs font-black text-blue-900 uppercase tracking-widest block px-1">Presentación (G/ML)</label>
            <input 
              value={formData.grams}
              onChange={(e) => setFormData({...formData, grams: e.target.value})}
              className="w-full px-5 py-4 bg-blue-50/30 border-2 border-transparent rounded-2xl focus:bg-white focus:border-blue-500 focus:outline-none transition-all font-bold text-slate-800"
              placeholder="Ej. 600ml"
            />
          </div>
        </div>

        <div className="grid grid-cols-3 gap-8 pt-6 border-t border-blue-50">
          <div className="space-y-3">
            <label className="text-xs font-black text-blue-900 uppercase tracking-widest block px-1">Costo ($)</label>
            <input 
              required
              type="number" step="0.01"
              value={formData.costPrice}
              onChange={(e) => setFormData({...formData, costPrice: e.target.value})}
              className="w-full px-5 py-4 bg-red-50/50 border-2 border-transparent rounded-2xl focus:bg-white focus:border-red-500 focus:outline-none transition-all font-black text-red-600 text-lg"
            />
          </div>
          <div className="space-y-3">
            <label className="text-xs font-black text-blue-900 uppercase tracking-widest block px-1">Venta ($)</label>
            <input 
              required
              type="number" step="0.01"
              value={formData.salePrice}
              onChange={(e) => setFormData({...formData, salePrice: e.target.value})}
              className="w-full px-5 py-4 bg-blue-50/50 border-2 border-transparent rounded-2xl focus:bg-white focus:border-blue-500 focus:outline-none transition-all font-black text-blue-600 text-lg"
            />
          </div>
          <div className="space-y-3">
            <label className="text-xs font-black text-blue-900 uppercase tracking-widest block px-1">Stock {editMode ? 'Actual' : 'Inicial'}</label>
            <input 
              required
              type="number"
              value={formData.stock}
              onChange={(e) => setFormData({...formData, stock: e.target.value})}
              className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent rounded-2xl focus:bg-white focus:border-slate-800 focus:outline-none transition-all font-black text-slate-800 text-lg"
            />
          </div>
        </div>

        <button 
          type="submit"
          disabled={isLoading}
          className="w-full bg-blue-600 text-white font-black py-6 rounded-2xl hover:bg-blue-700 transition-all shadow-xl shadow-blue-900/20 active:scale-95 flex items-center justify-center space-x-3 disabled:opacity-50 text-xl"
        >
          {success ? <Check size={32} /> : <span>{editMode ? 'Guardar Cambios' : 'Registrar en Inventario'}</span>}
        </button>
      </form>
    </div>
  );
};

export default ProductRegistration;

import { Product, InputTransaction, OutputTransaction, DailyClosing, PriceHistory, PurchaseNote, Envelope, EnvelopeWithdrawal } from "../types";

// URL actualizada de Apps Script
const APPS_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbwjOo5gxhhD__qjMwbS24UTJ-TYJbwe6-_xkVoJZ92RxXiooGhRdoc8TeRTp8wWdWgFrQ/exec";

const callApi = async (action: string, data: any = null) => {
  if (!APPS_SCRIPT_URL) {
    console.error("No se ha configurado la URL de Apps Script.");
    return null;
  }
  try {
    const response = await fetch(APPS_SCRIPT_URL, {
      method: 'POST',
      mode: 'cors',
      headers: { 'Content-Type': 'text/plain' },
      body: JSON.stringify({ action, data })
    });

    if (!response.ok) {
      throw new Error(`Error HTTP: ${response.status}`);
    }

    const result = await response.json();
    if (result && result.error) {
      console.warn(`Error de API en ${action}:`, result.error);
      return result;
    }
    return result;
  } catch (error) {
    console.error(`Error de red en API (${action}):`, error);
    return null;
  }
};

export const dataService = {
  _products: [] as Product[],
  _envelopes: [] as Envelope[],
  _envelopeHistory: [] as EnvelopeWithdrawal[],
  _purchaseNotes: [] as PurchaseNote[],
  _inputs: [] as InputTransaction[],
  _outputs: [] as OutputTransaction[],
  _closings: [] as DailyClosing[],
  _priceHistory: [] as PriceHistory[],

  async fetchAll() {
    try {
      const results = await Promise.all([
        callApi('getProducts'),
        callApi('getEnvelopes'),
        callApi('getEnvelopeHistory'),
        callApi('getPurchaseNotes'),
        callApi('getInputs'),
        callApi('getOutputs'),
        callApi('getClosings'),
        callApi('getPriceHistory'),
      ]);

      if (results[0] && !results[0].error) this._products = results[0];
      if (results[1] && !results[1].error) this._envelopes = results[1];
      if (results[2] && !results[2].error) this._envelopeHistory = results[2];
      if (results[3] && !results[3].error) this._purchaseNotes = results[3];
      if (results[4] && !results[4].error) this._inputs = results[4];
      if (results[5] && !results[5].error) this._outputs = results[5];
      if (results[6] && !results[6].error) this._closings = results[6];
      if (results[7] && !results[7].error) this._priceHistory = results[7];

      return true;
    } catch (e) { 
      console.error("Error al obtener todos los datos:", e); 
      return false;
    }
  },

  getProducts() { return this._products; },
  getEnvelopes() { return this._envelopes; },
  getEnvelopeHistory() { return this._envelopeHistory; },
  getPurchaseNotes() { return this._purchaseNotes; },
  getInputs() { return this._inputs; },
  getOutputs() { return this._outputs; },
  getClosings() { return this._closings; },
  getPriceHistory() { return this._priceHistory; },

  async setup() {
    return await callApi('setup');
  },

  async saveEnvelope(e: Envelope) { 
    const res = await callApi('saveEnvelope', e); 
    if (res && res.success) {
      await this.fetchAll(); 
      return true;
    }
    return false;
  },

  async saveProduct(p: Product) { 
    const res = await callApi('saveProduct', p); 
    if (res && res.success) await this.fetchAll(); 
    return res;
  },

  async withdrawEnvelope(withdrawal: EnvelopeWithdrawal) { 
    const res = await callApi('withdrawEnvelope', withdrawal); 
    if (res && res.success) await this.fetchAll(); 
    return res;
  },

  async deleteWithdrawal(id: string) { 
    const res = await callApi('deleteWithdrawal', id); 
    if (res && res.success) await this.fetchAll(); 
    return res;
  },

  async updateWithdrawal(withdrawal: EnvelopeWithdrawal) { 
    const res = await callApi('updateWithdrawal', withdrawal); 
    if (res && res.success) await this.fetchAll(); 
    return res;
  },

  async deleteInput(id: string) { await callApi('deleteInput', id); await this.fetchAll(); },
  async deletePurchaseNote(id: string) { await callApi('deletePurchaseNote', id); await this.fetchAll(); },
  async deleteProduct(id: string) { await callApi('deleteProduct', id); await this.fetchAll(); },
  async updateNoteStatus(id: string, status: string) { await callApi('updateNoteStatus', { id, status }); await this.fetchAll(); },

  async processPhysicalCount(counts: any[], shift: string) { 
    const res = await callApi('processPhysicalCount', { counts, shift }); 
    if (res && res.success) await this.fetchAll(); 
    return res; 
  },

  async sync() { 
    const res = await this.fetchAll(); 
    return { success: res }; 
  },

  async getDashboardData() {
    await this.fetchAll();
    const envelopes = this._envelopes;
    const util1 = Number(envelopes.find(e => e.id === 'ENV1')?.balance || 0);
    const util2 = Number(envelopes.find(e => e.id === 'ENV2')?.balance || 0);
    const util3 = Number(envelopes.find(e => e.id === 'ENV3')?.balance || 0);
    const capital = Number(envelopes.find(e => e.id === 'ENV4')?.balance || 0);
    const totalUtility = util1 + util2 + util3;

    return {
      envelopes,
      profitVsCapital: [
        { name: 'Utilidad Acum.', value: totalUtility },
        { name: 'Capital Invertido', value: capital }
      ],
      topVolume: [...this._products].sort((a, b) => (b.totalOutputs || 0) - (a.totalOutputs || 0)).slice(0, 5).map(p => ({ name: p.name, volume: p.totalOutputs || 0 })),
      topProfit: [...this._products].sort((a, b) => (b.totalEarned || 0) - (a.totalEarned || 0)).slice(0, 5).map(p => ({ name: p.name, profit: p.totalEarned || 0 }))
    };
  },

  async saveRestockNote(note: PurchaseNote) { 
    const res = await callApi('savePurchaseNote', note); 
    if (res && res.success) await this.fetchAll(); 
    return res; 
  },

  async saveOutput(output: OutputTransaction) { 
    const res = await callApi('saveOutput', output); 
    if (res && res.success) await this.fetchAll(); 
    return res; 
  },

  async saveClosing(closing: DailyClosing) { 
    const res = await callApi('saveClosing', closing); 
    if (res && res.success) await this.fetchAll(); 
    return res; 
  }
};

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { Calendar, ArrowUpCircle, ArrowDownCircle, Search, ClipboardList, Wallet, CheckCircle, Clock, Trash2, RefreshCw } from 'lucide-react';
import { dataService } from '../services/dataService';
import { InputTransaction, DailyClosing, PriceHistory, PurchaseNote } from '../types';

const HistoryView: React.FC = () => {
  const [tab, setTab] = useState<'Inputs' | 'Outputs' | 'Audit' | 'Debts'>('Inputs');
  const [inputs, setInputs] = useState<InputTransaction[]>([]);
  const [closings, setClosings] = useState<DailyClosing[]>([]);
  const [priceHistory, setPriceHistory] = useState<PriceHistory[]>([]);
  const [purchaseNotes, setPurchaseNotes] = useState<PurchaseNote[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);

  const refreshHistory = useCallback(async () => {
    await dataService.fetchAll();
    setInputs([...dataService.getInputs()]);
    setClosings([...dataService.getClosings()]);
    setPriceHistory([...dataService.getPriceHistory()]);
    setPurchaseNotes([...dataService.getPurchaseNotes()]);
  }, []);

  useEffect(() => {
    refreshHistory();
  }, [refreshHistory]);

  const handleMarkAsPaid = async (noteId: string) => {
    if (confirm("¿Marcar esta nota como PAGADA?")) {
      await dataService.updateNoteStatus(noteId, 'Paid');
      await refreshHistory();
    }
  };

  const handleDeleteInput = async (id: string, name: string, qty: number) => {
    if (confirm(`¿Eliminar entrada de "${name}"? Se restarán ${qty} unidades del stock actual.`)) {
      setIsProcessing(true);
      await dataService.deleteInput(id);
      await refreshHistory();
      setIsProcessing(false);
    }
  };

  const handleDeleteNote = async (id: string, provider: string) => {
    if (confirm(`¿Eliminar nota de "${provider}"? Esto no afectará el stock, solo el registro financiero.`)) {
      setIsProcessing(true);
      await dataService.deletePurchaseNote(id);
      await refreshHistory();
      setIsProcessing(false);
