/**
 * tiendita - Backend API v6.0
 * LockService integrado y lógica de negocio unificada.
 */

function doPost(e) {
  const lock = LockService.getScriptLock();
  try {
    lock.waitLock(30000);
    let params;
    try {
      params = JSON.parse(e.postData.contents);
    } catch (err) {
      return createResponse({error: "JSON inválido"});
    }

    const action = params.action;
    const data = params.data;
    let result;

    switch(action) {
      case 'getProducts': result = getSheetData("Products"); break;
      case 'getEnvelopes': result = getSheetData("Envelopes"); break;
      case 'getEnvelopeHistory': result = getSheetData("EnvelopeHistory"); break;
      case 'getPurchaseNotes': result = getSheetData("PurchaseNotes"); break;
      case 'getInputs': result = getSheetData("Inputs"); break;
      case 'getOutputs': result = getSheetData("Outputs"); break;
      case 'getClosings': result = getSheetData("Closings"); break;
      case 'getPriceHistory': result = getSheetData("PriceHistory"); break;
      case 'saveProduct': result = saveProduct(data); break;
      case 'saveEnvelope': result = saveEnvelope(data); break;
      case 'savePurchaseNote': result = savePurchaseNote(data); break;
      case 'saveOutputBatch': result = saveOutputBatch(data); break;
      case 'saveClosing': result = saveClosing(data); break;
      case 'updateNoteStatus': result = updateNoteStatus(data.id, data.status); break;
      case 'withdrawEnvelope': result = withdrawEnvelope(data); break;
      case 'processPhysicalCount': result = processPhysicalCount(data.counts, data.shift); break;
      case 'deleteProduct': result = deleteProduct(data); break;
      case 'deleteInput': result = deleteInput(data); break;
      case 'deletePurchaseNote': result = deletePurchaseNote(data); break;
      case 'deleteWithdrawal': result = deleteWithdrawal(data); break;
      case 'setup': result = setupSheet(); break;
      default: throw new Error("Acción no reconocida: " + action);
    }
    return createResponse(result);
  } catch (error) {
    return createResponse({error: error.toString()});
  } finally {
    lock.releaseLock();
  }
}

function createResponse(data) {
  return ContentService.createTextOutput(JSON.stringify(data)).setMimeType(ContentService.MimeType.JSON);
}

function saveOutputBatch(outputs) {
  if (!Array.isArray(outputs)) return {error: "Datos inválidos"};
  const outSheet = getSheet("Outputs");
  const prodSheet = getSheet("Products");
  const prodData = prodSheet.getDataRange().getValues();
  const prodHeaders = prodData[0];

  const stockIdx = prodHeaders.indexOf("stock");
  const earnedIdx = prodHeaders.indexOf("totalEarned");
  const outIdx = prodHeaders.indexOf("totalOutputs");
  const costIdx = prodHeaders.indexOf("costPrice");

  let totalCOGS = 0;
  let totalProfit = 0;

  outputs.forEach(o => {
    // 1. Registrar salida en hoja
    outSheet.appendRow([o.id, o.productId, o.productName, o.quantity, o.salePrice, o.totalSale, o.date, o.shift]);

    // 2. Actualizar Producto (Stock y Ganancia)
    let foundRow = -1;
    for(let i=1; i<prodData.length; i++) {
      if(prodData[i][0].toString() === o.productId.toString()) {
        foundRow = i + 1;
        break;
      }
    }

    if(foundRow > -1) {
      const currentStock = Number(prodData[foundRow-1][stockIdx] || 0);
      const currentEarned = Number(prodData[foundRow-1][earnedIdx] || 0);
      const currentOuts = Number(prodData[foundRow-1][outIdx] || 0);
      const costPrice = Number(prodData[foundRow-1][costIdx] || 0);

      const itemCOGS = o.quantity * costPrice;
      const itemProfit = o.totalSale - itemCOGS;

      totalCOGS += itemCOGS;
      totalProfit += itemProfit;

      prodSheet.getRange(foundRow, stockIdx + 1).setValue(currentStock - o.quantity);
      prodSheet.getRange(foundRow, earnedIdx + 1).setValue(currentEarned + itemProfit);
      prodSheet.getRange(foundRow, outIdx + 1).setValue(currentOuts + o.quantity);
    }
  });

  // 3. Actualizar Sobres (Distribución de dinero)
  updateEnvelopeBalance("ENV4", totalCOGS);
  if (totalProfit > 0) {
    const part = totalProfit / 3;
    updateEnvelopeBalance("ENV1", part);
    updateEnvelopeBalance("ENV2", part);
    updateEnvelopeBalance("ENV3", part);
  }

  return {success: true, totalProfit, totalCOGS};
}

function saveProduct(p) {
  const headers = ["id", "code", "name", "grams", "flavor", "costPrice", "salePrice", "stock", "category", "provider", "totalInvested", "totalEarned", "totalInputs", "totalOutputs"];
  return saveToSheet("Products", headers, p, "id");
}

function saveEnvelope(env) {
  const headers = ["id", "name", "balance", "description", "lastResetDate"];
  return saveToSheet("Envelopes", headers, env, "id");
}

function updateEnvelopeBalance(id, amount) {
  const sheet = getSheet("Envelopes");
  const data = sheet.getDataRange().getValues();
  for(let i=1; i<data.length; i++) {
    if(data[i][0].toString() === id.toString()) {
      const current = Number(data[i][2] || 0);
      sheet.getRange(i+1, 3).setValue(current + amount);
      return true;
    }
  }
  return false;
}

function saveToSheet(name, headers, obj, key) {
  const sheet = getSheet(name);
  const values = sheet.getDataRange().getValues();
  const rowData = headers.map(h => obj[h] !== undefined ? obj[h] : "");
  const targetId = obj[key].toString();
  let found = -1;
  for(let i=1; i<values.length; i++) {
    if(values[i][0].toString() === targetId) { found = i+1; break; }
  }
  if(found > -1) sheet.getRange(found, 1, 1, headers.length).setValues([rowData]);
  else sheet.appendRow(rowData);
  return {success: true};
}

function getSheetData(name) {
  const sheet = getSheet(name);
  const values = sheet.getDataRange().getValues();
  if (values.length <= 1) return [];
  const headers = values[0];
  return values.slice(1).map(row => {
    let obj = {};
    headers.forEach((h, i) => {
      let val = row[i];
      if (val instanceof Date) val = val.toISOString();
      obj[h] = val;
    });
    return obj;
  });
}

function getSheet(name) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  let sheet = ss.getSheetByName(name);
  if (!sheet) sheet = ss.insertSheet(name);
  return sheet;
}

function setupSheet() {
  const sheets = ["Products", "Envelopes", "Inputs", "Outputs", "Closings", "PurchaseNotes", "EnvelopeHistory", "PriceHistory"];
  sheets.forEach(s => getSheet(s));
  return {success: true};
}

function savePurchaseNote(note) {
  const headers = ["id", "date", "provider", "totalAmount", "status", "detailsJson"];
  saveToSheet("PurchaseNotes", headers, note, "id");
  if (note.status === 'Paid') updateEnvelopeBalance("ENV4", -Number(note.totalAmount));
  return {success: true};
}

function saveClosing(c) {
  const headers = ["id", "date", "totalSold", "netProfit", "cogs"];
  return saveToSheet("Closings", headers, c, "id");
}

function updateNoteStatus(id, status) {
  const sheet = getSheet("PurchaseNotes");
  const data = sheet.getDataRange().getValues();
  for(let i=1; i<data.length; i++) {
    if(data[i][0].toString() === id.toString()) {
      if (data[i][4] !== 'Paid' && status === 'Paid') updateEnvelopeBalance("ENV4", -Number(data[i][3]));
      sheet.getRange(i+1, 5).setValue(status);
      break;
    }
  }
  return {success: true};
}

function deleteRow(sheetName, id) {
  const sheet = getSheet(sheetName);
  const data = sheet.getDataRange().getValues();
  for(let i=1; i<data.length; i++) {
    if(data[i][0].toString() === id.toString()) {
      sheet.deleteRow(i+1);
      return true;
    }
  }
  return false;
}

function deleteProduct(id) { deleteRow("Products", id); return {success: true}; }
function deleteInput(id) { deleteRow("Inputs", id); return {success: true}; }
function deletePurchaseNote(id) { deleteRow("PurchaseNotes", id); return {success: true}; }
function deleteWithdrawal(id) { deleteRow("EnvelopeHistory", id); return {success: true}; }
function withdrawEnvelope(w) {
  const headers = ["id", "envelopeId", "envelopeName", "amount", "startDate", "endDate", "durationText", "notes"];
  saveToSheet("EnvelopeHistory", headers, w, "id");
  updateEnvelopeBalance(w.envelopeId, -Number(w.amount));
  return {success: true};
}

