const callApi = async (action: string, data: any = null) => {
  if (!APPS_SCRIPT_URL) {
    console.error("No se ha configurado la URL de Apps Script.");
    return null;
  }
  try {
    const response = await fetch(APPS_SCRIPT_URL, {
      method: 'POST',
      mode: 'cors',
      headers: { 'Content-Type': 'text/plain' },
      body: JSON.stringify({ action, data })
    });

    if (!response.ok) {
      throw new Error(`Error HTTP: ${response.status}`);
    }

    const result = await response.json();
    if (result && result.error) {
      console.warn(`Error de API en ${action}:`, result.error);
      return result;
    }
    return result;
  } catch (error) {
    console.error(`Error de red en API (${action}):`, error);
    return null;
  }
};

