        const phyStock = Number(count.physicalCount);
        const diff = sysStock - phyStock;

        if (diff > 0) {
          const cost = Number(prodData[i][costIdx] || 0);
          const sale = Number(prodData[i][saleIdx] || 0);
          const itemCOGS = diff * cost;
          const itemSaleTotal = diff * sale;
